var NOTES_V2=FIXTURES.NOTES_V2;
var TRANSCRIPTS=FIXTURES.TRANSCRIPTS;
var RUNGRAPH=FIXTURES.RUNGRAPH;
var FINDINGS=FIXTURES.FINDINGS;
var EVIDENCE=FIXTURES.EVIDENCE;
var FIX=FIXTURES.FIX;
