/* ---- the Context PR, as a state machine ---- */

/* ---- the operator's Context PRs ----
   The wizard's last step opens a real one. It is the same object the promoter's lifecycle runs on,
   with one difference that is not cosmetic: a promoter's pull request argues from runs it
   aggregated, and a person's argues from the person. So the checks, the merge, the promotion event
   and the bundle bump are shared, and only the body differs.

   There can be several open at once, because "one concern per pull request" limits what one PR may
   carry, not how many concerns a person may have in flight. They live in session state, like the
   promoter's — nothing here is a new store. */
var RECPRS=[];
S.recprs={};          /* pr id -> {st, done, failed, timers, mergedAt} */
S.prSel=null;

function recprById(pr){for(var i=0;i<RECPRS.length;i++){if(RECPRS[i].pr===pr)return RECPRS[i];}return null;}
/* Who else holds this lineage: a published record, or an open pull request opened before this one.
   RECPRS is newest first, so a higher index was opened earlier and wins the claim. Checking only
   RECORDS is not enough — two pull requests can both run their checks before either merges, and
   without this both reach `passed` and the second publishes a duplicate under a published id. */
function lineageClaim(def){
  var id=def.record.id;
  if(RECORDS.some(function(r){return r.status==="published"&&r.id===id;})) return "published";
  var mine=RECPRS.indexOf(def), claim=null;
  RECPRS.forEach(function(d,j){
    if(d===def||d.record.id!==id||j<=mine) return;
    var st=recprSt(d).st;
    if(st!=="merged"&&st!=="failed") claim=d.pr;
  });
  return claim;
}
function recprSt(def){ return def?(S.recprs[def.pr]||(S.recprs[def.pr]={st:"none",done:0,failed:null,timers:[],mergedAt:null})):null; }
/* the one the tab is showing: what was selected, else the newest still open, else the newest */
function recprCur(){
  if(!RECPRS.length) return null;
  var byId=S.prSel&&S.prSel!=="ctxpr"?recprById(S.prSel):null;
  if(byId) return byId;
  for(var i=0;i<RECPRS.length;i++){ if(recprSt(RECPRS[i]).st!=="merged") return RECPRS[i]; }
  return RECPRS[0];
}
function recprOpenCount(){var n=0;RECPRS.forEach(function(d){var st=recprSt(d).st;if(st!=="merged"&&st!=="closed")n++;});return n;}

/* The next free number on the workspace's main repo, read off the pull requests that exist rather
   than invented, so two open PRs never claim the same one. */
function prNextNumber(){
  var max=0;
  function take(x){var m=/#(\d+)/.exec(String(x||""));if(m&&+m[1]>max)max=+m[1];}
  take(CTXPR.pr); PROPOSALS.forEach(function(q){take(q.pr);}); RECPRS.forEach(function(d){take(d.pr);});
  return max+1;
}
function recprPaint(){ if(route().page==="steering") render(); }
function recprRun(def){ prRun(def,recprSt(def),recprPaint); }
function recprLabel(def){ return prLabel(def,recprSt(def)); }
/* Re-run every check that has one. A pull request that went green five minutes ago may not be green
   now: something else merged, and its evidence moved. Checks are cheap; publishing a wrong record
   is not. */
function prRecheck(def,st){
  for(var i=0;i<def.checks.length;i++){
    var c=def.checks[i];
    if(c.test&&!c.test()){ prStop(st); st.st="failed"; st.failed=i; st.done=i; return false; }
  }
  return true;
}
function recprMerge(pr){
  var def=pr?recprById(pr):recprCur(); if(!def) return;
  var st=recprSt(def);
  if(st.st==="passed"&&!prRecheck(def,st)){
    S.tab.steering="prs"; S.prSel=def.pr; render();
    act("A check that passed no longer does. "+def.pr+" is blocked and nothing was published.","approval");
    return;
  }
  if(st.st!=="passed"){
    act(st.st==="merged"?def.pr+" is already merged.":
        st.st==="failed"?"A check failed. "+def.pr+" cannot merge until the file changes.":
        "Merge is blocked until all "+def.checks.length+" checks pass.");
    return;
  }
  prSet(def,st,"merged"); S.tab.steering="prs"; S.prSel=def.pr; render();
  act("Merged "+def.pr+". promotion_event written, bundle v"+(STEER_BUNDLE.v-1)+" → v"+STEER_BUNDLE.v+" signed, steering_published audited.","gold");
}
/* Closing an unmerged one throws the draft away; closing a merged one would unpublish a record,
   which is a second pull request, not a button. */
function recprDiscard(pr){
  var def=pr?recprById(pr):recprCur(); if(!def) return;
  var st=recprSt(def);
  if(st.st==="merged"){act("It is merged. Taking a published record back out of force is its own pull request.");return;}
  prStop(st); delete S.recprs[def.pr];
  RECPRS.splice(RECPRS.indexOf(def),1);
  if(S.prSel===def.pr)S.prSel=null;
  render(); act("Closed "+def.pr+" without merging. Nothing was published and the branch is gone.");
}

/* The wizard's last step. Everything the PR needs is already in the draft; nothing new is stored. */
function wzRecOpenPr(){
  var z=S.wz; if(!z) return;
  var w=ws(), id=wzRecLineage(), st=String(cedText("wz:record")||wzRecStatement()).trim(), tok=wzRecTok();
  var ce=wzRecCe()?z.ce:null, head=sha7(id+st), day=new Date(storyMs()).toISOString().slice(0,10);
  var rec={id:id,kind:z.rkind,force:z.force,ce:ce,scope:z.scope,status:"published",isNew:true,tok:tok,
    st:st,effect:"rendered 0 · cited 0 · violated 0",commit:head,pub:day};
  var def={
    pr:w.main+"#"+prNextNumber(), branch:"context/"+id, base:CTXPR.base, head:head,
    record:rec, rule:{id:id,tok:tok,isNew:true},
    promo:"rec_01K5"+sha7(id).toUpperCase(), evt:"evt_01K5"+sha7(st).toUpperCase(),
    hash:"sha256:"+sha7(st)+sha7(id)+"a1",
    author:"operator", by:CMD_OP, desc:String(z.desc||"").trim(), ws:w.slug, opened:nowT().slice(0,8),
    mergedAt:function(){return rec.pub+" "+nowT().slice(0,8)+" UTC";}
  };
  /* The checks close over this pull request, not over whichever one is selected, so several can be
     open at once and each still reports on its own file. */
  def.checks=[
   {n:"Schema",ms:900,
    test:function(){return !!tomlOf(recprFileText(def));},
    ok:"context-record/v0.1 valid · 1 file, 1 record, 1 lineage",
    bad:"the record file does not parse as TOML"},
   {n:"Lineage uniqueness",ms:700,
    /* A real check, not a sentence, and it is re-run at merge because another pull request can
       claim the lineage after this one went green. */
    test:function(){return !lineageClaim(def);},
    ok:function(){return "no published record holds "+def.record.id+"; this pull request is its only holder";},
    bad:function(){var c=lineageClaim(def);
      return c==="published"
        ?def.record.id+" is already published. One lineage, one record — amend the published one instead of opening a second under its id."
        :def.record.id+" is already claimed by "+c+", which was opened first. Close one of them, or give this record a lineage of its own.";}},
   {n:"record_hash recomputation",ms:600,
    ok:function(){return "recomputed over the canonical bytes · "+def.hash.slice(0,20)+"… matches the file";}},
   {n:"Secret and PII scan",ms:900,ok:"statement, rationale and evidence scanned · 0 findings"},
   {n:"Conflict against active records",ms:1000,ok:function(){
      return RECORDS.filter(function(r){return r.status==="published"&&r.id!==def.record.id;}).length+
        " published records checked · no require or forbid on the same subject";}},
   {n:"Constraint is require or forbid",ms:500,ok:function(){
      var e=def.record.ce;
      return e?("constraint "+e+" · grants nothing"):"not a constraining kind · the field is absent, which is also a pass";}}
  ];
  RECPRS.unshift(def);
  S.recprs[def.pr]={st:"none",done:0,failed:null,timers:[],mergedAt:null};
  S.wz=null; S.dlg=null; S.dlgArg=null; S.prpSel=null;
  S.tab.steering="prs"; S.prSel=def.pr;
  recprRun(def);
  if(route().page!=="steering") go(stgHash("prs",w.slug)); else render();
  act("Branch "+def.branch+" pushed and "+def.pr+" opened. "+def.checks.length+" checks queued; it steers nothing until it merges.","gold");
}

/* The file the pull request carries. The statement is operator text, so it is escaped as TOML —
   a quote or a backslash in it must not be able to produce a file that does not parse while the
   schema check says it does. tomlStr and tomlMulti are the same serialisers the agent definition
   editor writes with. */
function recprFileText(def){
  var r=def.record, multi=/\n/.test(r.st);
  return '# .oxagen/rules/'+r.id+'.toml\n'+
   'schema = "context-record/v0.1"\n'+
   'lineage_id = '+tomlStr(r.id)+'\n'+
   'kind = '+tomlStr(r.kind)+'\n'+
   'sharing_scope = '+tomlStr(r.scope)+'\n'+
   'statement = '+(multi?tomlMulti(r.st):tomlStr(r.st))+'\n\n'+
   '[steering]\nstrength = '+tomlStr(r.force)+'\n\n'+
   (r.ce?'[enforcement]\nconstraint_effect = '+tomlStr(r.ce)+'\nblocking = false\n\n'
        :'# no [enforcement] table: a '+r.kind+' constrains nothing\n\n')+
   'record_hash = '+tomlStr(def.hash)+'\n';
}
function tomlOf(text){try{return tomlParse(text);}catch(e){return null;}}
function recprFile(def){
  /* highlighted with the same grammar the source editor uses, so what is shown is what parses */
  return '<pre>'+hlToml(recprFileText(def))+'</pre>';
}
function recprBody(def){
  var r=def.record, w=ws();
  return ['## '+r.st, '',
   'Written by '+me().name+' in the record wizard on '+r.pub+'.', '',
   '### What this asks for',
   'Kind `'+r.kind+'`. Strength `'+r.force+'`.'+(r.ce?' Constraint effect `'+r.ce+'`; it grants nothing.':' It constrains nothing and grants nothing.'), '',
   'Scope `'+r.scope+'` — '+(r.scope==="workspace"?'every agent in '+w.name:r.scope==="repository"?'the linked repository itself':'one agent’s runs and no other')+'.', '',
   '### Why',
   (def.desc||'(no rationale given)'), '',
   '### What it costs',
   'Adds '+r.tok+' steering tokens a turn to every turn in scope.', '',
   '---',
   'Opened by '+me().name+' · workspace `'+def.ws+'` · governance `team`'].join('\n');
}
function recprDetail(def){
  var st=recprSt(def), r=def.record, n=def.checks.length, l=recprLabel(def);
  var merged=st.st==="merged", passed=st.st==="passed", failed=st.st==="failed", sb=stgBundle();
  var checks=def.checks.map(function(k,i){
    var s2=i<st.done?"pass":(failed&&i===st.failed)?"fail":(st.st==="checking"&&i===st.done)?"running":"queued";
    return '<tr data-check="'+s2+'"><td style="font-size:12.5px">'+h(k.n)+'<div class="dim" style="font-size:11.5px">'+
     (s2==="pass"?h(ctxprCheckOk(k)):s2==="fail"?h(typeof k.bad==="function"?k.bad():k.bad):s2==="running"?'running…':'queued')+'</div></td>'+
     '<td style="text-align:right">'+(s2==="pass"?'<span class="b b-allowed"><span class="d"></span>pass</span>':
      s2==="fail"?'<span class="b b-failed"><span class="d"></span>fail</span>':
      s2==="running"?'<span class="reg-spin" aria-label="running"></span>':'<span class="b b-q">queued</span>')+'</td></tr>';}).join("");
  var mergebar=merged
   ? '<div class="panel-b" style="border-top:1px solid var(--border)"><b style="color:var(--st-proven)">Merged by '+h(me().name)+'</b>'+
     '<div class="dim" style="font-size:12px">'+h(st.mergedAt)+' · squashed into main as '+h(r.commit)+'</div>'+
     '<div class="row" style="margin-top:11px;gap:8px;flex-wrap:wrap">'+
     '<button class="btn primary" onclick="go(\''+crecUrl(r.id)+'\')">Open the record</button>'+
     '<button class="btn" onclick="S.tab.steering=\'records\';S.prSel=null;render()">See it in Records</button></div></div>'
   : '<div class="panel-b row" style="border-top:1px solid var(--border);gap:12px;flex-wrap:wrap"><div style="flex:1;min-width:200px;font-size:12.5px">'+
     (failed?'<b style="color:var(--st-failed)">A check failed.</b> <span class="muted">Nothing merges and nothing is published. Change the file and open it again.</span>'
      :passed?'<b>'+n+' checks passed.</b> <span class="muted">Governance team: '+h(me().name)+' owns <span class="mono">.oxagen/rules/</span>.</span>'
             :'<b>Checks are running.</b> <span class="muted">Merge is blocked until all '+n+' report.</span>')+'</div>'+
     '<button class="btn danger" onclick="openDialog(\'closepr\',\'recpr|'+h(def.pr)+'\')">Close pull request</button>'+
     '<button class="btn'+(passed?' primary':'')+'" '+(passed?'':'disabled ')+'onclick="recprMerge(\''+h(def.pr)+'\')">Merge pull request</button></div>';
  var right=merged
   ? '<div class="panel" style="margin-bottom:14px" data-promo-bundle="'+sb.v+'"><div class="panel-h"><h3>promotion_event</h3>'+
     '</div><div class="panel-b"><dl class="kv code">'+
     '<dt>record_id</dt><dd>'+h(def.promo)+'</dd><dt>lineage_id</dt><dd>'+h(r.id)+'</dd>'+
     '<dt>from → to</dt><dd>authored → <b>published</b></dd>'+
     '<dt>author</dt><dd>'+h(me().name)+' · '+h(me().role)+'</dd>'+
     '<dt>approver</dt><dd>'+h(me().name)+' · '+h(me().role)+'</dd>'+
     '<dt>pr_url</dt><dd>github.com/'+h(def.pr.replace("#","/pull/"))+'</dd>'+
     '<dt>commit_sha</dt><dd>'+h(r.commit)+'</dd><dt>merged_at</dt><dd>'+h(st.mergedAt)+'</dd>'+
     '<dt>re-indexed</dt><dd>from the merged commit · '+h(def.hash.slice(0,20))+'… verified</dd>'+
     '<dt>bundle</dt><dd>v'+(sb.v-1)+' → <b>v'+sb.v+'</b> · '+h(sb.digest||"re-signed")+'</dd>'+
     '<dt>tokens per turn</dt><dd>'+tokn(sb.tok-r.tok)+' → '+tokn(sb.tok)+'</dd>'+
     '<dt>audit</dt><dd>steering_published · '+h(def.evt)+'</dd>'+
     '<dt>ledger</dt><dd>promotions.jsonl not written · regulated mode only; this workspace is team</dd></dl>'+
     '<div class="row" style="margin-top:13px;gap:8px;flex-wrap:wrap">'+
     '<button class="btn" onclick="go(\'#/'+ORG.slug+'/audit/events\')">Audit log</button></div></div></div>'
   : '<div class="panel" style="margin-bottom:14px"><div class="panel-h"><h3>Merge effects</h3></div><div class="panel-b"><dl class="kv">'+
     '<dt>1</dt><dd>write a promotion_event with the author, the pull request and the commit</dd>'+
     '<dt>2</dt><dd>re-index the record from the merged commit; a hash mismatch blocks delivery</dd>'+
     '<dt>3</dt><dd>bump the bundle v'+sb.v+' → v'+(sb.v+1)+' and re-sign it · '+tokn(sb.tok)+' → '+tokn(sb.tok+r.tok)+' steering tokens a turn</dd>'+
     '<dt>4</dt><dd>emit steering_published to the audit log</dd>'+
     '<dt>5</dt><dd>deliver it on the next model call of every run in '+h(ws().name)+'</dd></dl>'+
     '<div class="note" style="margin-top:12px">Nothing above happens on the way here. The record steers nothing while this pull request is open, which is the whole reason it is a pull request.</div></div></div>';
  return '<div class="split"><div>'+
   '<div class="panel" style="margin-bottom:14px"><div class="panel-h"><h3>Context PR · <span class="mono">'+h(def.pr)+'</span></h3>'+
    '<span class="b b-'+l[0]+'" style="margin-left:auto" data-recpr-state="'+st.st+'"><span class="d"></span>'+h(l[1])+'</span></div><div class="panel-b">'+
    '<p class="eyebrow q">Branch <span class="mono">'+h(def.branch)+'</span> · base main · '+h(def.base)+' · one concern per PR</p>'+
    recprFile(def)+'</div></div>'+
   '<div class="panel"><div class="panel-h"><h3>Pull request body</h3>'+
    '<span class="b b-q" style="margin-left:auto">written by '+h(me().name)+'</span></div>'+
    '<div class="panel-b"><pre>'+h(recprBody(def))+'</pre></div></div></div>'+
   '<div><div class="panel" style="margin-bottom:14px"><div class="panel-h"><h3>Checks</h3>'+
    '<span class="muted" style="font-size:12px">the same rules as <span class="mono">stella context validate</span></span></div>'+
    '<div class="tw"><table class="narrow"><tbody data-recpr-done="'+st.done+'">'+checks+'</tbody></table></div>'+mergebar+'</div>'+right+'</div></div>';
}

/* Which pull request the tab is showing. An operator's wins by default because it is the one they
   just opened; the promoter's is one click away and stays selectable after. */
function prSelect(v){S.prSel=v;render();}
function prSelected(){ return (RECPRS.length&&S.prSel!=="ctxpr")?"recpr":"ctxpr"; }
function prTable(){
  var rows=[], cur=recprCur();
  RECPRS.forEach(function(d){var lr=recprLabel(d);
    rows.push([d.pr,d.pr,d.record.st,d.branch,me().name,ciLight(ciFromSt(d,recprSt(d)))+'<span class="b b-'+lr[0]+'"><span class="d"></span>'+h(lr[1])+'</span>',
      cur&&cur.pr===d.pr&&prSelected()==="recpr"]);});
  if(S.ctxpr.st!=="none"){var p=prpById(CTXPR.prp),lc=ctxprLabel();
    rows.push(["ctxpr",CTXPR.pr,p.st,CTXPR.branch,"the promoter",ciLight(ciFromSt(CTXPR,S.ctxpr))+'<span class="b b-'+lc[0]+'"><span class="d"></span>'+h(lc[1])+'</span>',
      prSelected()==="ctxpr"]);}
  PROPOSALS.forEach(function(q){ if(q.id!==CTXPR.prp&&q.pr!=="—")
    rows.push([null,q.pr,q.st,"context/"+q.lineage,"the promoter",'<span class="b b-approval"><span class="d"></span>'+h(q.checks)+'</span>',false]);});
  return '<div class="panel" style="margin-bottom:14px"><div class="panel-h"><h3>Context PRs</h3>'+
   '<span class="b b-q" style="margin-left:auto">Governance: '+h(wsGov(ws()))+'</span></div>'+
   '<div class="tw"><table data-lt="off"><thead><tr><th>Pull request</th><th>Branch</th><th>Opened by</th><th>State</th></tr></thead><tbody>'+
   rows.map(function(x){
     return '<tr'+(x[0]?' class="click'+(x[6]?' on':'')+'" onclick="prSelect(\''+h(x[0])+'\')" aria-current="'+(x[6]?"true":"false")+'"':'')+'>'+
      '<td><span class="mono" style="font-size:12px">'+h(x[1])+'</span><div class="dim" style="font-size:11.5px">'+h(x[2])+'</div></td>'+
      '<td class="mono" style="font-size:11.5px">'+h(x[3])+'</td><td style="font-size:12.5px">'+h(x[4])+'</td><td>'+x[5]+'</td></tr>';}).join("")+
   '</tbody></table></div></div>';
}

function ctxprTab(){
  var table=prTable();
  if(prSelected()==="recpr") return table+recprDetail(recprCur());
  var c=S.ctxpr, n=CTXPR.checks.length, l=ctxprLabel(), merged=c.st==="merged", passed=c.st==="passed"||merged;
  var p=prpById(CTXPR.prp), s=prpStats(CTXPR.prp), sb=stgBundle();
  if(c.st==="none") return table+'<div class="panel"><div class="panel-b"><p style="margin:0 0 12px;font-size:13px">'+h(CTXPR.prp)+' is ready and has no Context PR yet. It steers nothing until one merges.</p>'+
   '<button class="btn primary" onclick="openDialog(\'ctxpr\',\''+CTXPR.prp+'\')">Open a Context PR</button>'+
   '<div class="note" style="margin-top:12px">A pull request here is opened by the promoter, out of runs. <button class="lnk" onclick="wzOpen(\'record\')">Writing one yourself</button> opens the same kind of pull request, argued from you rather than from runs.</div></div></div>';

  var checks=CTXPR.checks.map(function(k,i){
    var st=i<c.done?"pass":(c.st==="checking"&&i===c.done)?"running":"queued";
    return '<tr data-check="'+st+'"><td style="font-size:12.5px">'+h(k.n)+'<div class="dim" style="font-size:11.5px">'+(st==="pass"?h(ctxprCheckOk(k)):st==="running"?'running…':'queued')+'</div></td>'+
     '<td style="text-align:right">'+(st==="pass"?'<span class="b b-allowed"><span class="d"></span>pass</span>':st==="running"?'<span class="reg-spin" aria-label="running"></span>':'<span class="b b-q">queued</span>')+'</td></tr>';
  }).join("");
  var mergebar=merged
   ? '<div class="panel-b" style="border-top:1px solid var(--border)"><b style="color:var(--st-proven)">Merged by '+h(me().name)+'</b><div class="dim" style="font-size:12px">'+h(c.mergedAt)+' · squashed into main as '+h(CTXPR.record.commit)+'</div></div>'
   : '<div class="panel-b row" style="border-top:1px solid var(--border);gap:12px;flex-wrap:wrap"><div style="flex:1;min-width:200px;font-size:12.5px">'+
     (passed?'<b>'+n+' checks passed.</b> <span class="muted">Governance team: '+h(me().name)+' owns <span class="mono">.oxagen/rules/</span>.</span>'
            :'<b>Checks are running.</b> <span class="muted">Merge is blocked until all '+n+' report.</span>')+'</div>'+
     '<button class="btn danger" onclick="openDialog(\'closepr\',\'ctxpr|'+h(CTXPR.pr)+'\')">Close pull request</button>'+
     '<button class="btn'+(passed?' primary':'')+'" '+(passed?'':'disabled ')+'onclick="ctxprMerge()">Merge pull request</button></div>';
  var body=[
   '## '+p.st, '',
   'Promoted by the oxagen promoter from **'+plural(s.runs,"run")+' across '+s.agents+' agent'+(s.agents===1?'':'s')+'**,',
   'confidence '+s.meta.confidence.toFixed(2)+'.', '',
   '### What this asks for',
   'Strength `'+p.force+'`. Constraint effect `forbid`; it grants nothing.', '',
   '### Why', s.meta.support(s)+' · finding fnd_01K5RT6C', '',
   '| Run | Date | Frame | Outcome | Repeat reads |','|---|---|---|---|---|'
  ].concat(s.rows.slice(0,3).map(function(r){return '| '+r.run+' | '+r.date+' | '+r.frame+' | `'+r.outcome+'` | '+r.dups+' |';}))
   .concat(['', '### What it costs', 'Adds '+s.meta.tok+' steering tokens a turn.', '', '---',
    'Opened by oxagen · workspace `core-platform` · governance `team`']).join('\n');
  var promo=merged
   ? '<div class="panel" style="margin-bottom:14px" data-promo-bundle="'+sb.v+'"><div class="panel-h"><h3>promotion_event</h3></div><div class="panel-b"><dl class="kv code">'+
     '<dt>record_id</dt><dd>'+h(CTXPR.promo)+'</dd><dt>lineage_id</dt><dd>'+h(CTXPR.record.id)+'</dd>'+
     '<dt>from → to</dt><dd>proposed → <b>published</b></dd><dt>approver</dt><dd>'+h(me().name)+' · '+h(me().role)+'</dd>'+
     '<dt>pr_url</dt><dd>github.com/a-intel/platform/pull/519</dd><dt>commit_sha</dt><dd>'+h(CTXPR.record.commit)+'</dd><dt>merged_at</dt><dd>'+h(c.mergedAt)+'</dd>'+
     '<dt>re-indexed</dt><dd>from the merged commit · '+h(CTXPR.hash)+' verified</dd>'+
     '<dt>bundle</dt><dd>v'+(sb.v-1)+' → <b>v'+sb.v+'</b> · '+h(sb.digest)+'</dd>'+
     '<dt>tokens per turn</dt><dd>'+tokn(sb.tok-CTXPR.record.tok)+' → '+tokn(sb.tok)+'</dd>'+
     '<dt>audit</dt><dd>steering_published · '+h(CTXPR.evt)+'</dd>'+
     '<dt>ledger</dt><dd>promotions.jsonl not written · regulated mode only; this workspace is team</dd></dl>'+
     '<div class="row" style="margin-top:13px;gap:8px;flex-wrap:wrap"><button class="btn" onclick="S.tab.run=\'context\';S.ctxSel=\'steering\';go(\'#/'+ORG.slug+'/'+S.ws+'/runs/run_01K5RS7M2E8FJ3QW\')">See it in run_01K5RS7M2E8FJ3QW</button>'+
     '<button class="btn" onclick="go(\'#/'+ORG.slug+'/audit/events\')">Audit log</button></div></div></div>'
   : '<div class="panel" style="margin-bottom:14px"><div class="panel-h"><h3>Merge effects</h3></div><div class="panel-b"><dl class="kv">'+
     '<dt>1</dt><dd>write a promotion_event with the approver, the pull request and the commit</dd>'+
     '<dt>2</dt><dd>re-index the record from the merged commit; a hash mismatch blocks delivery</dd>'+
     '<dt>3</dt><dd>bump the bundle v'+sb.v+' → v'+(sb.v+1)+' and re-sign it · '+tokn(sb.tok)+' → '+tokn(sb.tok+CTXPR.record.tok)+' steering tokens a turn</dd>'+
     '<dt>4</dt><dd>emit steering_published to the audit log</dd>'+
     '<dt>5</dt><dd>deliver it on the next model call of every run in core-platform</dd></dl></div></div>';
  return table+'<div class="split"><div>'+
   '<div class="panel" style="margin-bottom:14px"><div class="panel-h"><h3>Context PR · <span class="mono">'+h(CTXPR.pr)+'</span></h3>'+
    '<span class="b b-'+l[0]+'" style="margin-left:auto" data-ctxpr-state="'+c.st+'"><span class="d"></span>'+h(l[1])+'</span></div><div class="panel-b">'+
    '<p class="eyebrow q">Branch <span class="mono">'+h(CTXPR.branch)+'</span> · base main · '+h(CTXPR.base)+' · one concern per PR</p>'+
    '<pre><span class="c"># .oxagen/rules/'+h(CTXPR.record.id)+'.toml</span>\n'+
    '<span class="k">schema</span>       = <span class="s">"context-record/v0.1"</span>\n'+
    '<span class="k">lineage_id</span>   = <span class="s">"'+h(CTXPR.record.id)+'"</span>\n'+
    '<span class="k">kind</span>         = <span class="s">"'+h(CTXPR.record.kind)+'"</span>\n'+
    '<span class="k">sharing_scope</span>= <span class="s">"workspace"</span>\n'+
    '<span class="k">statement</span>    = <span class="s">"'+h(CTXPR.record.st)+'"</span>\n\n'+
    '[<span class="k">steering</span>]\n<span class="k">strength</span> = <span class="s">"'+h(CTXPR.record.force)+'"</span>\n\n'+
    '[<span class="k">enforcement</span>]\n<span class="k">constraint_effect</span> = <span class="s">"'+h(CTXPR.record.ce)+'"</span>\n<span class="k">blocking</span> = <span class="s">false</span>\n\n'+
    '<span class="k">record_hash</span>  = <span class="s">"'+h(CTXPR.hash)+'"</span></pre></div></div>'+
   '<div class="panel"><div class="panel-h"><h3>Pull request body</h3></div><div class="panel-b"><pre>'+h(body)+'</pre></div></div></div>'+
   '<div><div class="panel" style="margin-bottom:14px"><div class="panel-h"><h3>Checks</h3><span class="muted" style="font-size:12px">the same rules as <span class="mono">stella context validate</span></span></div>'+
    '<div class="tw"><table class="narrow"><tbody data-checks-done="'+c.done+'">'+checks+'</tbody></table></div>'+mergebar+'</div>'+promo+'</div></div>';
}

/* ============================== Steering: the hub ==============================
   One screen for everything that can steer an agent, in one order: Records, Skills, Memory,
   Ontology, Policy, Proposals, Preview. Two planes that never merge: steering is what the model
   reads (advisory, ranked, budgeted, may be dropped) and gating is what gets refused
   (deterministic, never budgeted, never ranked). One authoring surface, two compilations: every
   item compiles to text; an item with an enforcement grant also compiles to a gate, and every gate
   puts a one-line gate notice back into steering.

   The item type is SteeringItem: id, lineage, kind, force, scope, body, token_cost,
   enforcement_grant?, provenance, hash, valid_from. kind is record, skill, memory, ontology,
   policy (a gate notice) or instruction. stgItems() reads every source into that one shape and
   assembleSteering() is the one place they compete. The Preview tab and the steering.manifest
   frame on a run both call it, so the two can never disagree.

   A tab is a URL segment: #/:org/:ws/steering/<tab>. The hash is read on hashchange and at boot
   (applyHashTab), the way a run tab is; render() writes the hash back with replaceState so a tab
   changed by code (a merge landing on the pull requests view) is still a URL somebody can share.
   Context PRs is a view inside Proposals (/steering/proposals/prs), still S.tab.steering="prs". */
var MEMORY=FIXTURES.MEMORY, ONTOLOGY=FIXTURES.ONTOLOGY, GATES=FIXTURES.GATES, SKILL_SYNC=FIXTURES.SKILL_SYNC,
    STG_PREVIEW=FIXTURES.STEERING_PREVIEW, STG_MANIFESTS=FIXTURES.STEERING_MANIFESTS;
/* Five tabs, one category each. Records, Skills, Memory and Ontology were four tabs that all
   answered the same question — what is written down — so they are four shelves of one Library.
   Assignments answers which agent receives what, Gates is the second compilation, Proposals is
   the lifecycle, and Compiler is where you watch the assembler decide. Policy was renamed Gates
   because Tools has a Policy tab that means something else. */
var STG_TABS=[["library","Library"],["assignments","Assignments"],["gates","Gates"],
              ["proposals","Proposals"],["compiler","Compiler"]];
/* A tab id in the URL names the shelf it opened, so every link written before the Library
   existed still lands on the same list. */
var STG_LIB_KIND={records:"record",skills:"skill",memory:"memory",ontology:"ontology"};
var STG_LIB_SEG={record:"records",skill:"skills",memory:"memory",ontology:"ontology"};
/* Instructions is a shelf only where the workspace has one, so All stays the sum of what is shown. */
var STG_LIB_TABS=[["","All"],["record","Records"],["instruction","Instructions"],["skill","Skills"],["memory","Memory"],["ontology","Ontology"]];
var STG_LIB_LABEL={record:"Records",instruction:"Instructions",skill:"Skills",memory:"Memory",ontology:"Ontology"};
var STG_TAB_KEYS={library:1,records:1,skills:1,memory:1,ontology:1,assignments:1,
                  gates:1,policy:1,proposals:1,prs:1,compiler:1,preview:1};
var STG_KIND={record:"record",skill:"skill",memory:"memory",ontology:"ontology",policy:"gate notice",instruction:"instruction"};
var STG_KIND_ORDER={policy:0,record:1,instruction:2,skill:3,ontology:4,memory:5};
var STG_FORCE_ORDER={must:0,should:1,may:2,info:3};
var STG_REASON={"over budget":"b-approval","lower precedence":"b-q","out of scope":"b-q","superseded":"b-q"};
S.pv={agent:"release-manager",preset:"release-notes",text:null};
S.libKind="";

function stgHash(t,wslug){
  var base="#/"+ORG.slug+"/"+(wslug||S.ws)+"/steering";
  if(t==="prs") return base+"/proposals/prs";
  if(t==="skills") return base+"/skills"+(S.tab.skills&&S.tab.skills!=="catalog"?"/"+S.tab.skills:"");
  if(t==="compiler"||t==="preview") return base+"/compiler/"+encodeURIComponent(S.pv.agent);
  if(t==="library") return base+"/"+(S.libKind?STG_LIB_SEG[S.libKind]:"library");
  return base+"/"+(t||"library");
}
/* Picking a shelf is a navigation, so the shelf has a URL somebody can send. */
function stgLib(k){ S.libKind=k; stgTab(k==="skill"?"skills":"library"); }
/* Inside a scenario the hash belongs to the scenario, so a tab of the page the step is on is a
   re-render; a tab the step's page cannot show (Skills from a Steering step) is a real navigation. */
function stgTab(t){
  /* An old tab id still works from anywhere: it names a Library shelf, or the tab that was
     renamed. Nothing in a scenario, a doc or a bookmark has to be rewritten. */
  if(t!=="skills"&&STG_LIB_KIND[t]){ S.libKind=STG_LIB_KIND[t]; t="library"; }
  else if(t==="policy") t="gates";
  else if(t==="preview") t="compiler";
  var toSkills=t==="skills";
  if(!toSkills) S.tab.steering=t;
  if(S.scn&&((route().page==="skills")===toSkills)){ if(toSkills)S.tab.skills="catalog"; render(); return; }
  var hsh=stgHash(t); if(location.hash===hsh) render(); else go(hsh);
}
function stgSyncHash(r){
  if(S.scn||(r.page!=="steering"&&r.page!=="skills")) return;
  var want=r.page==="skills"?stgHash("skills",r.ws):stgHash(tab("steering","library"),r.ws);
  if(location.hash!==want){ try{history.replaceState(null,"",want);}catch(e){} }
}
function stgOpenCount(){
  return (S.ctxpr.st!=="none"&&S.ctxpr.st!=="merged"?1:0)+recprOpenCount()+
   PROPOSALS.filter(function(q){return q.id!==CTXPR.prp&&q.pr!=="—";}).length;
}
/* The header and the seven tabs. `on` is the tab in view; `primary` is that tab's one gold action. */
function wsGov(w){return (w&&w.governance)||"team";}
function govDesc(m){var x=WZ_MODES.filter(function(y){return y[0]===m;})[0];return x?x[1]:"";}
function govChip(w){
  return '<button class="btn sm gov-chip" onclick="openDialog(\'govmode\',\''+h(w.slug)+'\')" title="Change the governance mode">Governance: <span class="mono">'+h(wsGov(w))+'</span></button>';
}
function govSet(slug,mode){
  var w=wsBySlug(slug); if(!w) return; var was=wsGov(w); w.governance=mode; closeDialog();
  act(was===mode?"Governance mode is already "+mode+"; nothing to change.":"Context PR opened on "+w.main+": .oxagen/rules/governance.toml sets mode = "+mode+". It takes effect on merge for everything already in flight; nothing else in oxagen writes that file.","gold");
}
DLG_EXT.govmode=function(){
  var w=S.dlg==="govmode"?wsBySlug(S.dlgArg):null; if(!w) return {t:"Governance mode",w:false,b:"",f:""};
  var cur=S.govPick||wsGov(w);
  return {t:"Governance mode · "+w.name,s:".oxagen/rules/governance.toml on "+w.main,w:false,
   b:'<div class="wz-pick" style="grid-template-columns:1fr">'+WZ_MODES.map(function(m){var on=cur===m[0];
      return '<button class="wz-card'+(on?" on":"")+'" onclick="S.govPick=\''+m[0]+'\';render()"><span class="tx"><b>'+h(m[0])+(m[0]===wsGov(w)?' <span class="dim" style="font-weight:400">· now</span>':'')+'</b><span class="d">'+h(m[1])+' '+h(m[2])+'</span></span></button>';}).join("")+'</div>'+
    '<pre style="margin-top:12px">'+h(oxGovernanceToml(cur))+'</pre>'+
    '<div class="note" style="margin-top:12px">The mode is read off the file when a pull request is opened and again when it is merged, so raising it takes effect on everything already in flight. Lowering it is an org-owner action with approval, recorded as a security event.</div>',
   f:'<button class="btn" onclick="S.govPick=null;closeDialog()">Cancel</button><button class="btn primary" onclick="var m=S.govPick||\''+h(wsGov(w))+'\';S.govPick=null;govSet(\''+h(w.slug)+'\',m)">Open the Context PR</button>'};
};
/* Every count on this tab reads one list. The chip on a shelf is that kind's share of it, and All
   is its length, so the two can never disagree. */
function stgLibCounts(w){
  var c={record:0,instruction:0,skill:0,memory:0,ontology:0,all:0};
  stgLibraryItems(w.slug).forEach(function(it){c[it.kind]=(c[it.kind]||0)+1;c.all++;});
  return c;
}
function stgHub(on,body,primary){
  var w=ws(), c=stgLibCounts(w);
  var n={library:c.all,
    assignments:stgAgents().filter(function(x){return x.a.ws===w.slug;}).length,
    gates:stgGates(w.slug).length,proposals:PROPOSALS.length+stgOpenCount(),compiler:""};
  var tabs='<div class="tabs stg-tabs" role="tablist" aria-label="Steering">'+STG_TABS.map(function(x){
    return '<button class="tab" role="tab" aria-selected="'+(on===x[0])+'" onclick="stgTab(\''+x[0]+'\')">'+x[1]+
     (n[x[0]]?'<span class="n">'+n[x[0]]+'</span>':'')+'</button>';}).join("")+'</div>';
  /* The shelves sit under the Library tab, never beside it: an artifact kind is not a peer of
     an assignment or a lifecycle. Skills keeps its own page and still lights the Library tab. */
  var shelves=on!=="library"?'':'<div class="kf stg-seg" role="group" aria-label="Library shelves">'+
    STG_LIB_TABS.filter(function(x){return x[0]!=="instruction"||c.instruction;}).map(function(x){
      var k=x[0], cnt=k?c[k]:c.all;
      return '<button class="btn sm" aria-pressed="'+((S.libKind||"")===k)+'" onclick="stgLib(\''+k+'\')">'+
        h(x[1])+' <span class="dim">'+cnt+'</span></button>';}).join("")+'</div>';
  return '<div class="phead"><div class="t"><p class="eyebrow">'+h(w.name)+'</p><h1>Steering</h1>'+
   '<p>Everything that can steer an agent in this workspace competes in one assembler.</p></div>'+
   '<div class="acts">'+govChip(w)+(primary||'')+'</div></div>'+tabs+shelves+body;
}

/* ---- the sources, read into one shape ---- */
function stgAgents(){return STG_PREVIEW.agents.map(function(x){var a=agentBySlug(x.slug);return a?{slug:x.slug,repo:x.repo,prompt:x.prompt,a:a}:null;}).filter(Boolean);}
function stgAgent(slug){var L=stgAgents();for(var i=0;i<L.length;i++){if(L[i].slug===slug)return L[i];}return L[0];}
function stgInWs(x,wslug){return (x.ws||"core-platform")===wslug||x.scope==="org";}
function stgMemory(wslug){return MEMORY.filter(function(x){return stgInWs(x,wslug);});}
function stgOntology(wslug){return ONTOLOGY.filter(function(x){return stgInWs(x,wslug);});}
function stgGates(wslug){return GATES.filter(function(x){return stgInWs(x,wslug);});}
function stgTokOf(text){return Math.max(12,Math.round(String(text||"").length/3.6));}
function recRule(id){for(var i=0;i<STEER_BUNDLE.rules.length;i++){if(STEER_BUNDLE.rules[i].id===id)return STEER_BUNDLE.rules[i];}return null;}
function recTok(r){var b=recRule(r.id);return r.tok||(b&&b.tok)||stgTokOf(r.st)+40;}
/* The library and the assembler read two different lists, and both are true. `stgItems` is what the
   assembler selects from: the compiled bundle, and of the registry only a record the bundle carries.
   The library is what the workspace has written down, and a record joins it the moment it is
   published. Built from `stgItems`, the library showed 11 of 59 published records under a chip that
   said 59, so the count and the table disagreed and a record merged a moment ago was missing from
   All. Two kinds stay out: a gate notice, which belongs to the other plane and lives on Gates, and a
   bundle rule with no record in the registry, which no shelf can open. */
function stgLibraryItems(wslug){
  var out=stgItems(wslug).filter(function(it){return it.kind!=="policy"&&it.kind!=="record";});
  if(wslug==="core-platform") RECORDS.forEach(function(r){
    if(r.status!=="published") return;
    out.push({id:r.id,lineage:r.id,kind:"record",sub:r.kind,force:r.force,scope:r.scope,repo:r.repo,
      body:r.st,tok:recTok(r),grant:r.grant||null,about:r.about||[],
      provenance:".oxagen/rules/"+r.id+".toml"+(r.commit?" @ "+r.commit:""),
      hash:r.hash||"",valid_from:r.pub||""});});
  return out;
}
function stgItems(wslug,asOf){
  var out=[], seen={};
  function push(x){if(!seen[x.id]){seen[x.id]=1;out.push(x);}}
  /* records: the compiled bundle, then every seed record the registry holds. A record the volume
     generator grew has no hash and is not part of the story the assembler tells. */
  if(wslug==="core-platform") STEER_BUNDLE.rules.forEach(function(b){
    if(asOf!=null&&(b.since||0)>asOf) return;
    var r=stgRecord(b.id)||{};
    push({id:b.id,lineage:b.id,kind:"record",sub:r.kind||"rule",force:r.force||b.force,scope:r.scope||b.scope,repo:r.repo||b.repo,agent:b.agent,
      body:r.st||b.st,tok:b.tok,grant:r.grant||null,about:r.about||b.about||[],provenance:".oxagen/rules/"+b.id+".toml"+(r.commit?" @ "+r.commit:""),
      hash:r.hash||"",valid_from:r.pub||""});});
  if(wslug==="core-platform") RECORDS.forEach(function(r){
    if(r.status!=="published"||!r.hash) return;
    push({id:r.id,lineage:r.id,kind:"record",sub:r.kind,force:r.force,scope:r.scope,repo:r.repo,body:r.st,tok:recTok(r),grant:r.grant||null,
      about:r.about||[],provenance:".oxagen/rules/"+r.id+".toml @ "+r.commit,hash:r.hash,valid_from:r.pub});});
  STG_PREVIEW.instructions.forEach(function(x){ if(stgInWs(x,wslug)) push(stgNorm(x)); });
  if(SK_ON[wslug]) SKILLS.forEach(function(s){
    if(s.state!=="ok") return;
    var nm=s.id.split(".").pop();
    push({id:"skill:"+s.id,lineage:s.id,kind:"skill",sub:s.kind,force:"info",scope:"workspace",body:s.st,tok:stgTokOf(s.st),grant:null,
      about:nm.split("-"),provenance:s.path+" @ "+s.ver,hash:s.digest,valid_from:s.updated,skill:s.id});});
  stgOntology(wslug).forEach(function(x){push(stgNorm(x));});
  stgMemory(wslug).forEach(function(x){push(stgNorm(x));});
  stgGates(wslug).forEach(function(x){push(stgNorm(x));});
  return out;
}
function stgNorm(x){
  return {id:x.id,lineage:x.lineage,kind:x.kind,sub:x.cls||x.noteKind||x.gate||"",force:x.force,scope:x.scope,repo:x.repo,agent:x.agent,agents:x.agents,
    body:x.body,tok:x.token_cost,grant:x.enforcement_grant||null,about:x.about||[],provenance:x.provenance,hash:x.hash,valid_from:x.valid_from,
    supersededBy:x.supersededBy,yieldsTo:x.yieldsTo,outcome:x.outcome};
}
function stgItemById(wslug,id){var L=stgItems(wslug);for(var i=0;i<L.length;i++){if(L[i].id===id)return L[i];}return null;}

/* ---- the assembler ----
   assembleSteering(run, budget) in the product; here the run is an agent, the repository it works
   in and the prompt. Precedence is fixed in this one place: a gate beats everything, a published
   must beats recalled memory, and repository scope may narrow workspace scope and never widen it.
   Returns the stable prefix (gate notices, then must and should), the volatile selection (may
   and info, ranked for this prompt and packed under the token budget) and the manifest of what
   was cut and why. Same inputs, same answer: there is no clock and no model in it. */
var STG_STOP={the:1,and:1,for:1,that:1,this:1,with:1,now:1,from:1,into:1,are:1,was:1,not:1,its:1,"on":1,"is":1,"of":1,"to":1,"in":1,"a":1,"an":1};
function stgWords(s){
  var m=String(s||"").toLowerCase().match(/[a-z0-9][a-z0-9.\-]*/g)||[], out=[], seen={};
  m.forEach(function(w){w=w.replace(/[.\-]+$/,"");if(w.length>4&&/[a-z]s$/.test(w)&&!/ss$/.test(w))w=w.slice(0,-1);
    if(w.length<3||STG_STOP[w]||seen[w])return;seen[w]=1;out.push(w);});
  return out;
}
function stgScore(it,words){
  var ab={},bw={};stgWords((it.about||[]).join(" ")).forEach(function(w){ab[w]=1;});stgWords(it.body).forEach(function(w){bw[w]=1;});
  var s=0;words.forEach(function(w){s+=ab[w]?2:bw[w]?1:0;});return s;
}
function assembleSteering(slug,prompt,opt){
  opt=opt||{};
  var A=stgAgent(slug), a=A.a, wslug=a.ws, repo=opt.repo||A.repo, B=STG_PREVIEW.budget;
  var items=stgItems(wslug,opt.asOf), live=[], cut=[], byId={};
  function drop(it,reason,why){cut.push({it:it,reason:reason,why:why});}
  items.forEach(function(it){
    if(it.scope==="repository"&&it.repo!==repo) return drop(it,"out of scope","scoped to "+it.repo+"; this agent works in "+repo);
    if(it.scope==="agent"&&it.agent!==slug) return drop(it,"out of scope","scoped to the agent "+it.agent);
    if(it.agents&&it.agents.indexOf(slug)<0) return drop(it,"out of scope",it.agents.length?"applies to "+it.agents.join(", "):"no agent holds the tool it gates");
    live.push(it); byId[it.id]=it;});
  live=live.filter(function(it){
    if(it.supersededBy&&byId[it.supersededBy]){drop(it,"superseded","replaced by "+it.supersededBy+", published "+(byId[it.supersededBy].valid_from||"since"));return false;}
    if(it.yieldsTo&&byId[it.yieldsTo]&&byId[it.yieldsTo].force==="must"){drop(it,"lower precedence","a published must beats recalled memory: "+it.yieldsTo);return false;}
    return true;});
  function order(x,y){return (STG_KIND_ORDER[x.kind]-STG_KIND_ORDER[y.kind])||(STG_FORCE_ORDER[x.force]-STG_FORCE_ORDER[y.force])||(x.id<y.id?-1:1);}
  var gates=live.filter(function(it){return it.kind==="policy";}).sort(order);
  var stable=live.filter(function(it){return it.kind!=="policy"&&(it.force==="must"||it.force==="should");})
    .sort(function(x,y){return (STG_FORCE_ORDER[x.force]-STG_FORCE_ORDER[y.force])||order(x,y);});
  var gateTok=0; gates.forEach(function(g){gateTok+=g.tok;});
  /* the SessionStart cap is bytes, and a gate notice is never what gives way to it */
  var cap=Math.floor(B.sessionStartBytes/B.bytesPerTok), used=B.compileHeaderTok+gateTok, prefix=[];
  stable.forEach(function(it){
    if(used+it.tok>cap) return drop(it,"over budget","the SessionStart additional context is capped at 16 KiB");
    used+=it.tok; prefix.push(it);});
  var words=stgWords(prompt), vol=live.filter(function(it){return it.kind!=="policy"&&(it.force==="may"||it.force==="info");});
  vol.forEach(function(it){it.score=stgScore(it,words);});
  vol.sort(function(x,y){return (y.score-x.score)||order(x,y);});
  var vTok=0, volatile=[];
  vol.forEach(function(it,i){
    it.rank=i+1;
    if(vTok+it.tok>B.volatileTok) return drop(it,"over budget","ranked "+(i+1)+" of "+vol.length+" for this prompt, relevance "+it.score+"; "+tokn(it.tok)+" tok did not fit in the "+tokn(B.volatileTok-vTok)+" left");
    vTok+=it.tok; volatile.push(it);});
  var order2={"over budget":0,"lower precedence":1,"superseded":2,"out of scope":3};
  cut.sort(function(x,y){return (order2[x.reason]-order2[y.reason])||((x.it.rank||99)-(y.it.rank||99))||(x.it.id<y.it.id?-1:1);});
  var hooks=(TIER_RANK[a.tier]||0)>=1;
  return {agent:a,slug:slug,repo:repo,prompt:prompt,words:words,delivered:hooks,gates:gates,prefix:prefix,volatile:volatile,cut:cut,
    skills:SK_ON[wslug]?SKILLS.filter(function(s){return s.state==="ok"&&(s.srcLabel===repo||/registry/.test(s.srcLabel));}):[],
    sync:SKILL_SYNC.filter(function(x){return x.repo===repo;})[0]||null,
    tok:{header:B.compileHeaderTok,gates:gateTok,prefix:used,volatile:vTok,total:used+vTok},
    bytes:used*B.bytesPerTok,budget:B};
}

/* ---- shared pieces ---- */
function forceBadge(f){return '<span class="b b-q fz fz-'+h(f)+'" title="steering force">'+h(f)+'</span>';}
/* The kind badge on every steering list: the Library, an agent's Steering tab, the compiler, and
   a run's manifest. It is the Records shelf's badge, with the same icon and hue, so a kind reads the
   same on every tab. A memory is itself one of the six kinds, and a record or a skill carries one
   in `sub`. An ontology note, an instruction, and a gate notice carry none of the six, so they keep
   the badge's shape and take their own icon in a neutral hue: the six hues mean the six kinds and
   nothing else. The word the old grey chip put after its dot sits beside the badge: a skill's
   shelf, a memory's class, an ontology note's kind. A record needs none, because the six kinds are
   record kinds. */
var STG_ITEM_BADGE={
 skill:{l:"skill",d:"A governed SKILL.md, delivered by sync",i:'<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h4"/>'},
 ontology:{l:"ontology",d:"An entity or a term, defined the way this workspace uses it",i:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20V3H6.5A2.5 2.5 0 0 0 4 5.5z"/><path d="M4 19.5A2.5 2.5 0 0 0 6.5 22H20v-5"/>'},
 instruction:{l:"instruction",d:"The workspace's additional instructions",i:'<path d="M4 6h16M4 10h11M4 14h16M4 18h11"/>'},
 policy:{l:"gate notice",d:"The line a gate puts into steering about what it refuses",i:'<rect x="4" y="11" width="16" height="10" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/>'}};
function stgItemKind(it){
  if(KINDS[it.kind]) return it.kind;
  var s=String(it.sub||"").toLowerCase();
  return (it.kind==="record"||it.kind==="skill")&&KINDS[s]?s:"";
}
function stgKindLabel(it){var k=stgItemKind(it);return k?KINDS[k].l:(STG_ITEM_BADGE[it.kind]||{l:STG_KIND[it.kind]||it.kind}).l;}
function stgKindChip(it){
  var k=stgItemKind(it), d=STG_ITEM_BADGE[it.kind]||{l:STG_KIND[it.kind]||it.kind,d:"",i:""};
  var badge=k?kindBadge(k):'<span class="kb k-item" title="'+h(d.d)+'"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+d.i+'</svg>'+h(d.l)+'</span>';
  var shelf=STG_KIND[it.kind]||it.kind, sub=String(it.sub||"").toLowerCase();
  var src=it.kind==="record"||it.kind==="policy"?"":stgKindLabel(it)===shelf?sub:shelf;
  return badge+(src?'<span class="kb-src">'+h(src)+'</span>':'');
}
function compileChip(grant){
  return grant?'<button class="b b-approval stg-cc" title="This record carries an enforcement grant. It compiles to text, and to a gate: '+h(grant.outcome)+' on '+h(grant.on)+'" onclick="event.stopPropagation();stgTab(\'gates\')"><span class="d"></span>compiles to text and a gate</button>'
    :'<span class="b b-q" title="No enforcement grant. The model reads it. Nothing refuses a call because of it.">compiles to text</span>';
}
function stgOpenItem(it){
  if(it.kind==="record") return stgRecord(it.id)?"go('"+crecUrl(it.id)+"')":"stgTab('records')";
  if(it.kind==="skill") return "openDialog('skill','"+it.skill+"')";
  if(it.kind==="policy") return "stgTab('gates')";
  if(it.kind==="memory") return memById(it.id)?"openDialog('memory','"+it.id+"')":"stgTab('memory')";
  if(it.kind==="ontology") return "stgTab('ontology')";
  return "stgTab('records')";
}
function stgItemLink(it){return '<button class="lnk mono" style="font-size:12px" onclick="'+stgOpenItem(it)+'">'+h(it.id)+'</button>';}
function stgMeter(label,used,max,unit,sub){
  var p=Math.min(100,Math.round(used/max*100));
  return '<div class="meter"><div class="lab"><span>'+h(label)+'</span><b>'+tokn(used)+' of '+tokn(max)+' '+h(unit)+'</b></div>'+
   '<div class="bar" role="img" aria-label="'+h(label)+': '+p+' percent used"><i'+(p>=90?' class="hold"':'')+' style="width:'+p+'%"></i></div>'+
   (sub?'<div class="dim" style="font-size:11.5px">'+sub+'</div>':'')+'</div>';
}

/* ---- Memory ---- */
/* Memory is aggregated, not collected: every run's notes and every operator steer are folded by
   lineage into one item per fact, the newest provenance kept, and the recall count is the sum over
   the runs that pulled it. The strip above the table says how much folded into how little. */
function stgMemoryAgg(L){
  var runs={}, steers=0, notes=0, recalls=0, cls={};
  L.forEach(function(m){recalls+=m.recalls30||0; cls[m.cls]=(cls[m.cls]||0)+1;
    String(m.provenance||"").split(/\s*·\s*/).forEach(function(p){if(/^run_/.test(p))runs[p]=1;});
    if(/operator steer/.test(m.provenance||""))steers++; else notes++;});
  return {runs:Object.keys(runs).length,steers:steers,notes:notes,recalls:recalls,cls:cls,folded:Math.round(L.length*3.4)+steers};
}
function stgMemoryTab(w){
  var L=stgMemory(w.slug), G=stgMemoryAgg(L);
  var rows=L.map(function(m){
    var st=m.supersededBy?'<span class="b b-q">superseded</span><span class="sub">by '+stgItemLinkById(w.slug,m.supersededBy)+'</span>'
      :m.yieldsTo?'<span class="b b-approval"><span class="d"></span>yields</span><span class="sub">to '+stgItemLinkById(w.slug,m.yieldsTo)+', a published must</span>'
      :'<span class="b b-allowed"><span class="d"></span>competes</span>';
    return '<tr '+rowClick("openDialog('memory','"+h(m.id)+"')","Open "+m.id)+'><td><b style="font-weight:500">'+h(m.body)+'</b><span class="sub mono">'+h(m.id)+' · '+h(m.provenance)+'</span></td>'+
     '<td><span class="b b-q mono">'+h(m.cls)+'</span></td><td>'+forceBadge(m.force)+'</td>'+
     '<td>'+h(m.scope)+(m.agent?'<span class="sub mono">'+h(m.agent)+'</span>':'')+'</td>'+
     '<td class="mono" style="font-size:11.5px">'+h(m.lastRecalled)+'<span class="sub">'+m.recalls30+' recalls in 30 days</span></td>'+
     '<td class="num">'+tokn(m.token_cost)+' tok</td><td>'+st+'</td></tr>';}).join("");
  var agg='<div class="grid g4" style="margin-bottom:14px">'+
   '<div class="stat"><span class="k">Memories</span><span class="v">'+L.length+'</span><span class="s">folded from '+G.folded+' run notes and steers</span></div>'+
   '<div class="stat"><span class="k">Sources</span><span class="v">'+G.runs+' <small>'+(G.runs===1?"run":"runs")+'</small></span><span class="s">'+G.steers+' operator steers and '+G.notes+' agent notes</span></div>'+
   '<div class="stat"><span class="k">Recalled 30d</span><span class="v">'+G.recalls.toLocaleString()+'</span><span class="s">'+tokn(L.reduce(function(n,m){return n+(m.token_cost||0)*(m.recalls30||0);},0))+' tokens delivered</span></div>'+
   '<div class="stat"><span class="k">By class</span><span class="v" style="font-size:15px;padding-top:6px">'+Object.keys(G.cls).map(function(k){return '<span class="mono">'+h(k)+'</span> '+G.cls[k];}).join(' · ')+'</span><span class="s">a rule is proposed as a record instead</span></div></div>';
  return agg+'<div class="note" style="margin-bottom:14px"><b>A published must beats recalled memory.</b> Memory is what an agent’s own runs left behind. It is recalled, never published, so it competes only in the volatile selection, as <span class="mono">may</span> or <span class="mono">info</span>, and it gives way wherever a published record says otherwise. To make a memory binding, promote it: a proposal, a pull request, a merge.</div>'+
   '<div class="panel"><div class="panel-h"><h3>Recalled memory</h3><span class="b b-q" style="margin-left:auto">'+L.length+'</span></div>'+
   '<div class="tw"><table><thead><tr><th>Memory</th><th>Class</th><th>Force</th><th>Scope</th><th>Last recalled</th><th>Token cost</th><th>In the assembler</th></tr></thead><tbody>'+rows+'</tbody></table></div>'+
   '<div class="panel-b"><div class="row"><button class="btn sm" onclick="S.pv.preset=\'merge-green\';S.pv.text=null;stgTab(\'compiler\')">See one yield in the compiler</button>'+
   '<span class="dim" style="font-size:12px">Recall used to reach only the in-app agent, capped at six items. It now goes through the same assembler as every other source.</span></div></div></div>';
}

/* ---- one memory. The tab told you to promote a memory and no row offered it, and nothing
   forgot one either: a fact an agent got wrong kept being recalled with no way to stop it. ---- */
function memById(id){for(var i=0;i<MEMORY.length;i++){if(MEMORY[i].id===id)return MEMORY[i];}return null;}
function memPosition(m){
  if(m.supersededBy)return "Superseded by "+h(m.supersededBy)+". It is kept for the runs that carried it and is never selected again.";
  if(m.yieldsTo)return "It yields to "+h(m.yieldsTo)+", a published must. Where the two disagree, the published record is what the agent reads.";
  return "It competes in the volatile selection at force "+h(m.force)+". A published record beats it wherever the two are about the same thing.";
}
DLG_EXT.memory=function(id){
  var m=memById(id); if(!m)return noSuch("Memory");
  var run=String(m.provenance||"").split(/\s*·\s*/)[0];
  return {t:m.body,s:"A memory, recalled and never published",w:false,
   b:'<dl class="kv"><dt>Class</dt><dd><span class="b b-q mono">'+h(m.cls)+'</span> at '+forceBadge(m.force)+'</dd>'+
     '<dt>Scope</dt><dd>'+h(m.scope)+(m.agent?' · <span class="mono">'+h(m.agent)+'</span>':'')+'</dd>'+
     '<dt>Where it came from</dt><dd><span class="mono" style="font-size:11.5px">'+h(m.provenance)+'</span></dd>'+
     '<dt>Recalled</dt><dd>'+m.recalls30+' times in 30 days, last on '+h(m.lastRecalled)+'</dd>'+
     '<dt>Cost</dt><dd>'+tokn(m.token_cost)+' tokens every time it is selected, so '+tokn(m.token_cost*m.recalls30)+' over those 30 days</dd>'+
     '<dt>In force since</dt><dd><span class="mono">'+h(m.valid_from)+'</span></dd></dl>'+
     '<div class="note" style="margin-top:12px">'+memPosition(m)+'</div>'+
     (/^run_/.test(run)?'<div class="field" style="margin-top:12px"><label>The run that left it</label>'+
       '<button class="btn sm" onclick="closeDialog();go(\'#/'+ORG.slug+'/'+S.ws+'/runs/'+h(run)+'\')">Open '+h(run)+'</button></div>':''),
   f:'<button class="btn" onclick="closeDialog()">Close</button>'+
     '<button class="btn danger" onclick="openDialog(\'memforget\',\''+h(m.id)+'\')">Forget</button>'+
     '<button class="btn primary" onclick="memPromote(\''+h(m.id)+'\')">Promote to a record</button>'};
};
DLG_EXT.memforget=function(id){
  var m=memById(id); if(!m)return noSuch("Memory");
  return {t:"Forget this memory?",w:false,
   b:'<div class="note">The assembler stops selecting it, and '+h(m.agent||"every agent in scope")+' stops being told it. The runs it was folded from are untouched: every frame stays, and every run that carried it keeps naming the hash it carried.</div>'+
     (m.recalls30?'<div class="warn">It was recalled '+m.recalls30+' times in the last 30 days. Whatever those runs did with it, they did because of this.</div>':'')+
     '<div class="note" style="margin-top:10px">Promote is the other answer. If the memory is right, a record makes it binding instead of leaving it to compete.</div>',
   f:'<button class="btn" onclick="closeDialog()">Keep it</button>'+
     '<button class="btn danger" onclick="memForget(\''+h(m.id)+'\')">Forget it</button>'};
};
function memForget(id){
  var m=memById(id), i=MEMORY.indexOf(m); if(i<0)return;
  MEMORY.splice(i,1); closeDialog(); render();
  act("Forgot "+m.id+". The assembler stops selecting it; every run that carried it is untouched.");
}
function memPromote(id){
  var m=memById(id); if(!m)return;
  wzOpen("record");
  if(S.wz){S.wz.desc=m.body; S.wz.descAI=false; S.wz.fromMemory=m.id;}
  render();
}

function stgItemLinkById(wslug,id){var it=stgItemById(wslug,id);return it?stgItemLink(it):'<span class="mono">'+h(id)+'</span>';}

/* ---- Ontology ---- */
function ontById(id){for(var k=0;k<ONTOLOGY.length;k++){if(ONTOLOGY[k].id===id)return ONTOLOGY[k];}return null;}
function ontSlug(t){return String(t).toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");}
function ontFile(o){return ".oxagen/ontology/"+ontSlug(o.term)+".toml";}
/* A note's cost is what its words compile to. Four characters a token is the estimate the
   assembler uses everywhere else on this page. */
function ontCost(body){return Math.max(1,Math.round(String(body).trim().length/4));}
/* Deterministic, so a headless check of this screen reads the same digest every run. */
function ontHash(t){var n=0,x=String(t);for(var k=0;k<x.length;k++){n=(n*31+x.charCodeAt(k))>>>0;}
  var o="";for(var m=0;m<16;m++){n=(n*1103515245+12345)>>>0;o+="0123456789abcdef"[n>>>28];}return "sha256:"+o;}

function stgOntologyTab(w){
  var L=stgOntology(w.slug);
  var rows=L.map(function(o){
    return '<tr class="click" onclick="openDialog(\'ontology\',\''+h(o.id)+'\')"><td><b>'+h(o.term)+'</b><span class="sub mono">'+h(o.id)+'</span></td><td><span class="b b-q">'+h(o.noteKind)+'</span></td>'+
     '<td style="max-width:52ch">'+h(o.body)+'</td>'+
     '<td>'+(o.retiring?'<span class="b b-approval"><span class="d"></span>retiring</span>':forceBadge(o.force))+'</td>'+
     '<td class="mono" style="font-size:11.5px">'+o.entities.map(h).join("<br>")+'</td>'+
     '<td class="num">'+tokn(o.token_cost)+' tok</td><td class="mono" style="font-size:11px">'+h(o.provenance)+'</td>'+
     '<td class="rowacts" onclick="event.stopPropagation()"><button class="btn sm" onclick="openDialog(\'ontedit\',\''+h(o.id)+'\')">Edit</button><span class="vh">, </span>'+
     '<button class="btn sm danger" onclick="openDialog(\'ontretire\',\''+h(o.id)+'\')">Retire</button></td></tr>';}).join("");
  return '<div class="note" style="margin-bottom:14px">An ontology note defines one entity or one term the way this workspace uses it. It compiles to text like any other item, enters the volatile selection as <span class="mono">info</span>, and grants nothing. A note is a file somebody wrote and somebody merged, under <span class="mono">.oxagen/ontology/</span> on '+h(w.main)+', so writing, changing and retiring one each open a pull request.</div>'+
   '<div class="panel"><div class="panel-h"><h3>Definitions</h3><div class="sp"><span class="b b-q">'+L.length+'</span>'+
   '<button class="btn sm" onclick="openDialog(\'ontnew\')">New definition</button></div></div>'+
   '<div class="tw"><table><thead><tr><th>Term</th><th>Kind</th><th>Definition</th><th>Force</th><th>About</th><th>Token cost</th><th>File</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div></div>';
}

/* ---- Ontology notes: write one, change one, retire one ----
   Each is a pull request against the workspace repository, because the note is a file there. The
   row changes the moment the request is opened, so the screen never claims a merge it did not
   see. */
var ONT_KINDS=["term","entity","alias","boundary"];
function ontForm(o,p){
  o=o||{};
  return '<div class="field"><label for="'+p+'-term">Term</label><input id="'+p+'-term" value="'+h(o.term||"")+'" placeholder="release train"></div>'+
   '<div class="field"><label for="'+p+'-kind">Kind</label><select id="'+p+'-kind">'+
   ONT_KINDS.map(function(k){return '<option'+(k===(o.noteKind||"term")?" selected":"")+'>'+h(k)+'</option>';}).join("")+
   '</select><div class="hint">A term defines a word. An entity names a thing. An alias points one term at another. A boundary says where something stops.</div></div>'+
   '<div class="field"><div class="lab-row"><label for="'+p+'-body">Definition</label>'+
   '<button class="btn wand" id="'+p+'WandBtn" onclick="ontWand(\''+p+'\')" title="Have the assistant write it" aria-label="Have the assistant write it">'+avSvg("wand-sparkles")+'</button></div>'+
   '<textarea id="'+p+'-body" rows="4" placeholder="The release train is the weekly cut of a-intel/platform from main to a release branch.">'+h(o.body||"")+'</textarea>'+
   '<div class="wand-note on">Press the wand. <b>oxagen.assistant</b> rewrites what you wrote into the prose the file carries. Read it before anybody reviews it.</div></div>'+
   '<div class="field"><label for="'+p+'-ent">About</label><input id="'+p+'-ent" value="'+h((o.entities||[]).join(", "))+'" placeholder="a-intel/platform, release/4.11">'+
   '<div class="hint">The repositories, branches or services this note is about, separated by commas.</div></div>';
}
function ontWand(p){
  var t=el(p+"-body"); if(!t)return;
  var raw=String(t.value||"").trim();
  if(!raw)return act("Write the definition first. The assistant rewrites what you give it; it does not decide what the term means.");
  t.value=assistProse("ontology",raw);
  act(WAND_SAY.ontology,"gold");
}
function ontRead(p){
  return {term:el(p+"-term")?el(p+"-term").value.trim():"",
   noteKind:el(p+"-kind")?el(p+"-kind").value:"term",
   body:el(p+"-body")?el(p+"-body").value.trim():"",
   entities:el(p+"-ent")?el(p+"-ent").value.split(",").map(function(x){return x.trim();}).filter(Boolean):[]};
}
/* The checks a note faces. Each one reads the note in front of it. */
function ontChecks(o,removing){
  if(removing)return [["schema","pass","The file is removed, so there is nothing left to validate."],
   ["reference_scan","pass","No record, skill or agent definition names "+h(o.term)+"."],
   ["lineage_uniqueness","pass",h(o.id)+" is published nowhere else, so nothing inherits it."]];
  return [["schema","pass","ontology-note/v0.1; one [[note]]; every required member present."],
   ["lineage_uniqueness","pass",h(o.id)+" is published nowhere else in this workspace."],
   ["secret_pii_scan","pass","No credential, email address or card number in the definition."],
   ["grant_scan","pass","kind = "+h(o.noteKind)+" carries no effect and grants nothing, as an ontology note must."]];
}
function ontPr(o,op,trigger){
  var p={id:"oxpr_ont_"+ontSlug(o.term).slice(0,14),kind:"ontology",title:o.term,
   repo:ws().main,base:ws().branch,branch:"ontology/"+ontSlug(o.term),
   pr:ws().main+"#"+(524+OXPRS.length),by:PEOPLE.marcus.name,byKind:"person",
   opened:"just now",state:"checks_running",trigger:trigger,
   files:[[op,ontFile(o),op==="del"?"the note is removed":"one [[note]], force = info"]],
   checks:ontChecks(o,op==="del")};
  OXPRS.unshift(p);
  return p;
}
DLG_EXT.ontology=function(id){
  var o=ontById(id);
  if(!o)return noSuch("Ontology note");
  return {t:o.term,s:"An ontology note, which compiles to text and grants nothing",w:false,
   b:'<dl class="kv"><dt>Kind</dt><dd>'+h(o.noteKind)+'</dd>'+
    '<dt>Definition</dt><dd>'+h(o.body)+'</dd>'+
    '<dt>About</dt><dd class="mono" style="font-size:11.5px">'+o.entities.map(h).join("<br>")+'</dd>'+
    '<dt>Force</dt><dd>'+(o.retiring?'A pull request removes this note. It keeps informing the model until that merges.':h(o.force)+', so it informs the model and grants nothing')+'</dd>'+
    '<dt>Token cost</dt><dd>'+tokn(o.token_cost)+' tokens when it is selected</dd>'+
    '<dt>File</dt><dd class="mono" style="font-size:11.5px">'+h(o.provenance)+'</dd>'+
    '<dt>Hash</dt><dd class="mono" style="font-size:11.5px">'+h(o.hash)+'</dd>'+
    '<dt>In force since</dt><dd class="mono">'+h(o.valid_from)+'</dd></dl>',
   f:'<button class="btn" onclick="closeDialog()">Close</button>'+
    '<button class="btn danger" onclick="openDialog(\'ontretire\',\''+h(o.id)+'\')">Retire</button>'+
    '<button class="btn primary" onclick="openDialog(\'ontedit\',\''+h(o.id)+'\')">Edit</button>'};
};
DLG_EXT.ontnew=function(){
  return {t:"Write an ontology note",s:"One term, defined the way this workspace uses it",w:false,
   b:ontForm(null,"on")+
    '<div class="note">Opening this writes <span class="mono">.oxagen/ontology/&lt;term&gt;.toml</span> on '+h(ws().main)+' in a pull request. The note steers nothing until it merges.</div>',
   f:'<button class="btn" onclick="closeDialog()">Cancel</button>'+
    '<button class="btn primary" onclick="ontCreate()">Open the pull request</button>'};
};
function ontCreate(){
  var f=ontRead("on");
  if(!f.term)return act("Name the term before you open the pull request.");
  if(!f.body)return act("Write the definition before you open the pull request.");
  var dupe=stgOntology(ws().slug).filter(function(x){return x.term.toLowerCase()===f.term.toLowerCase();});
  if(dupe.length)return act("This workspace already defines "+f.term+". Edit that note instead.");
  var o={id:"ont."+ontSlug(f.term),lineage:"ont."+ontSlug(f.term),kind:"ontology",noteKind:f.noteKind,
   term:f.term,force:"info",scope:"workspace",body:f.body,token_cost:ontCost(f.body),
   about:f.term.toLowerCase().split(/\s+/),entities:f.entities,ws:ws().slug,
   provenance:ontFile({term:f.term})+" @ pending",hash:ontHash(f.body),
   valid_from:"pending the merge",retiring:false};
  var p=ontPr(o,"add","An operator wrote a definition for "+f.term+".");
  ONTOLOGY.push(o);
  closeDialog(); render();
  act("Opened "+p.pr+" for "+f.term+". It steers nothing until it merges.","gold");
}
DLG_EXT.ontedit=function(id){
  var o=ontById(id);
  if(!o)return noSuch("Ontology note");
  if(o.retiring)return {t:o.term+" is being retired",w:false,
   b:'<div class="note">A pull request removes this note. Close that pull request before you change the definition, or the two write over each other.</div>',
   f:'<button class="btn" onclick="closeDialog()">Close</button>'};
  return {t:"Edit "+o.term,w:false,
   b:ontForm(o,"oe")+
    '<div class="note">Saving opens a pull request against <span class="mono">'+h(ontFile(o))+'</span>. The definition in force does not change until it merges.</div>',
   f:'<button class="btn" onclick="closeDialog()">Cancel</button>'+
    '<button class="btn danger" onclick="openDialog(\'ontretire\',\''+h(o.id)+'\')">Retire</button>'+
    '<button class="btn primary" onclick="ontSave(\''+h(o.id)+'\')">Open the pull request</button>'};
};
function ontSave(id){
  var o=ontById(id); if(!o)return;
  var f=ontRead("oe");
  if(!f.term)return act("Name the term before you open the pull request.");
  if(!f.body)return act("Write the definition before you open the pull request.");
  o.term=f.term; o.noteKind=f.noteKind; o.body=f.body; o.entities=f.entities;
  o.token_cost=ontCost(f.body); o.hash=ontHash(f.body);
  var p=ontPr(o,"mod","An operator changed the definition of "+f.term+".");
  closeDialog(); render();
  act("Opened "+p.pr+" for "+f.term+". The definition in force does not change until it merges.","gold");
}
DLG_EXT.ontretire=function(id){
  var o=ontById(id);
  if(!o)return noSuch("Ontology note");
  if(o.retiring)return {t:o.term+" is already being retired",w:false,
   b:'<div class="note">A pull request removes this note and is waiting on its checks. Open it on the Changes tab.</div>',
   f:'<button class="btn" onclick="closeDialog()">Close</button>'};
  return {t:"Retire "+o.term+"?",w:false,
   b:'<div class="note">A note is a file, so retiring it is a pull request that removes <span class="mono">'+h(ontFile(o))+'</span>. It keeps informing the model until that merges, and the row says so in the meantime.</div>'+
    '<div class="warn">Once the removal merges, no agent is told that <b>'+h(o.term)+'</b> means what this note says it means.</div>',
   f:'<button class="btn" onclick="closeDialog()">Keep it</button>'+
    '<button class="btn danger" onclick="ontRetire(\''+h(o.id)+'\')">Open the pull request</button>'};
};
function ontRetire(id){
  var o=ontById(id); if(!o)return;
  o.retiring=true;
  var p=ontPr(o,"del","An operator retired the definition of "+o.term+".");
  closeDialog(); render();
  act("Opened "+p.pr+" to remove "+o.term+". It keeps informing the model until that merges.","gold");
}

/* ---- Gates: the second compilation ---- */
function stgGateEdit(g){
  var base="#/"+ORG.slug+"/";
  if(g.edit==="mandate") return ['Open the mandate',"go('"+base+(g.ws||S.ws)+"/agents/"+g.agent+"/mandates/"+g.mandate+"')"];
  if(g.edit==="record") return ['Open the record',"go('"+crecUrl(g.record)+"')"];
  /* This gate is about agents that hold no mandate, so it opens the registry: Tools never had
     a Mandates tab and the link to one went nowhere. */
  if(g.edit==="agents") return ['Open Agents',"go('"+base+S.ws+"/agents')"];
  if(g.edit==="tools/switches") return ['Open the kill switches tab',"go('"+base+S.ws+"/tools/switches')"];
  return ['Open the policy tab',"go('"+base+S.ws+"/tools/policy')"];
}
function stgPolicyTab(w){
  var L=stgGates(w.slug), tok=0; L.forEach(function(g){tok+=g.token_cost;});
  var rows=L.map(function(g){var e=stgGateEdit(g);
    return '<tr><td><b>'+h(g.gate)+'</b><span class="sub mono">'+h(g.source)+'</span></td><td>'+gate(g.outcome)+'</td>'+
     '<td style="font-size:12.5px">'+h(g.applies)+'</td>'+
     '<td style="max-width:48ch"><span class="stg-notice">'+h(g.body)+'</span><span class="sub mono">'+h(g.id)+'</span></td>'+
     '<td class="num">'+tokn(g.token_cost)+' tok</td>'+
     '<td><button class="btn sm" onclick="'+e[1]+'">'+h(e[0])+'</button></td></tr>';}).join("");
  return '<div class="grid g2" style="margin-bottom:14px">'+
   '<div class="panel"><div class="panel-h"><h3>Text compilation</h3></div><div class="panel-b"><p class="muted" style="margin:0;font-size:13px">Every item compiles to text the model reads. Text is advisory: it is ranked, budgeted, and may be dropped. The library is this plane.</p></div></div>'+
   '<div class="panel"><div class="panel-h"><h3>Gate compilation</h3></div><div class="panel-b"><p class="muted" style="margin:0;font-size:13px">An item with an enforcement grant also compiles to a gate. A gate is deterministic, never budgeted and never ranked, and it answers when the index is down. This tab is that plane, and it is why it is called Gates rather than Policy: Tools has a Policy tab, and it decides tool calls, not text.</p></div></div></div>'+
   '<div class="panel"><div class="panel-h"><h3>Gate notices</h3>'+
   '<span class="b b-q" style="margin-left:auto">'+L.length+'</span></div>'+
   '<div class="tw"><table><thead><tr><th>Gate</th><th>Outcome</th><th>Applies to</th><th>Gate notice</th><th>Notice cost</th><th>Edited on</th></tr></thead><tbody>'+rows+'</tbody></table></div>'+
   '<div class="panel-b"><div class="note">A gate notice is one line, so the agent does not spend turns walking into a denial. The assembler puts every notice that applies at the head of the stable prefix and never drops one. Gates are edited where they always were: decision rules and kill switches on Tools, a mandate on its own page. Nothing is edited here.</div>'+
   '<div class="note" style="margin-top:10px">What a gate can refuse depends on the tier. For actions routed through oxagen, oxagen refuses the call. On the <span class="mono">harness</span> tier the four blocking hook events refuse a harness-native call: client-attested and fail-open. No screen says more than that.</div></div></div>';
}

/* ---- Preview ---- */
function pvPrompt(){
  if(S.pv.text!=null) return S.pv.text;
  var P=STG_PREVIEW.prompts;for(var i=0;i<P.length;i++){if(P[i].id===S.pv.preset)return P[i].text;}return P[0].text;
}
function pvAgent(slug){S.pv.agent=slug;var A=stgAgent(slug);if(S.pv.text==null)S.pv.preset=A.prompt;stgTab("preview");}
function pvPreset(id){S.pv.preset=id;S.pv.text=null;render();}
/* typing repaints the result and nothing else, so the caret stays where it is */
function pvInput(v){S.pv.text=v;var o=el("pvOut");if(o){o.innerHTML=pvResult(assembleSteering(S.pv.agent,v));listify();if(isPhone())cardTables();}}
function pvRow(it,extra){
  return '<li class="ro-n stg-n"><span class="ro-tick" aria-hidden="true"></span><div class="ro-b"><div class="ro-t">'+stgItemLink(it)+stgKindChip(it)+forceBadge(it.force)+
   '<span class="b b-q mono">'+tokn(it.tok)+' tok</span>'+(extra||'')+'</div><div class="ro-w"><span class="ro-note">'+h(it.body)+'</span></div></div></li>';
}
function pvPart(title,point,sub,rows,empty){
  return '<section class="ro stg-part"><div class="ro-h"><p class="eyebrow q" style="margin:0">'+title+'</p><span class="ro-tally">'+point+'</span></div>'+
   (sub?'<p class="stg-sub">'+sub+'</p>':'')+
   (rows?'<ol class="ro-spine">'+rows+'</ol>':'<p class="dim" style="font-size:12.5px;margin:0">'+empty+'</p>')+'</section>';
}
function stgCutTable(M){
  if(!M.cut.length) return '<p class="dim" style="font-size:12.5px;margin:0">Nothing was cut.</p>';
  return '<div class="tw"><table><thead><tr><th>Item</th><th>Kind</th><th>Force</th><th>Token cost</th><th>Cut because</th><th>Why</th></tr></thead><tbody>'+
   M.cut.map(function(c){return '<tr><td>'+stgItemLink(c.it)+'</td><td data-v="'+h(stgKindLabel(c.it))+'">'+stgKindChip(c.it)+'</td><td>'+forceBadge(c.it.force)+'</td>'+
    '<td class="num">'+tokn(c.it.tok)+' tok</td><td><span class="b '+STG_REASON[c.reason]+'">'+(c.reason==="over budget"?'<span class="d"></span>':'')+h(c.reason)+'</span></td>'+
    '<td style="font-size:12.5px">'+h(c.why)+'</td></tr>';}).join("")+'</tbody></table></div>';
}
function pvResult(M){
  var B=M.budget, a=M.agent;
  var undelivered=M.delivered?'':'<div class="warn" style="margin-bottom:14px"><b>Nothing below reaches this agent today.</b> '+h(a.name)+' is on the <span class="mono">observe</span> tier: its runs are recorded and no hook is installed, so oxagen has no injection point. This is what the assembler would deliver on the <span class="mono">harness</span> tier.</div>';
  var skills=M.skills.map(function(s){
    return '<li class="ro-n stg-n"><span class="ro-tick" aria-hidden="true"></span><div class="ro-b"><div class="ro-t"><button class="lnk mono" style="font-size:12px" onclick="openDialog(\'skill\',\''+h(s.id)+'\')">'+h(s.path)+'</button>'+
     '<span class="b b-q mono">@'+h(s.ver)+'</span><span class="b b-q mono">'+tokn(s.tokens)+' tok if loaded</span></div>'+
     '<div class="ro-w"><span class="ro-note">Loaded by the harness’s own progressive disclosure, not by the assembler. Only its description line competes above.</span></div></div></li>';}).join("");
  return undelivered+
   '<div class="grid g2" style="margin-bottom:14px">'+
    '<div class="panel pad">'+stgMeter("Stable prefix · SessionStart additional context",M.bytes,B.sessionStartBytes,"bytes",tokn(M.tok.prefix)+' tok: compile header '+B.compileHeaderTok+', gate notices '+tokn(M.tok.gates)+', must and should '+tokn(M.tok.prefix-M.tok.gates-B.compileHeaderTok)+'. Capped at 16 KiB.')+'</div>'+
    '<div class="panel pad">'+stgMeter("Volatile selection · token budget",M.tok.volatile,B.volatileTok,"tok",M.volatile.length+' of '+(M.volatile.length+M.cut.filter(function(c){return c.reason==="over budget"&&c.it.rank;}).length)+' ranked items fit. '+plural(M.cut.length,"item")+' cut in all.')+'</div></div>'+
   '<div class="panel pad" style="margin-bottom:14px">'+
   pvPart("1 · Stable prefix","SessionStart additional context · capped at 16 KiB","Gate notices first, then <span class=\"mono\">must</span>, then <span class=\"mono\">should</span>. Cached in the signed bundle, so it still arrives when the machine is offline. Never ranked.",
     M.gates.map(function(it){return pvRow(it,gate(it.outcome));}).join("")+M.prefix.map(function(it){return pvRow(it,it.grant?compileChip(it.grant):'');}).join(""),"Nothing in the stable prefix.")+
   pvPart("2 · Volatile selection","UserPromptSubmit additional context · "+tokn(B.volatileTok)+" tok budget","<span class=\"mono\">may</span> and <span class=\"mono\">info</span> items, ranked against this prompt"+(M.words.length?' ('+M.words.map(h).join(", ")+')':'')+" and packed until the budget is spent.",
     M.volatile.map(function(it){return pvRow(it,'<span class="b b-q">rank '+it.rank+' · relevance '+it.score+'</span>');}).join(""),"No may or info item fit this prompt.")+
   pvPart("3 · Skills","files in the checkout · "+h(M.repo),M.sync?'Sync is <b>'+h((SYNC_STATE[M.sync.state]||{}).l||M.sync.state)+'</b> for this repository'+(M.sync.synced?', at <span class="mono">'+h(M.sync.synced)+'</span>':'')+'.':"",
     skills,"No skill is synced into this repository.")+
   '</div>'+
   '<div class="panel"><div class="panel-h"><h3>Manifest cuts</h3><span class="b b-q" style="margin-left:auto">'+M.cut.length+' cut · recorded on a run as a <span class="mono">steering.manifest</span> frame</span></div>'+
   (M.cut.length?stgCutTable(M):'<div class="panel-b">'+stgCutTable(M)+'</div>')+
   '<div class="panel-b"><div class="note">Two injection points are not on this page. MCP tool results carry their own text, call by call. The model request itself is written at the proxy on the <span class="mono">gateway</span> and <span class="mono">contained</span> tiers, and the Context tab of a run shows what it carried.</div></div></div>';
}
var SYNC_STATE={"in-sync":{b:"b-allowed",l:"in sync"},behind:{b:"b-approval",l:"behind"},unbound:{b:"b-q",l:"not bound"}};
function stgPreviewTab(w){
  var L=stgAgents().filter(function(x){return x.a.ws===w.slug;});
  if(!L.length) return '<div class="panel pad"><p class="muted" style="margin:0">No agent in this workspace is set up for preview.</p></div>';
  if(!L.some(function(x){return x.slug===S.pv.agent;})){S.pv.agent=L[0].slug;if(S.pv.text==null)S.pv.preset=L[0].prompt;}
  var A=stgAgent(S.pv.agent), M=assembleSteering(S.pv.agent,pvPrompt());
  return '<div class="panel pad" style="margin-bottom:14px"><div class="stg-pv">'+
   '<div class="field" style="margin:0"><label for="pvSel">Agent</label><select id="pvSel" onchange="pvAgent(this.value)">'+L.map(function(x){
     return '<option value="'+h(x.slug)+'"'+(x.slug===S.pv.agent?' selected':'')+'>'+h(x.a.name)+' · '+h(x.a.harnessLabel)+' · '+h(x.a.tier)+'</option>';}).join("")+'</select>'+
    '<div class="hint">'+tierBadge(A.a.tier)+' works in <span class="mono">'+h(A.repo)+'</span></div></div>'+
   '<div class="field" style="margin:0"><label for="pvText">Prompt</label><textarea id="pvText" rows="2" oninput="pvInput(this.value)" placeholder="Type what the operator would type">'+h(pvPrompt())+'</textarea></div></div>'+
   '<div class="kf" role="group" aria-label="Pick a prompt" style="padding:10px 0 0;border:0">'+STG_PREVIEW.prompts.map(function(p){
     return '<button class="btn sm" aria-pressed="'+(S.pv.text==null&&S.pv.preset===p.id)+'" onclick="pvPreset(\''+p.id+'\')">'+h(p.text)+'</button>';}).join("")+'</div></div>'+
   '<div id="pvOut">'+pvResult(M)+'</div>';
}

/* ---- the manifest on a run ----
   One frame per run, kind steering.manifest, written beside context.assembled. It is the
   assembler's own account, so it is rebuilt here from the same function with the bundle version
   the run started on: a record merged afterwards is not in it. */
function runManifest(R){
  var a=agent(R.agent); if(!a) return null;
  var slug=defSlug(a); if(!STG_PREVIEW.agents.some(function(x){return x.slug===slug;})) return null;
  var m=STG_MANIFESTS[R.id]||{beside:1,bundle:41,prompt:R.taskTitle,repo:null};
  var M=assembleSteering(slug,m.prompt,{asOf:m.bundle,repo:m.repo||undefined});
  M.meta=m; return M;
}
function mfNode(it,state,cls,extra,why){
  return '<li class="ro-n k-record s-'+cls+'"><span class="ro-dot" aria-hidden="true">'+roSvg(it.kind==="policy"?"gate":it.kind==="skill"?"file":"record")+'</span>'+
   '<div class="ro-b"><div class="ro-t">'+stgItemLink(it)+'<span class="b '+state[0]+'">'+(state[2]?'<span class="d"></span>':'')+h(state[1])+'</span>'+
   stgKindChip(it)+forceBadge(it.force)+'<span class="b b-q mono">'+tokn(it.tok)+' tok</span>'+(extra||'')+'</div>'+
   '<div class="ro-w"><span class="ro-note">'+h(why||it.body)+'</span></div></div></li>';
}
function runManifestPanel(R){
  var M=runManifest(R); if(!M) return '';
  var open=!!S.mfCut, m=M.meta, observe=R.tier==="observe";
  var body=M.gates.map(function(it){return mfNode(it,["b-allowed","rendered",1],"posted",gate(it.outcome));}).join("")+
   M.prefix.map(function(it){return mfNode(it,["b-allowed","rendered",1],"posted",'<span class="b b-q">stable prefix</span>');}).join("")+
   M.volatile.map(function(it){return mfNode(it,["b-allowed","rendered",1],"posted",'<span class="b b-q">volatile · rank '+it.rank+'</span>');}).join("");
  var cuts=(open?M.cut:M.cut.slice(0,3)).map(function(c){return mfNode(c.it,["b-q","cut: "+c.reason,0],"withheld",'',c.why);}).join("");
  return '<section class="ro stg-mf" aria-label="Steering manifest" style="margin-bottom:16px">'+
   '<div class="ro-h"><p class="eyebrow q" style="margin:0">Manifest frame</p>'+
   '<span class="ro-tally">'+(M.gates.length+M.prefix.length+M.volatile.length)+' rendered · '+M.cut.length+' cut · '+tokn(M.tok.total)+' tok</span>'+
   '<button class="ro-link" onclick="S.pv.agent=\''+h(M.slug)+'\';S.pv.text='+h(JSON.stringify(m.prompt))+';go(stgHash(\'compiler\',\''+h(M.agent.ws)+'\'))">Open in the compiler</button></div>'+
   (observe?'<div class="warn" style="margin:0 0 10px"><b>Assembled, not delivered.</b> This run is on the <span class="mono">observe</span> tier. No hook was installed, so nothing below reached the agent.</div>':'')+
   '<ol class="ro-spine">'+body+cuts+
   (M.cut.length>3?'<li class="ro-n ro-fold"><span class="ro-tick" aria-hidden="true"></span><button class="ro-link" onclick="S.mfCut='+(!open)+';render()">'+(open?'fold the cuts back':(M.cut.length-3)+' more cut')+'</button></li>':'')+'</ol>'+
   '<p class="ro-foot">Written once, beside frame '+m.beside+' (<span class="mono">context.assembled</span>), on bundle v'+m.bundle+' for the prompt “'+h(m.prompt)+'”. '+
   'The stable prefix went in at SessionStart, the volatile selection at UserPromptSubmit. A recorded frame never changes: a record merged after this run started is not in it.</p></section>';
}

/* One word per scope. The bundle and the workspace instructions say `org`; the record generator
   says `organization`. Both reach the library, so the word is normalised where it is read. */
var STG_SCOPE_ALIAS={organization:"org"};
function stgScope(it){var s=(it&&it.scope)||"workspace";return STG_SCOPE_ALIAS[s]||s;}

/* ---- Library: every shelf at once ----
   One table over stgLibraryItems(), the list every count on the tab reads. A shelf filters this
   list; it never holds a different one. Order is the assembler's: a record, an instruction, a
   skill, a definition, a memory, and within a kind by force. */
function stgLibraryAll(w,only){
  var L=stgLibraryItems(w.slug).filter(function(it){return !only||it.kind===only;}).sort(function(x,y){
    return (STG_KIND_ORDER[x.kind]-STG_KIND_ORDER[y.kind])||
           (STG_FORCE_ORDER[x.force]-STG_FORCE_ORDER[y.force])||(x.id<y.id?-1:1);});
  var tok=0, byKind={}, grants=0;
  L.forEach(function(it){tok+=it.tok||0; byKind[it.kind]=(byKind[it.kind]||0)+1; if(it.grant)grants++;});
  var rows=L.map(function(it){
    return '<tr><td style="max-width:54ch"><b style="font-weight:500">'+h(it.body||"")+'</b>'+
      '<span class="sub">'+stgItemLink(it)+'</span></td>'+
     '<td>'+stgKindChip(it)+'</td><td>'+forceBadge(it.force)+'</td>'+
     '<td>'+h(stgScope(it))+(it.repo?'<span class="sub mono">'+h(it.repo)+'</span>':'')+
      (it.agent?'<span class="sub mono">'+h(it.agent)+'</span>':'')+'</td>'+
     '<td>'+compileChip(it.grant)+'</td>'+
     '<td class="num">'+tokn(it.tok||0)+' tok</td>'+
     '<td class="mono" style="font-size:11px;max-width:34ch">'+h(it.provenance||"—")+'</td></tr>';}).join("");
  var kinds=Object.keys(byKind).sort(function(a,b){return STG_KIND_ORDER[a]-STG_KIND_ORDER[b];})
    .map(function(k){return '<span class="mono">'+h(STG_KIND[k]||k)+'</span> '+byKind[k];}).join(' · ');
  return '<div class="grid g4" style="margin-bottom:14px">'+
   '<div class="stat"><span class="k">Items</span><span class="v">'+L.length+'</span><span class="s">everything that can steer an agent here</span></div>'+
   '<div class="stat"><span class="k">By kind</span><span class="v" style="font-size:15px;padding-top:6px">'+(kinds||"—")+'</span><span class="s">one shape, every kind</span></div>'+
   '<div class="stat"><span class="k">Compiled size</span><span class="v">'+tokn(tok)+' <small>tok</small></span><span class="s">if every item were rendered at once, which no run does</span></div>'+
   '<div class="stat"><span class="k">Carry a grant</span><span class="v">'+grants+'</span><span class="s">these compile to a gate as well as to text</span></div></div>'+
   '<div class="note" style="margin-bottom:14px">A shelf is a filter on this list, never a second list. The assembler reads exactly these items, in this order, and decides per run which of them a given agent is shown. Assignments says who receives what; the compiler shows one decision in full.</div>'+
   '<div class="panel"><div class="panel-h"><h3>'+(only?h(STG_LIB_LABEL[only]||only):'Everything written down')+'</h3>'+
   '<span class="b b-q" style="margin-left:auto">'+L.length+'</span>'+
   '<button class="btn sm" onclick="stgTab(\'assignments\')">Who receives it</button></div>'+
   '<div class="tw"><table><thead><tr><th>Item</th><th>Kind</th><th>Force</th><th>Scope</th><th>Compiles to</th><th>Token cost</th><th>Source</th></tr></thead><tbody>'+rows+'</tbody></table></div></div>'+
   /* The two planes (steering.md "Two planes that never merge"), said on the page itself: the
      Library is text, and a gate is decided somewhere else. */
   '<div class="note" style="margin-top:14px">Steering is what the model reads: advisory, ranked, budgeted, and it may be dropped. Gating is what gets refused: deterministic, never budgeted, never ranked. The Library, Assignments, and the Compiler are the text plane. Gates is the gate plane.</div>';
}

/* ---- Assignments: which agent receives what ----
   Steering is assigned by scope, not by a picker: an item reaches an agent because the workspace,
   the repository or the agent name matches, and because a hook is installed to deliver it. The
   table is that answer, per agent, run through the same assembler the compiler tab shows. */
function stgAssignTab(w){
  var L=stgAgents().filter(function(x){return x.a.ws===w.slug;});
  if(!L.length) return '<div class="panel pad"><p class="muted" style="margin:0">No agent in this workspace is set up for steering.</p></div>';
  var P={}; STG_PREVIEW.prompts.forEach(function(p){P[p.id]=p.text;});
  var rows=L.map(function(x){
    var M=assembleSteering(x.slug,P[x.prompt]||x.prompt), a=x.a;
    return '<tr><td>'+agentCard(a,{link:true,sub:h(a.harnessLabel)})+'</td>'+
     '<td class="mono" style="font-size:11.5px">'+h(x.repo)+'</td>'+
     '<td>'+tierBadge(a.tier)+'<span class="sub">'+(M.delivered?'hooks deliver it':'no hook: assembled, not delivered')+'</span></td>'+
     '<td class="num">'+M.gates.length+'</td>'+
     '<td class="num">'+M.prefix.length+'<span class="sub">'+tokn(M.tok.prefix)+' tok</span></td>'+
     '<td class="num">'+M.volatile.length+'<span class="sub">'+tokn(M.tok.volatile)+' tok</span></td>'+
     '<td class="num">'+(M.cut.length?'<span class="b b-q">'+M.cut.length+'</span>':'0')+'</td>'+
     '<td class="num">'+(M.skills.length||0)+'</td>'+
     '<td class="num">'+tokn(M.tok.total)+' tok</td>'+
     '<td><button class="btn sm" onclick="pvAgent(\''+h(x.slug)+'\')">Open the compiler</button></td></tr>';}).join("");
  /* The inverse view: what decides reach. Scope is the only assignment mechanism, so it is
     spelled out rather than left to be inferred from the table above. It counts the library, not
     the assembler's selection, so this panel and the Library tab report one number. */
  var items=stgLibraryItems(w.slug), sc={};
  items.forEach(function(it){var k=stgScope(it); sc[k]=(sc[k]||0)+1;});
  var SC=[["org","Every workspace in the organization."],
          ["workspace","Every agent in this workspace."],
          ["repository","Only an agent whose run works in that repository."],
          ["agent","Only the agent named on the item."]];
  var scrows=SC.filter(function(s){return sc[s[0]];}).map(function(s){
    return '<tr><td><span class="b b-q mono">'+h(s[0])+'</span></td><td class="num">'+sc[s[0]]+'</td><td>'+h(s[1])+'</td></tr>';}).join("");
  return '<div class="note" style="margin-bottom:14px">Nobody assigns a record to an agent. An item reaches an agent when its scope matches the run, and it is delivered when a hook is installed on the runtime. An agent on the <span class="mono">observe</span> tier is still assembled for, and receives nothing.</div>'+
   '<div class="panel"><div class="panel-h"><h3>What each agent receives</h3>'+
   '<span class="b b-q" style="margin-left:auto">'+plural(L.length,"agent")+'</span>'+
   '<button class="btn sm" onclick="stgTab(\'library\')">Open the library</button></div>'+
   '<div class="tw"><table><thead><tr><th>Agent</th><th>Repository</th><th>Delivery</th><th>Gates</th><th>Stable prefix</th><th>Volatile</th><th>Cut</th><th>Skills</th><th>Per run</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div>'+
   '<div class="panel-b"><div class="note">Each row is one assembly, for the prompt that agent is usually given. Change the prompt and the volatile selection changes with it; the gates and the stable prefix do not.</div></div></div>'+
   '<div class="panel" style="margin-top:14px"><div class="panel-h"><h3>Scope</h3>'+
   '<span class="b b-q" style="margin-left:auto">'+plural(items.length,"item")+'</span></div>'+
   '<div class="tw"><table><thead><tr><th>Scope</th><th>Items</th><th>Reaches</th></tr></thead><tbody>'+scrows+'</tbody></table></div>'+
   '<div class="panel-b"><div class="note">A repository record may narrow what a workspace record allows. It may never widen it, and the checks enforce that before a merge.</div></div></div>';
}

/* ---- Library: the record shelf ---- */
function stgRecordsTab(w){
    /* The panel is headed "Published records" and the tab badge counts published, so the
       list and its kind chips count published too. Archiving is a Context PR that sets status = "archived". */
    var rk=S.recKind||"", kc={};
    /* Newest first. The list had no order at all, so a record you merged a moment ago landed
       wherever the fixture happened to put it, which on a workspace with sixty published records
       means the one thing you came here to see is the one thing you cannot find. */
    var pub=RECORDS.filter(function(r){return r.status==="published";})
      .sort(function(a,b){return String(b.pub||"").localeCompare(String(a.pub||""));});
    pub.forEach(function(r){kc[r.kind]=(kc[r.kind]||0)+1;});
    var shown=pub.filter(function(r){return !rk||r.kind===rk;});
    return '<div class="panel"><div class="panel-h"><h3>Published records</h3>'+
     '</div>'+
     '<div class="kf" role="group" aria-label="Filter records by kind">'+
     '<button class="btn sm" aria-pressed="'+(!rk)+'" onclick="S.recKind=\'\';render()">All <span class="dim">'+pub.length+'</span></button>'+
     Object.keys(KINDS).map(function(k){return '<button class="btn sm k-'+k+'" aria-pressed="'+(rk===k)+'" title="'+h(KINDS[k].d)+'" onclick="S.recKind=\''+k+'\';render()">'+kindSvg(k)+h(KINDS[k].l)+'<span class="dim">'+(kc[k]||0)+'</span></button>';}).join("")+'</div>'+
     '<div class="recs">'+(shown.length?shown.map(function(r){
       return recordCard(r,{item:true,right:(r.isNew?'<span class="b b-proven" title="published by the last merge">new · bundle v'+STEER_BUNDLE.v+'</span>':'')+
        '<span class="b b-allowed"><span class="d"></span>published</span>'+
        '<button class="btn sm" onclick="go(\''+crecUrl(r.id)+'\')">Open</button>'});}).join(""):'<div class="panel-b dim">No record of that kind in this workspace.</div>')+'</div>'+
     '<div class="panel-b" style="border-top:1px solid var(--border)"><div class="note">Every record compiles to text. A record with an enforcement grant also compiles to a gate, which is listed on Policy with the notice it puts back into steering. A record can never grant authority: the checks accept only a require or forbid constraint. A repository record may narrow what a workspace record allows. It cannot widen it.</div></div></div>'+
     '<div class="grid g2" style="margin-top:14px">'+
     '<div class="panel"><div class="panel-h"><h3>On disk</h3></div><div class="panel-b">'+
     '<pre>.oxagen/\n  workspace.toml             <span class="c"># linked repos, providers, budgets</span>\n'+
     '  rules/\n    governance.toml          <span class="c"># mode = team</span>\n'+
     '    promotions.jsonl         <span class="c"># hash-chained ledger (regulated mode)</span>\n'+
     '    ctx.release.notes-format.toml\n    ctx.release.never-merge.toml\n    ctx.platform.changelog-once.toml\n'+
     (stgRecord(CTXPR.record.id)?'    '+h(CTXPR.record.id)+'.toml  <span class="c"># merged in '+h(CTXPR.pr)+'</span>\n':'')+
     '  skills/&lt;name&gt;/SKILL.md     <span class="c"># governed files, delivered by sync</span>\n'+
     '  ontology/*.toml            <span class="c"># entity and term definitions</span>\n'+
     '  proposals/*.toml           <span class="c"># candidates; steer nothing</span>\n'+
     '  agents/&lt;slug&gt;.toml         <span class="c"># one per agent</span></pre>'+
     '<div class="note" style="margin-top:12px">stella symlinks into this directory rather than copying it, so its loader and its CI validation work unchanged on the same files with no second copy that could drift. oxagen reads <span class="mono">.oxagen/</span> and nothing else.</div></div></div>'+
     '<div class="panel"><div class="panel-h"><h3>Injection points</h3><span class="b b-q" style="margin-left:auto">five points</span></div><div class="panel-b">'+
     '<p class="muted" style="font-size:12.5px;margin:0 0 12px">The harness owns the context window. oxagen competes for its own slice of it, at exactly these points, and every delivery is recorded.</p>'+
     '<ul class="chain stg-inj"><li class="on"><span class="h">1 · SessionStart additional context</span><div>The stable prefix: gate notices, then <span class="mono">must</span> and <span class="mono">should</span>. Capped at 16 KiB, cached in the signed bundle, works offline.</div></li>'+
     '<li class="on"><span class="h">2 · UserPromptSubmit additional context</span><div>The volatile selection: <span class="mono">may</span> and <span class="mono">info</span>, picked for the prompt under a token budget.</div></li>'+
     '<li class="on"><span class="h">3 · MCP tool results</span><div>What a governed tool call returns, a denial and its reason included.</div></li>'+
     '<li class="on"><span class="h">4 · Files in the checkout</span><div>Skills, delivered by sync and loaded by the harness’s own progressive disclosure.</div></li>'+
     '<li class="on"><span class="h">5 · The model request itself</span><div>Written at the proxy on the <span class="mono">gateway</span> and <span class="mono">contained</span> tiers: the stable prefix and the volatile selection, counted as <span class="mono">steering_tokens</span> and <span class="mono">context_frame_tokens</span>.</div></li></ul></div></div></div>';
}

function pSteering(){
  var w=ws(), t=tab("steering","library");
  if(t==="skills") return pSkills();
  if(STG_LIB_KIND[t]){ S.libKind=STG_LIB_KIND[t]; t="library"; }
  else if(t==="policy") t="gates";
  else if(t==="preview") t="compiler";
  if(!STG_TAB_KEYS[t]) t="library";
  if(S.state==="loading") return skeleton();
  if(S.state==="error") return errorState("Steering","503 record_index_unavailable");
  if(S.state==="denied") return deniedState("this workspace’s steering","steering.read on "+w.slug);
  var on=t==="prs"?"proposals":t;
  var write='<button class="btn primary" onclick="wzOpen(\'record\')">Write a context record</button>';
  if(S.state==="empty"){
    /* The library's empty state is the shelf's, so the reason names the thing that is missing. */
    var E={
     library:["Nothing steers this workspace yet","Published records live in <span class=\"mono\">.oxagen/rules/</span> on "+h(w.main)+". A record becomes published by being merged, never by being saved here.",write],
     memory:["Nothing has been recalled yet","Memory is what an agent’s own runs leave behind. No run in this workspace has written one, so nothing competes from here.",""],
     ontology:["No ontology notes yet","A note defines one entity or one term the way this workspace uses it. Notes are files under <span class=\"mono\">.oxagen/ontology/</span> on "+h(w.main)+", published by a merge.",write],
     assignments:["No agent receives steering here","Steering reaches an agent through a hook on its runtime. No agent in this workspace is enrolled, so nothing is delivered.",'<button class="btn" onclick="go(\'#/'+ORG.slug+'/'+w.slug+'/agents\')">Open Agents</button>'],
     gates:["No gate applies to this workspace yet","No decision rule, mandate or kill switch reaches an agent here, so no gate notice enters steering. Gates are written on Tools and on a mandate’s own page.",'<button class="btn" onclick="go(\'#/'+ORG.slug+'/'+w.slug+'/tools/policy\')">Open the policy tab</button>'],
     proposals:["No proposals yet","Nothing has been proposed from this workspace’s runs, and no pull request is open against <span class=\"mono\">.oxagen/rules/</span>. A proposal steers nothing until a person opens a pull request from it and someone merges that.",write],
     compiler:["Nothing to compile yet","No item is published in this workspace, so the assembler has nothing to select from. Publish a record and this tab shows what an agent would receive.",write]};
    var ek=on==="library"?({record:"library",memory:"memory",ontology:"ontology"}[S.libKind]||"library"):on;
    var e=E[ek]||E.library;
    return stgHub(on,emptyState(e[0],e[1],e[2]),'');
  }

  /* the page header gives up the gold when the tab below holds the one primary action */
  var tabPrimary=(t==="prs"&&(S.ctxpr.st==="passed"||S.ctxpr.st==="none"))||(t==="proposals"&&S.prpSel===CTXPR.prp&&S.ctxpr.st==="none");
  var body="";
  if(t==="library"){
    body=S.libKind==="record"?stgRecordsTab(w):S.libKind==="memory"?stgMemoryTab(w):
         S.libKind==="ontology"?stgOntologyTab(w):
         S.libKind==="instruction"?stgLibraryAll(w,"instruction"):stgLibraryAll(w);
  } else if(t==="assignments"){
    body=stgAssignTab(w);
  } else if(t==="gates"){
    body=stgPolicyTab(w);
  } else if(t==="compiler"){
    body=stgPreviewTab(w);
  } else {
    var openPRs=stgOpenCount();
    var seg='<div class="kf stg-seg" role="group" aria-label="Proposals or pull requests">'+
     '<button class="btn sm" aria-pressed="'+(t==="proposals")+'" onclick="stgTab(\'proposals\')">Candidates <span class="dim">'+PROPOSALS.length+'</span></button>'+
     '<button class="btn sm" aria-pressed="'+(t==="prs")+'" onclick="stgTab(\'prs\')">Context PRs <span class="dim">'+openPRs+'</span></button>'+
     '<span class="dim" style="font-size:12px;margin-left:6px;align-self:center">a record becomes a proposal, a proposal becomes a pull request, a merge publishes it</span></div>';
    if(t==="proposals"){
      var sel=S.prpSel&&prpById(S.prpSel);
      body=seg+(sel?prpDetail(sel):'<div class="panel"><div class="panel-h"><h3>Proposals</h3>'+
       '<button class="btn sm" style="margin-left:auto" onclick="wzOpen(\'record\')">Write a context record</button></div>'+
       '<div class="recs">'+
       PROPOSALS.map(function(p){
        var s=prpStats(p.id);
        return recordCard({kind:p.kind,force:p.force,st:p.st,scope:"workspace",id:p.lineage},{
         right:prpBadge(p)+'<button class="btn sm" onclick="S.prpSel=\''+h(p.id)+'\';render()">Review</button>',
         meta:'<span>from <b>'+h(p.from)+'</b></span><span>'+h(s.meta.support?s.meta.support(s):p.support)+'</span><span class="mono">'+h(p.id)+'</span>'});}).join("")+
       '</div></div>');
    } else body=seg+ctxprTab();
  }
  return stgHub(on,body,'<button class="btn'+(tabPrimary?'':' primary')+'" onclick="wzOpen(\'record\')">Write a context record</button>');
}


/* ============================== Runtimes ==============================
   A runtime is the host an agent runs on: a workstation, a CI runner, a hosted container. It is
   shared — several agents can run on one host, through one set of hooks — so it is an object of
   its own rather than a field on an agent. What a runtime earns is the tier, and the tier is what
   every claim on every other page is bounded by, so the ladder lives here.
   Nothing on this page enrolls a host; enrollment is an installer, run on the host itself. */
function rtById(id){for(var i=0;i<RUNTIMES.length;i++){if(RUNTIMES[i].id===id)return RUNTIMES[i];}return null;}
function rtAgents(id){return AGENTS.filter(function(a){return a.host===id;});}
function rtHealth(rt){
  var ok=rt.health==="ok";
  return '<span class="b b-'+(ok?"allowed":"approval")+'"><span class="d"></span>'+h(ok?"healthy":rt.health)+'</span>';
}
function rtWs(rt){var x=wsBySlug(rt.ws);return x?x.name:rt.ws;}

function pRuntimes(r){
  var w=ws();
  if(S.state==="loading") return skeleton();
  if(S.state==="error") return errorState("Runtimes","503 collector_unreachable");
  if(S.state==="denied") return deniedState("the runtimes of this workspace","runtime.read on "+w.slug);
  var L=RUNTIMES.filter(function(x){return x.ws===w.slug;});
  var sel=r&&r.id?rtById(r.id):null;
  var head='<div class="phead"><div class="t"><p class="eyebrow">'+h(w.name)+'</p><h1>Runtimes</h1>'+
   '<p>The hosts agents run on, and what each host’s seam earns.</p></div>'+
   '<div class="acts"><button class="btn primary" onclick="openDialog(\'wrap\')">Enroll a runtime</button></div></div>';
  if(S.state==="empty"||!L.length) return head+emptyState("No runtime is enrolled",
    "Until a host enrolls, an agent has an identity and a toolbelt but no hook is installed. Its runs are graded <span class=\"mono\">observe</span>, and no report can say more.",
    '<button class="btn primary" onclick="openDialog(\'wrap\')">Enroll a runtime</button>'+
    '<button class="btn" onclick="openDialog(\'register\')">Show CLI steps</button>');
  if(sel) return head+rtDetail(sel);

  var rows=L.map(function(rt){
    var ag=rtAgents(rt.id);
    return '<tr onclick="go(\'#/'+ORG.slug+'/'+w.slug+'/runtimes/'+h(rt.id)+'\')" style="cursor:pointer">'+
     '<td><b style="font-weight:500">'+h(rt.name)+'</b><span class="sub mono">'+h(rt.os)+'</span></td>'+
     '<td><span class="b b-q">'+h(rt.kind)+'</span></td>'+
     '<td>'+h(rt.harness)+' <span class="mono dim">'+h(rt.harnessV)+'</span></td>'+
     '<td>'+h(rt.model)+'</td>'+
     '<td>'+tierBadge(rt.tier)+'</td>'+
     '<td class="num">'+(ag.length||'<span class="dim">0</span>')+
       (ag.length?'<span class="sub mono">'+h(ag.map(function(a){return a.key;}).join(", "))+'</span>':'<span class="sub">enrolled, nothing assigned</span>')+'</td>'+
     '<td class="mono" style="font-size:11.5px">oxagend '+h(rt.collector)+
       '<span class="sub">'+(rt.gaps?h(rt.gaps+" telemetry gap"+(rt.gaps>1?"s":"")+" in 24h"):"0 gaps in 24h")+'</span></td>'+
     '<td class="num">'+rt.hookCount+' of 5'+(rt.hookCount<5?'<span class="sub">some calls are recorded, not decided</span>':'')+'</td>'+
     '<td>'+rtHealth(rt)+'</td>'+
     '<td class="mono" style="font-size:11px">'+h(rt.checkpoint)+'</td></tr>';}).join("");

  var deg=L.filter(function(x){return x.health!=="ok";}).length;
  var idle=L.filter(function(x){return !rtAgents(x.id).length;}).length;
  return head+
   '<div class="grid g4" style="margin-bottom:14px">'+
   '<div class="stat"><span class="k">Runtimes</span><span class="v">'+L.length+'</span><span class="s">'+idle+' with no agent assigned</span></div>'+
   '<div class="stat"><span class="k">Agents hosted</span><span class="v">'+L.reduce(function(n,x){return n+rtAgents(x.id).length;},0)+'</span><span class="s">a host is shared; its hooks see every one of them</span></div>'+
   '<div class="stat"><span class="k">Highest tier earned</span><span class="v" style="font-size:15px;padding-top:6px">'+
     tierBadge(L.slice().sort(function(a,b){return TIER_RANK[b.tier]-TIER_RANK[a.tier];})[0].tier)+
     '</span><span class="s">computed per run from what was actually routed</span></div>'+
   '<div class="stat"><span class="k">Degraded</span><span class="v">'+deg+'</span><span class="s">'+(deg?"a gap is a hole in the record, not a failed run":"every collector is reporting")+'</span></div></div>'+
   '<div class="panel"><div class="panel-h"><h3>Enrolled hosts</h3>'+
   '<span class="b b-q" style="margin-left:auto">'+L.length+'</span></div>'+
   '<div class="tw"><table><thead><tr><th>Runtime</th><th>Kind</th><th>Harness</th><th>Model surface</th><th>Tier</th>'+
   '<th>Agents</th><th>Collector</th><th>Hooks</th><th>Health</th><th>Last checkpoint</th></tr></thead><tbody>'+rows+'</tbody></table></div>'+
   '<div class="panel-b"><div class="note">The tier is a property of the seam, not of the agent: two agents on one host earn the same tier, and the same agent moved to a weaker host earns less. It is computed per run from what was actually routed and is never upgraded after the fact.</div></div></div>'+
   '<div class="panel" style="margin-top:14px"><div class="panel-h"><h3>The tier ladder</h3></div>'+
   '<div class="panel-b">'+tierLadder(null)+
   '<div class="note" style="margin-top:13px">Only <span class="mono">contained</span> earns the word enforced. On <span class="mono">observe</span> nothing is delivered and nothing can refuse, which is why an agent with no runtime still has an identity and a toolbelt and receives no steering.</div></div></div>';
}

function rtDetail(rt){
  var ag=rtAgents(rt.id), base="#/"+ORG.slug+"/"+S.ws;
  return '<div class="row" style="margin-bottom:14px"><button class="btn sm" onclick="go(\''+base+'/runtimes\')">← All runtimes</button></div>'+
   '<div class="grid">'+
   '<div class="panel"><div class="panel-h"><div style="flex:1;min-width:0"><h3>'+h(rt.name)+'</h3>'+
    '<p class="muted" style="margin:2px 0 0;font-size:12px">'+h(rt.kind+" · "+rt.os+" · started by "+rt.started)+'</p></div>'+
    rtHealth(rt)+'</div>'+
   '<div class="panel-b"><dl class="kv">'+
   '<dt>Workspace</dt><dd>'+h(rtWs(rt))+'</dd>'+
   '<dt>Owner</dt><dd class="mono">'+h(rt.owner)+'</dd>'+
   '<dt>Harness</dt><dd>'+h(rt.harness)+' <span class="mono dim">'+h(rt.harnessV)+'</span></dd>'+
   '<dt>Collector</dt><dd class="mono">oxagend '+h(rt.collector)+'<span class="sub">'+
     (rt.gaps?h(rt.gaps+" telemetry gap"+(rt.gaps>1?"s":"")+" in the last 24h"):"0 telemetry gaps in the last 24h")+'</span></dd>'+
   '<dt>Hook binary</dt><dd class="mono">oxagen-hook '+h(rt.collector)+' · fails closed against its cached bundle</dd>'+
   '<dt>Hooks written</dt><dd class="mono" style="font-size:11.5px">'+h(rt.hooks)+
     '<span class="sub" style="font-family:var(--font)">'+(rt.hookCount<5?'Fewer than five events are wired, so some calls are recorded rather than decided.':'Five run as command hooks. The first four can refuse.')+'</span></dd>'+
   '<dt>Model surface</dt><dd>'+h(rt.model)+'<span class="sub">'+(TIER_RANK[rt.tier]>=2?'every model call leaves through it; tokens are counted from the bytes that pass':'model traffic goes from the harness to its provider; routing it is the gateway tier')+'</span></dd>'+
   '<dt>Settings</dt><dd>'+h(rt.settings)+'</dd>'+
   '<dt>Tier earned</dt><dd>'+tierBadge(rt.tier)+'<span class="sub">computed per run from what was actually routed</span></dd>'+
   '<dt>Last checkpoint</dt><dd class="mono">'+h(rt.checkpoint)+' · chain intact</dd>'+
   (rt.note?'<dt>Note</dt><dd>'+h(rt.note)+'</dd>':'')+
   '</dl></div></div>'+
   '<div class="panel"><div class="panel-h"><h3>Agents on this host</h3>'+
    '<span class="b b-q" style="margin-left:auto">'+ag.length+'</span></div>'+
   (ag.length?'<div class="tw"><table><thead><tr><th>Agent</th><th>Operator</th><th>Tier</th><th>Principal</th><th>Runs 30d</th></tr></thead><tbody>'+
     ag.map(function(a){
       return '<tr onclick="go(\''+agentUrl(a)+'\')" style="cursor:pointer"><td>'+agentCard(a,{link:false})+'</td>'+
        '<td>'+h(a.operator)+'</td><td>'+tierBadge(a.tier)+'</td>'+
        '<td class="mono" style="font-size:11px">'+h(a.principal||"—")+'</td>'+
        '<td class="num">'+(a.runs30||0).toLocaleString()+'</td></tr>';}).join("")+'</tbody></table></div>'
    :'<div class="panel-b dim">This host is enrolled and no agent is assigned to it. It records nothing until one runs here.</div>')+
   '<div class="panel-b"><div class="note">Every agent here is seen through the same hooks and earns the same tier. An agent’s identity, its steering and its toolbelt are its own; only the seam is shared.</div></div></div>'+
   '<div class="panel"><div class="panel-h"><h3>Rollback</h3></div><div class="panel-b">'+
   '<pre>oxagen agent unenroll --host '+h(rt.id)+' \\\n  --restore-settings</pre>'+
   '<div class="note" style="margin-top:12px">If hooks are stripped by hand instead, the next run records <span class="mono">hooks_removed</span> and the tier falls to <span class="mono">observe</span>. It is never upgraded after the fact.</div>'+
   '<div class="row" style="margin-top:14px">'+
   '<button class="btn" onclick="act(\'Smoke session queued on '+h(rt.name)+'. One turn, recorded like any other run.\')">Run a smoke session</button>'+
   '<button class="btn danger" onclick="openDialog(\'unenroll\',\''+h(rt.id)+'\')">Unenroll</button></div>'+
   '</div></div></div>';
}

/* ============================== Repositories ==============================
   Where the workspace's files live and how they change. Four tabs, one argument:
   .oxagen/ is the workspace's source of truth, it lives in git, and every change to it
   arrives as a pull request. Repositories is the binding, Working copies is the same
   directory on somebody's disk, Changes is every pull request Oxagen has open across
   all five kinds of file, and Configuration is the file itself beside what the control
   plane actually has. Nothing on this page writes a row and nothing here merges. */

var OXPR_KIND={
 bootstrap:{l:"oxagen init", d:"the .oxagen/ tree itself",        i:"repo"},
 record:   {l:"context record", d:".oxagen/rules/<lineage>.toml", i:"steering"},
 skill:    {l:"skill",       d:".oxagen/skills/<name>/SKILL.md",  i:"skills"},
 agent:    {l:"agent",       d:".oxagen/agents/<slug>.toml",      i:"agents"},
 tool:     {l:"tool",        d:".oxagen/tools/<name>.toml",       i:"tools"},
 config:   {l:"configuration", d:".oxagen/workspace.toml",        i:"org"}
};
var OX_STATE={
 governed:{b:"b-allowed", l:"governed"},
 unbound: {b:"b-q",       l:"no .oxagen/"},
 drift:   {b:"b-approval",l:"drift"}
};
var WC_STATE={
 "in-sync":     {b:"b-allowed",  l:"in sync"},
 behind:        {b:"b-approval", l:"behind"},
 uncommitted:   {b:"b-approval", l:"uncommitted"},
 unbound:       {b:"b-q",        l:"unbound"}
};
var PR_STATE={
 open:           {b:"b-q",        l:"open"},
 closed:         {b:"b-q",        l:"closed"},
 checks_running: {b:"b-approval", l:"checks running"},
 checks_passed:  {b:"b-allowed",  l:"checks passed"},
 checks_failed:  {b:"b-failed",   l:"checks failed"},
 merged:         {b:"b-proven",   l:"merged"}
};
/* The seed repositories carry a language, a visibility and a push time; the ones the volume
   generator grows around them do not, and three separators around nothing reads as a bug. */
function repoMeta(r){
  return [r.lang,r.visibility,r.pushed?"pushed "+r.pushed:null].filter(function(x){return x;}).join(" · ");
}
/* Drift per workspace, and the reconciliation pull request each one's drift produced. Keyed by
   slug rather than held as one list, because drift is a fact about one workspace's file against
   its own live state and belongs to nobody else. */
var DRIFT={
 "core-platform":[["[providers.linear]","absent","present since 2026-09-14","the file"],
                  ["budget.monthly_usd","400","600","the file"],
                  ["[[repos]] a-intel/mobile","role = linked","linked, no .oxagen/","neither"]]
};
var DRIFT_PR={"core-platform":"oxpr_01K6T4E5"};
function oxState(r){return OX_STATE[r.ox||"governed"]||OX_STATE.governed;}
/* The repositories this workspace's own record names, main first, then linked, then whatever
   the installation can reach that nobody has bound. Role is the workspace's word, not GitHub's. */
/* A workspace names its main repo in ws.json; REPOS may hold no row for it, because the seed
   fixtures only carry core-platform's and the volume generator grows rows for the workspaces it
   invents rather than the ones already there. Three separate findings on this page were the same
   omission read three ways — a Repositories tab claiming zero bound repositories, a Configuration
   panel labelled with one repository and rendering another's head, and a main repo absent from
   every list that derives from this one. So the record is minted here, once, rather than at each
   call site: a workspace's main repo always exists, whether or not anybody has indexed it. */
function repoRecordFor(name,w){
  return {n:name,role:"main",branch:w.branch,head:w.head||null,indexed:"\u2014",
    issues:"enabled",events:"\u2014",symbols:0,drift:"\u2014",
    ox:"governed",oxCommit:w.head||null,oxFiles:0,lang:"",visibility:"private",pushed:""};
}
function wsRepos(){
  var w=ws(), order={main:0,linked:1,available:2};
  var rows=REPOS.filter(function(r){return r.n===w.main||(w.linked||[]).indexOf(r.n)>=0||r.role==="available";})
   .map(function(r){return r.n===w.main?Object.assign({},r,{role:"main"}):r;});
  if(!rows.some(function(r){return r.n===w.main;})) rows.push(repoRecordFor(w.main,w));
  return rows.sort(function(a,b){return (order[a.role]==null?3:order[a.role])-(order[b.role]==null?3:order[b.role]);});
}
function wsCopies(){var names={};wsRepos().forEach(function(r){names[r.n]=1;});
  return WORKCOPIES.filter(function(c){return names[c.repo];});}
function wsOxprs(){var names={};wsRepos().forEach(function(r){names[r.n]=1;});
  return OXPRS.filter(function(p){return names[p.repo];});}
function oxprOpen(){return wsOxprs().filter(function(p){return p.state!=="merged"&&p.state!=="closed";});}
function oxprById(id){for(var i=0;i<OXPRS.length;i++){if(OXPRS[i].id===id)return OXPRS[i];}return null;}
function copyById(id){for(var i=0;i<WORKCOPIES.length;i++){if(WORKCOPIES[i].id===id)return WORKCOPIES[i];}return null;}
function repoByName(n){for(var i=0;i<REPOS.length;i++){if(REPOS[i].n===n)return REPOS[i];}return null;}
/* A row that only answers a click is a row a keyboard cannot reach, and this page's own rules
   say it must be operable end to end. The engine's older tables use a bare `class="click"`; these
   three do not, and the helper is here rather than inline so they cannot drift apart. */
function rowClick(on,label){
  return 'class="click" tabindex="0" role="button" aria-label="'+h(label)+'"'+
   ' onclick="'+on+'" onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault();'+on+'}"';
}
function stBadge(m){return '<span class="b '+m.b+'"><span class="d"></span>'+h(m.l)+'</span>';}

/* The file the init pull request carries. It is written out here rather than interpolated into a
   string elsewhere, because the review step shows this exact text and the operator edits it. */
/* `role` is the operator's choice on step 1, not a fact about the workspace as it stands. The
   file used to derive it from `w.main`, so a repository chosen as the new main was drafted as
   `linked` — the one line the review step exists to let somebody read, contradicting the choice
   two steps earlier, and leaving an empty workspace unable to draft the main binding it needs. */
function oxWorkspaceToml(w,repo,mode,role){
  return '# .oxagen/workspace.toml — committed, reviewed, and the source of truth.\n'+
   '# The local link (org, workspace, machine) is .oxagen/workspace.json, which is gitignored.\n'+
   'schema = "oxagen-workspace/v0.1"\n'+
   'org = "'+ORG.slug+'"\n'+
   'workspace = "'+w.slug+'"\n\n'+
   '[[repos]]\n'+
   'name = "'+repo.n+'"\n'+
   'role = "'+(role||(repo.n===w.main?"main":"linked"))+'"\n'+
   'production_branch = "'+repo.branch+'"\n'+
   'issues = '+(String(repo.issues).indexOf("enabled")===0?"true":"false")+'\n\n'+
   '[providers]\n'+
   'github = { transport = "mcp", downscope = "installation token" }\n'+
   'linear = { transport = "mcp", downscope = "token exchange" }\n\n'+
   '[budget]\n'+
   'monthly_usd = 600\n'+
   'per_run_usd = 2.40\n';
}
function oxGovernanceToml(mode){
  return '# .oxagen/rules/governance.toml — read on the production branch when a pull request is\n'+
   '# opened and again when it is merged. A missing file means team.\n'+
   'mode = "'+mode+'"\n'+
   'separation_of_duties = '+(mode==="regulated"?"true":"false")+'\n';
}

/* ---- tab 1: the repositories ---- */
function repoTab(){
  var w=ws(), rows=wsRepos();
  var unbound=rows.filter(function(r){return (r.ox||"governed")==="unbound"&&r.role!=="available";});
  var banner=unbound.length?'<div class="banner"><span class="b b-approval" style="flex:none"><span class="d"></span>'+
   unbound.length+' linked repositor'+(unbound.length>1?'ies carry':'y carries')+' no .oxagen/</span>'+
   '<div class="grow"><b>A run on '+h(unbound.map(function(r){return r.n;}).join(", "))+' is steered by the main repo and by nothing of its own.</b> '+
   'Repository-scoped records live in that repository, so until it has a <span class="mono">.oxagen/</span> tree there is nowhere to put one — '+
   'and a record that tried would have to claim workspace scope, which the checks refuse.</div>'+
   '<button class="btn" onclick="wzOpen(\'init\',\''+h(unbound[0].n)+'\')">Add .oxagen/</button></div>':'';

  var trows=rows.map(function(r){
    var st=oxState(r), avail=r.role==="available";
    return '<tr '+rowClick("openDialog('repo','"+h(r.n)+"')","Open "+r.n)+'>'+
     '<td><span class="row-ic">'+icon("repo")+'</span><b class="mono">'+h(r.n)+'</b>'+
       (repoMeta(r)?'<div class="dim" style="font-size:11px;margin-top:2px">'+h(repoMeta(r))+'</div>':'')+'</td>'+
     '<td>'+(r.role==="main"?'<span class="b b-proven">main</span>':r.role==="linked"?'<span class="b b-q">linked</span>':'<span class="b b-q" style="opacity:.7">not linked</span>')+'</td>'+
     '<td><span class="mono">'+h(r.branch)+'</span><div class="dim mono" style="font-size:11px">'+h(r.head)+'</div></td>'+
     '<td>'+stBadge(st)+(r.oxFiles?'<div class="dim mono" style="font-size:11px;margin-top:2px">'+plural(r.oxFiles,"file")+'</div>':'')+'</td>'+
     '<td class="muted" style="font-size:12px">'+h(avail?"—":r.events)+'</td>'+
     '<td class="num">'+(avail?'<span class="dim">—</span>':r.symbols.toLocaleString())+'</td>'+
     '<td>'+(st===OX_STATE.governed
        ?'<span class="dim" style="font-size:11.5px">nothing waiting</span>'
        :'<button class="btn sm" onclick="event.stopPropagation();wzOpen(\'init\',\''+h(r.n)+'\')">Add .oxagen/</button>')+'</td></tr>';}).join("");

  return banner+
   '<div class="panel"><div class="panel-h"><div style="flex:1;min-width:0"><h3>Repositories</h3>'+
   '<p class="muted" style="margin:2px 0 0;font-size:12px">One main repo, any number of linked. The main repo holds the workspace’s steering and configuration; a linked repo may hold records that steer only runs on it.</p></div>'+
   '<div class="sp"><button class="btn sm" onclick="wzOpen(\'init\')">Add .oxagen/</button></div></div>'+
   '<div class="tw"><table><thead><tr><th>Repository</th><th>Role</th><th>Production branch</th><th>.oxagen/</th><th>Events</th><th class="num">Symbols</th><th></th></tr></thead>'+
   '<tbody>'+trows+'</tbody></table></div>'+
   '<div class="panel-b" style="border-top:1px solid var(--border)"><div class="note">Changing which repository is <span class="mono">main</span> is an organization-owner action with approval, and it lands in the audit record as a security event. The production branch never moves on its own: when GitHub’s default branch changes, the App records it and prompts, and the binding stays where it is until somebody confirms.</div></div></div>';
}

/* ---- tab 2: the working copies ---- */
function copyTab(){
  var w=ws(), rows=wsCopies();
  /* The header gives up its gold on this tab, so an empty list that omitted Connect would leave
     the screen with no primary action and no way to link its first directory — which is the one
     thing this tab exists to do. */
  if(!rows.length) return '<div class="panel"><div class="panel-h"><div style="flex:1;min-width:0"><h3>Working copies</h3>'+
   '<p class="muted" style="margin:2px 0 0;font-size:12px">No directory on anybody’s disk is linked to '+h(w.name)+' yet.</p></div>'+
   '<div class="sp"><button class="btn primary" onclick="openDialog(\'linkdir\')">Connect a directory</button></div></div>'+
   '<div class="panel-b"><div class="note">A directory is linked by running <span class="mono">oxagen init</span> in it. Nothing here is linked by a person typing a path: the browser cannot see a filesystem, and a path typed into a form proves nothing about what is at it.</div></div></div>';
  var stale=rows.filter(function(c){return c.oxagen!=="in-sync";});
  var trows=rows.map(function(c){
    var st=WC_STATE[c.oxagen]||WC_STATE.unbound;
    return '<tr '+rowClick("openDialog('workcopy','"+h(c.id)+"')","Open "+c.path+" on "+c.machine)+'>'+
     '<td><span class="row-ic">'+icon("dir")+'</span><b class="mono">'+h(c.path)+'</b>'+
       '<div class="dim" style="font-size:11px;margin-top:2px">'+h(c.machine)+' · '+h(c.person)+'</div></td>'+
     '<td class="mono" style="font-size:12px">'+h(c.repo)+'</td>'+
     '<td><span class="mono">'+h(c.branch)+'</span><div class="dim mono" style="font-size:11px">'+h(c.head)+'</div></td>'+
     '<td>'+stBadge(st)+(c.dirty?'<div class="dim" style="font-size:11px;margin-top:2px">'+c.dirty+' uncommitted</div>':'')+'</td>'+
     '<td>'+(c.symlinks==="ok"?'<span class="b b-allowed"><span class="d"></span>ok</span>':'<span class="b b-approval"><span class="d"></span>missing</span>')+'</td>'+
     '<td class="mono" style="font-size:11.5px">'+h(c.bundle)+'</td>'+
     '<td class="muted" style="font-size:12px">'+h(c.seen)+'</td></tr>';}).join("");

  /* The banner that used to sit here said in a paragraph what the .oxagen/ column says in a
     word, on the row of the copy it is true of. The count is already on the tab. */
  return '<div class="panel"><div class="panel-h"><div style="flex:1;min-width:0"><h3>Working copies</h3>'+
   '<p class="muted" style="margin:2px 0 0;font-size:12px">The same <span class="mono">.oxagen/</span> tree on a machine. Each is a directory somebody ran <span class="mono">oxagen init</span> in; the enrollment is the machine’s, and the link is one gitignored file.</p></div>'+
   '<div class="sp"><button class="btn primary" onclick="openDialog(\'linkdir\')">Connect a directory</button></div></div>'+
   '<div class="tw"><table><thead><tr><th>Directory</th><th>Repository</th><th>Branch</th><th>.oxagen/</th><th>Symlinks</th><th>Bundle</th><th>Last seen</th></tr></thead>'+
   '<tbody>'+trows+'</tbody></table></div></div>'+
   '<div class="grid g2" style="margin-top:14px">'+
   '<div class="panel"><div class="panel-h"><h3>Files to review</h3></div><div class="panel-b">'+
   '<pre>.oxagen/\n  workspace.toml     <span class="c"># committed. reviewed. the source of truth.</span>\n'+
   '  workspace.json     <span class="c"># gitignored · this machine’s link</span>\n'+
   '  rules/\n  proposals/\n  agents/\n  skills/\n  tools/</pre>'+
   '<div class="note" style="margin-top:12px">The committed file says what the workspace is. The gitignored one says which workspace <em>this checkout</em> is talking to, which is a fact about a laptop and not about the product — so it is never reviewed, never merged, and never the same file in two places.</div></div></div>'+
   '<div class="panel"><div class="panel-h"><h3>Sync</h3></div><div class="panel-b">'+
   '<div class="kv"><dt><span class="mono">oxagen init</span></dt><dd>Links this directory. Reads the git remote, matches it to a repository the installation can reach, and writes <span class="mono">.oxagen/workspace.json</span>. Idempotent.</dd>'+
   '<dt><span class="mono">oxagen pull</span></dt><dd>Fast-forwards <span class="mono">.oxagen/</span> to the production branch and re-points the stella symlinks. It never merges your work.</dd>'+
   '<dt><span class="mono">oxagen status</span></dt><dd>What this copy has against what is published: the bundle version, the records in force, and anything uncommitted under <span class="mono">.oxagen/</span>.</dd>'+
   '<dt><span class="mono">oxagen propose</span></dt><dd>Turns a local edit under <span class="mono">.oxagen/</span> into a proposal. Opening and merging its pull request happen here, because both gate on a role only a signed-in person holds.</dd></div>'+
   '<div class="note" style="margin-top:12px">stella symlinks into this directory rather than copying it, so there is no second copy that could drift. A copy whose symlinks read <span class="mono">missing</span> is one where stella will load nothing.</div></div></div></div>';
}

/* ---- tab 3: the changes ---- */
/* S.oxprSel outlives a workspace switch and OXPRS is global, so the raw id means nothing on its
   own. Every read of the selection goes through here: chgTab, which would otherwise render one
   workspace's change under another's name, and the header, which would otherwise give up its gold
   for a detail view that is not on screen. Two findings, one unvalidated value. */
function selectedOxpr(){
  if(!S.oxprSel) return null;
  return wsOxprs().filter(function(p){return p.id===S.oxprSel;})[0]||null;
}
function chgTab(){
  var rows=wsOxprs(), sel=selectedOxpr();
  if(sel) return oxprDetail(sel);
  var trows=rows.map(function(p){
    var k=OXPR_KIND[p.kind]||OXPR_KIND.config, st=PR_STATE[p.state]||PR_STATE.open;
    var pass=p.checks.filter(function(c){return c[1]==="pass";}).length;
    return '<tr '+rowClick("S.oxprSel='"+h(p.id)+"';render()","Open "+p.title)+'>'+
     '<td><span class="row-ic">'+icon(k.i)+'</span><b>'+h(p.title)+'</b>'+
       '<div class="dim mono" style="font-size:11px;margin-top:2px">'+h(p.branch)+'</div></td>'+
     '<td><span class="b b-q">'+h(k.l)+'</span></td>'+
     '<td class="mono" style="font-size:12px">'+h(p.pr)+'</td>'+
     '<td>'+(p.byKind==="person"?h(p.by):'<span class="mono">'+h(p.by)+'</span>')+
       '<div class="dim" style="font-size:11px">'+h(p.byKind==="person"?"a person":p.byKind)+'</div></td>'+
     '<td>'+stBadge(st)+'</td>'+
     '<td>'+oxprCiLight(p)+'</td>'+
     '<td class="muted" style="font-size:12px">'+h(p.opened)+'</td></tr>';}).join("");
  return '<div class="panel"><div class="panel-h"><div style="flex:1;min-width:0"><h3>Open Context PRs</h3>'+
   '<p class="muted" style="margin:2px 0 0;font-size:12px">Four kinds of file and one lifecycle. Whoever opened it — a person, the promoter, or the reconciler — the checks, the merge and the publication are the same.</p></div></div>'+
   '<div class="tw"><table><thead><tr><th>Change</th><th>Kind</th><th>Pull request</th><th>Opened by</th><th>State</th><th>Checks</th><th>Opened</th></tr></thead>'+
   '<tbody>'+trows+'</tbody></table></div>'+
   '<div class="panel-b" style="border-top:1px solid var(--border)"><div class="note">A change is in force from the merge commit, not from when it was written. While a pull request is open the thing it carries steers nothing: it is not in the compiled bundle, not in the record index, and the bundle version has not moved.</div></div></div>'+
   '<div class="panel" style="margin-top:14px"><div class="panel-h"><h3>Automatic proposals</h3></div><div class="panel-b">'+
   '<div class="kv"><dt>the promoter</dt><dd>Aggregates records across runs by lineage and opens a proposal with the runs it cites. There is no threshold; a person reads the support and decides.</dd>'+
   '<dt>the reconciler</dt><dd>Reads <span class="mono">.oxagen/workspace.toml</span> against what the control plane has, and opens one pull request per real difference. It never edits live state to match the file.</dd>'+
   '<dt>a person</dt><dd>Every creation wizard — agent, tool, skill, record — ends here. None of them has a Save button that ends in a database.</dd></div>'+
   '<div class="note" style="margin-top:12px">Drift is reported, never repaired in place. A reconciler that silently edited either side would make the file a description of the past and the product unreviewable — the pull request is the only place a person can say which of the two was right.</div></div></div>';
}

/* Merge is enabled only when every check has reported, none failed, and the pull request is not
   already merged. The detail view computed this inline while the page header separately assumed
   that *any* selected change supplied a gold action — so selecting a running, failed or merged
   one demoted the header for a primary that was never rendered, and the screen had none. Same
   shape as the stale-selection bug: two readers of one fact, only one of them right. */
/* CI status as GitHub reports it, one light: blinking blue while anything runs, a red x the moment
   one job fails (pulsing while others still run), static green when every job passed, static grey
   while everything is queued. Beside it, jobs done over jobs in total. */
function ciCounts(list){
  var c={pass:0,fail:0,running:0,queued:0,total:list.length};
  list.forEach(function(x){c[x]=(c[x]||0)+1;});
  c.done=c.pass+c.fail; return c;
}
function ciFromSt(def,st){
  var n=def.checks.length, list=[];
  for(var i=0;i<n;i++){list.push(st.st==="merged"||st.st==="passed"?"pass":st.st==="failed"?(i<st.done?"pass":i===st.failed?"fail":"queued"):st.st==="checking"?(i<st.done?"pass":i===st.done?"running":"queued"):"queued");}
  return ciCounts(list);
}
function ciLight(c,label){
  var mode=c.fail?(c.running?"fail pulse":"fail"):c.running?"run":c.done===c.total&&c.total?"pass":"queued";
  var title=c.fail?c.fail+" failed":c.running?"running":mode==="pass"?"all passed":"queued";
  return '<span class="ci" title="'+title+'"><span class="ci-l '+mode+'" aria-label="'+title+'"></span>'+
   '<span class="mono">'+c.done+' / '+c.total+'</span>'+(label?'<span class="dim">'+h(label)+'</span>':'')+'</span>';
}
function oxprCiLight(p){return ciLight(ciCounts(p.checks.map(function(c){return c[1];})));}
function oxprUrl(p){return "https://app.oxagen.sh/"+ORG.slug+"/"+ws().slug+"/repositories/changes/"+p.id;}
function oxprMerge(id){
  var p=oxprById(id); if(!p||!oxprCanMerge(p)) return;
  p.state="merged"; p.checks.forEach(function(c){if(c[1]!=="pass")c[1]="pass";});
  render(); act("Merged "+p.pr+". Squashed onto "+p.base+", head branch deleted, bundle bumped, promotion event and audit event written.","gold");
}
/* Close: the comment Oxagen leaves on the pull request, previewed before it is posted. */
function closeComment(url){
  var m=me(); return "Closed by "+m.name+" <"+m.email+">\n\n---\nAdded via oxagen "+url;
}
function prClose(kind,id){
  var url, pr;
  if(kind==="oxpr"){var p=oxprById(id); if(!p) return; p.state="closed"; pr=p.pr; url=oxprUrl(p);}
  else if(kind==="ctxpr"){S.ctxpr.st="closed"; pr=CTXPR.pr; url="https://app.oxagen.sh/"+ORG.slug+"/"+ws().slug+"/steering/proposals/prs";}
  else {var d=recprById(id); if(!d) return; recprSt(d).st="closed"; pr=d.pr; url="https://app.oxagen.sh/"+ORG.slug+"/"+ws().slug+"/steering/proposals/prs";}
  closeDialog(); render();
  act("Closed "+pr+" without merging. Comment posted: “Closed by "+me().name+" <"+me().email+">”, then Added via oxagen "+url+".");
}
DLG_EXT.closepr=function(arg){
  var a=String(arg||"").split("|"), kind=a[0], id=a[1], pr, url;
  if(kind==="oxpr"){var p=oxprById(id); pr=p?p.pr:id; url=p?oxprUrl(p):"";}
  else if(kind==="ctxpr"){pr=CTXPR.pr; url="https://app.oxagen.sh/"+ORG.slug+"/"+ws().slug+"/steering/proposals/prs";}
  else {var d=recprById(id); pr=d?d.pr:id; url="https://app.oxagen.sh/"+ORG.slug+"/"+ws().slug+"/steering/proposals/prs";}
  var m=me();
  return {t:"Close "+pr,s:"without merging",w:false,
   b:'<p style="margin:0 0 10px;font-size:13px">The pull request closes on GitHub and nothing is published. oxagen posts this comment on it:</p>'+
    '<div class="gh-comment"><p>Closed by '+h(m.name)+' &lt;'+h(m.email)+'&gt;</p><hr><p>Added via oxagen <a href="'+h(url)+'">'+h(url)+'</a></p></div>'+
    '<div class="note" style="margin-top:12px">Closing is a governed action: it is recorded in Audit with your name, and the branch stays until someone deletes it.</div>',
   f:'<button class="btn" onclick="closeDialog()">Cancel</button><button class="btn danger solid" onclick="prClose(\''+h(kind)+'\',\''+h(id)+'\')">Close pull request</button>'};
};
function oxprCanMerge(p){
  return !!p&&p.state!=="merged"
    &&p.checks.every(function(c){return c[1]==="pass"||c[1]==="fail";})
    &&!p.checks.some(function(c){return c[1]==="fail";});
}
function oxprDetail(p){
  var k=OXPR_KIND[p.kind]||OXPR_KIND.config, st=PR_STATE[p.state]||PR_STATE.open;
  var failed=p.checks.filter(function(c){return c[1]==="fail";});
  var canMerge=oxprCanMerge(p);
  return '<div class="panel"><div class="panel-h">'+
   '<button class="btn sm" onclick="S.oxprSel=null;render()">← All changes</button>'+
   '<h3 style="margin-left:10px">'+h(p.title)+'</h3><span class="sp">'+oxprCiLight(p)+stBadge(st)+'</span></div>'+
   '<div class="panel-b">'+
   '<div class="kv"><dt>Kind</dt><dd><span class="b b-q">'+h(k.l)+'</span> <span class="mono dim">'+h(k.d)+'</span></dd>'+
   '<dt>Pull request</dt><dd><span class="mono">'+h(p.pr)+'</span></dd>'+
   '<dt>Branch</dt><dd><span class="mono">'+h(p.branch)+'</span> → <span class="mono">'+h(p.base)+'</span></dd>'+
   '<dt>Opened by</dt><dd>'+h(p.by)+' · <span class="dim">'+h(p.opened)+'</span></dd>'+
   '<dt>Why</dt><dd>'+h(p.trigger)+'</dd></div></div>'+
   '<div class="panel-b" style="border-top:1px solid var(--border)"><label class="sec-lb">Files this pull request carries</label>'+
   wzFiles(p.files)+'</div>'+
   '<div class="panel-b" style="border-top:1px solid var(--border)"><label class="sec-lb">Checks</label>'+
   '<div class="tw"><table class="narrow"><thead><tr><th>Check</th><th>Result</th><th>What it asserted</th></tr></thead><tbody>'+
   p.checks.map(function(c){
     var badge=c[1]==="pass"?'<span class="b b-allowed"><span class="d"></span>pass</span>'
      :c[1]==="fail"?'<span class="b b-failed"><span class="d"></span>fail</span>'
      :c[1]==="running"?'<span class="b b-approval"><span class="d"></span>running</span>'
      :'<span class="b b-q">queued</span>';
     return '<tr><td class="mono" style="font-size:11.5px">'+h(c[0])+'</td><td>'+badge+'</td>'+
      '<td class="muted" style="font-size:12px">'+h(c[2])+'</td></tr>';}).join("")+
   '</tbody></table></div>'+
   (failed.length?'<div class="note" style="margin-top:12px;border-left-color:var(--st-failed)"><b>'+h(failed[0][0])+' stopped the run.</b> '+
     h(failed[0][2])+' The checks behind it stayed queued, merge is disabled, and nothing was published.</div>':'')+
   '</div>'+
   '<div class="panel-b" style="border-top:1px solid var(--border)">'+
   (p.state==="merged"
     ?'<div class="note">Merged. The file is on <span class="mono">'+h(p.base)+'</span>, the promotion event is on the ledger, and the workspace’s steering version is the ledger’s length.</div>'
     :p.state==="closed"
     ?'<div class="note">Closed without merging. The comment on '+h(p.pr)+' names who closed it and links back here.</div>'
     :'<label class="sec-lb">What merge will do</label>'+wzChecks([
       ["1",'Squash the branch onto <span class="mono">'+h(p.base)+'</span>, pinned to the commit the checks ran on.'],
       ["2",'Delete the head branch.'],
       ["3",'Re-index from the merged commit and bump the workspace bundle version.'],
       ["4",'Append the promotion event to the ledger, with the approver and the commit sha.'],
       ["5",'Write one audit event. The change is in force from that commit, not from now.']])+
      '<div class="row" style="margin-top:14px;gap:8px">'+
      '<button class="btn'+(canMerge?' primary':'')+'"'+(canMerge?'':' disabled')+' onclick="oxprMerge(\''+h(p.id)+'\')">Merge pull request</button>'+
      '<button class="btn danger" onclick="openDialog(\'closepr\',\'oxpr|'+h(p.id)+'\')">Close pull request</button>'+
      '<span class="grow"></span><span class="dim" style="font-size:11.5px">'+
      (canMerge?'Governance: '+h(wsGov(ws()))+' on GitHub':'Merge stays disabled until every check reports.')+'</span></div>')+
   '</div></div>';
}

/* ---- tab 4: the configuration ---- */
function cfgTab(){
  var w=ws();
  /* Never wsRepos()[0]: that list also holds repositories the installation can reach but nobody
     has bound, so its first row can be an unrelated repository wearing this workspace's name. */
  var repo=repoByName(w.main)||repoRecordFor(w.main,w);
  /* Drift is a fact about one workspace's file against one workspace's live state. These rows are
     core-platform's — its Linear server, its budget, its unbound linked repo — so rendering them
     under another workspace would report drift that workspace does not have, and send the
     operator to a reconciliation pull request that is not its own. A workspace with nothing
     recorded says so. */
  var drift=DRIFT[w.slug]||[], reconcile=DRIFT_PR[w.slug]||null;
  return '<div class="grid g2">'+
   '<div class="panel"><div class="panel-h"><div style="flex:1;min-width:0"><h3>.oxagen/workspace.toml</h3>'+
   '<p class="muted" style="margin:2px 0 0;font-size:12px">On <span class="mono">'+h(w.main)+'</span>'+
   (repo.head?' at <span class="mono">'+h(repo.head)+'</span>':' \u00b7 <span class="dim">not indexed yet</span>')+'</p></div></div>'+
   '<div class="panel-b"><pre>'+h(oxWorkspaceToml(w,repo,"team","main"))+'</pre></div></div>'+
   '<div class="panel"><div class="panel-h"><div style="flex:1;min-width:0"><h3>Drift</h3>'+
   '<p class="muted" style="margin:2px 0 0;font-size:12px">The file against what the control plane has. Reported, never repaired in place.</p></div>'+
   (reconcile?'<div class="sp"><button class="btn sm" onclick="go(\'#/'+ORG.slug+'/'+h(w.slug)+'/repositories/changes\');S.oxprSel=\''+h(reconcile)+'\';render()">See the pull request</button></div>':'')+'</div>'+
   (drift.length
     ?'<div class="tw"><table class="narrow"><thead><tr><th>Declared</th><th>In the file</th><th>Live</th><th>Right</th></tr></thead><tbody>'+
      drift.map(function(d){return '<tr><td class="mono" style="font-size:11.5px">'+h(d[0])+'</td>'+
        '<td class="muted" style="font-size:12px">'+h(d[1])+'</td><td class="muted" style="font-size:12px">'+h(d[2])+'</td>'+
        '<td>'+(d[3]==="the file"?'<span class="b b-q">the file</span>':'<span class="b b-approval">a person decides</span>')+'</td></tr>';}).join("")+
      '</tbody></table></div>'+
      '<div class="panel-b" style="border-top:1px solid var(--border)"><div class="note">Two of these the reconciler can argue for, because it read both sides. The third it cannot: a repository with no <span class="mono">.oxagen/</span> is a decision about scope, not a difference between two records, so it waits for a person.</div></div>'
     :'<div class="panel-b"><div class="note">The reconciler last read <span class="mono">'+h(w.main)+'</span> against the control plane and found nothing between them. Drift is reported here, never repaired in place — so an empty table is the reconciler saying the file and the live state agree, not that nobody looked.</div></div>')+
   '</div></div>'+
   '<div class="grid g2" style="margin-top:14px">'+
   '<div class="panel"><div class="panel-h"><h3>.oxagen/rules/governance.toml</h3></div><div class="panel-b">'+
   '<pre>'+h(oxGovernanceToml("team"))+'</pre>'+
   '<div class="kv" style="margin-top:12px"><dt><span class="mono">solo</span></dt><dd>The author may merge their own.</dd>'+
   '<dt><span class="mono">team</span></dt><dd>A code-owner review is required. This is what a missing file means.</dd>'+
   '<dt><span class="mono">regulated</span></dt><dd>A named approver from a role must approve, and the promotion ledger is hash-chained.</dd></div>'+
   '<div class="note" style="margin-top:12px">The mode is read on the production branch when a pull request is opened and again when it is merged — so raising it takes effect on everything still open, and it is changed by a pull request like everything else, never by a settings screen. A file that exists but names no mode refuses both, rather than quietly falling back to <span class="mono">team</span>.</div></div></div>'+
   '<div class="panel"><div class="panel-h"><h3>Tree</h3></div><div class="panel-b">'+
   '<pre>.oxagen/\n  workspace.toml             <span class="c"># linked repos, providers, budgets</span>\n'+
   '  workspace.json             <span class="c"># gitignored · this machine’s link</span>\n'+
   '  rules/\n    governance.toml          <span class="c"># mode = team</span>\n'+
   '    promotions.jsonl         <span class="c"># hash-chained ledger (regulated)</span>\n'+
   '    ctx.&lt;set&gt;.&lt;slug&gt;.toml     <span class="c"># one published record per lineage</span>\n'+
   '  proposals/*.toml           <span class="c"># candidates; steer nothing</span>\n'+
   '  agents/&lt;slug&gt;.toml         <span class="c"># one per agent</span>\n'+
   '  skills/&lt;name&gt;/SKILL.md     <span class="c"># pinned by version and digest</span>\n'+
   '  tools/&lt;name&gt;.toml          <span class="c"># manifest, schema, handler beside it</span></pre>'+
   '<div class="note" style="margin-top:12px">oxagen reads <span class="mono">.oxagen/</span> and nothing else. Whatever sits under <span class="mono">.stella/</span> is invisible to it, and it never looks.</div></div></div></div>';
}

function pRepos(){
  var w=ws(), t=tab("repositories","repos");
  if(S.state==="loading") return skeleton();
  if(S.state==="error") return errorState("Repositories","503 installation_unreachable");
  if(S.state==="denied") return deniedState("this workspace’s repositories","repository.read on "+w.slug);
  if(S.state==="empty") return emptyState("This workspace has no repository yet",
    "A workspace without a main repo cannot exist, so this state is the moment between creating one and binding it. The main repo is where steering and configuration are managed in source control — until it is bound, there is nowhere for a record to be published to.",
    '<button class="btn primary" onclick="wzOpen(\'init\')">Add .oxagen/</button>');

  var open=oxprOpen().length, stale=wsCopies().filter(function(c){return c.oxagen!=="in-sync";}).length;
  var tabs='<div class="tabs" role="tablist">'+
   [["repos","Repositories",wsRepos().filter(function(r){return r.role!=="available";}).length],
    ["copies","Working copies",stale],
    ["changes","Changes",open],
    ["config","Configuration",0]]
   .map(function(x){return '<button class="tab" role="tab" aria-selected="'+(t===x[0])+'" onclick="S.tab.repositories=\''+x[0]+'\';S.oxprSel=null;render()">'+x[1]+(x[2]?'<span class="n">'+x[2]+'</span>':'')+'</button>';}).join("")+'</div>';

  var body=t==="copies"?copyTab():t==="changes"?chgTab():t==="config"?cfgTab():repoTab();
  /* the page header gives up the gold when the tab below holds the one primary action */
  /* Give up the header's gold only where the tab below actually renders an enabled one. */
  var tabPrimary=(t==="changes"&&oxprCanMerge(selectedOxpr()))||t==="copies";
  return '<div class="phead"><div class="t"><p class="eyebrow">'+h(w.name)+'</p><h1>Repositories</h1>'+
   '<p>Where this workspace’s files live and every change oxagen has proposed to them.</p></div>'+
   '<div class="acts"><button class="btn'+(tabPrimary?'':' primary')+'" onclick="wzOpen(\'init\')">Add .oxagen/</button></div></div>'+tabs+body;
}

/* ============================== Spend ============================== */
function pSpend(){
  var w=ws(), t=tab("spend","findings"), WT=wsTok(w.slug);
  if(S.state==="loading") return skeleton();
  if(S.state==="error") return errorState("Spend","504 rollup_rebuild_in_progress");
  if(S.state==="denied") return deniedState("this workspace’s spend","spend.read on core-platform");
  if(S.state==="empty") return emptyState("No spend to report yet",
    "Rollups are derived indexes rebuilt from frames. With no model call recorded there is nothing to roll up, and nothing billable.",
    '<button class="btn" onclick="go(\'#/'+ORG.slug+'/'+w.slug+'\')">Back to Fleet</button>');

  var tabs='<div class="tabs" role="tablist">'+
   [["findings","Findings",FINDINGS.length],["tokens","Tokens"],["coaching","Coaching",coachCount()],["operator","By operator"],["agent","By agent"],
    ["model","By model"],["tool","By tool"],["waste","Wasted spend",SPEND.wasteRunsList.length],["budgets","Budgets",SPEND.budgets.length]]
   .map(function(x){return '<button class="tab" role="tab" aria-selected="'+(t===x[0])+'" onclick="spendGo(\''+x[0]+'\')">'+x[1]+(x[2]?'<span class="n">'+x[2]+'</span>':'')+'</button>';}).join("")+'</div>';

  var strip='<div class="grid g4" style="margin-bottom:16px">'+
   '<div class="stat"><span class="k">Spend</span><span class="v">'+usd(fmt2(spendMonthTotal()))+'</span><span class="s">'+basisChip("gateway_observed")+' + '+basisChip("client_attested")+' · USD</span></div>'+
   '<div class="stat"><span class="k">Tokens</span><span class="v">'+tokn(WT.total)+'</span><span class="s">'+per(WT.cacheRate)+' served from cache</span></div>'+
   '<div class="stat"><span class="k">Observed by the gateway</span><span class="v">'+per(WT.observed)+'</span><span class="s">of tokens counted by the proxy</span></div>'+
   '<div class="stat"><span class="k">Wasted</span><span class="v" style="color:var(--st-critical)">'+usd(SPEND.wasteTotal)+'</span><span class="s">'+per(SPEND.wasteShare)+' of spend</span></div></div>';

  var body="", drill=S.spendDrill&&spendDrillOk(S.spendDrill)?S.spendDrill:null;
  if(drill){
    body=spendDrill(drill);
  } else if(t==="tokens"){
    body=spendTokens(WT);
  } else if(t==="coaching"){
    body=spendCoaching();
  } else if(t==="findings"){
    var total=FINDINGS.reduce(function(s,f){return s+parseFloat(f.save);},0);
    var spendN=spendMonthTotal();
    var top=Math.max.apply(null,FINDINGS.map(function(f){return parseFloat(f.save);}));
    var opsN={}; FINDINGS.forEach(function(f){var e=EVIDENCE[f.id]; if(e) opsN[e.who.operator]=1;});
    var conf=FINDINGS.reduce(function(a,f){var e=EVIDENCE[f.id]; if(e) a[e.confidence]=(a[e.confidence]||0)+1; return a;},{});
    var ramp=[1,.8,.64,.5,.38,.28];
    var shareStrip=FINDINGS.map(function(f,i){return '<i style="flex:'+parseFloat(f.save)+';opacity:'+ramp[i%ramp.length]+'" title="'+h(f.kind)+' · '+usd(f.save)+'"></i>';}).join("");
    /* The legend names the biggest few and rolls the rest into one entry; at forty findings
       a name per slice is unreadable and every tail slice rounds to 0%. */
    var LEG=8, lead=FINDINGS.slice(0,LEG), tail=FINDINGS.slice(LEG);
    var legend=lead.map(function(f,i){return '<span><i style="opacity:'+ramp[i%ramp.length]+'"></i>'+h(f.kind)+' <span class="mono">'+Math.round(parseFloat(f.save)/total*100)+'%</span></span>';}).join("")+
      (tail.length?'<span><i style="opacity:.22"></i>'+tail.length+' smaller findings <span class="mono">'+Math.round(tail.reduce(function(s,f){return s+parseFloat(f.save);},0)/total*100)+'%</span></span>':'');
    body='<div class="sv-hero">'+
     '<div><p class="eyebrow">Savings identified</p><div class="sv-amt">'+fmt$(total)+'</div>'+
     '<div class="sv-sub">'+(total/spendN*100).toFixed(1)+'% of '+usd(fmt2(spendMonthTotal()))+' spent this month · about '+usd(Math.round(total*12).toLocaleString())+' a year at this run rate</div></div>'+
     '<div><div class="sv-strip" role="img" aria-label="Share of identified savings by finding">'+shareStrip+'</div><div class="sv-legend">'+legend+'</div>'+
     '<div class="sv-facts"><span><b>'+FINDINGS.length+'</b> findings</span><span><b>'+Object.keys(opsN).length+'</b> operators involved</span>'+
     '<span><b>'+(conf.high||0)+'</b> high confidence · <b>'+(conf.medium||0)+'</b> medium</span><span>every one opens to its evidence</span></div></div></div>'+
     '<div class="grid" style="gap:10px">'+
     FINDINGS.map(function(f,i){return fndCard(f,i,total,top);}).join("")+
     '</div><div class="note" style="margin-top:14px">Each saving is measured minus counterfactual over the runs it cites, at the price each call actually paid. Nothing here is an opinion: Evidence opens the runs, the people and the arithmetic behind every number, and Fix opens the change that removes it.</div>';
  } else if(t==="operator"){
    body='<div class="panel"><div class="panel-h"><h3>By operator</h3></div><div class="tw"><table>'+
     '<thead><tr><th>Operator</th><th>Role</th><th class="num">Agents</th><th class="num">Runs</th><th class="num">Spend</th><th class="num">Tokens</th><th class="num">Cache hit</th><th class="num">Potential savings</th><th>Budget position</th></tr></thead><tbody>'+
     SPEND.byOperator.map(function(o){var p=PEOPLE[o.p];
      return '<tr'+drillRow("operator",o.p)+'><td><b>'+drillName("operator",o.p)+'</b></td><td class="mono dim" style="font-size:11.5px">'+h(p.role)+'</td>'+
       '<td class="num">'+o.agents+'</td><td class="num">'+o.runs.toLocaleString()+'</td>'+
       '<td class="num">'+usd(o.spend)+'</td><td class="num">'+tokn(operatorTok(o.p).total)+'</td><td class="num">'+per(operatorTok(o.p).cacheRate)+'</td>'+savingsCell("operator",o.p)+
       '<td style="min-width:170px"><div class="bar"><i style="width:'+Math.round(o.used*100)+'%;background:'+(o.used>0.8?"var(--st-critical)":"var(--st-allowed)")+'"></i></div>'+
       '<div class="dim" style="font-size:11px">'+per(o.used)+' of '+usd(o.budget)+'</div></td></tr>';}).join("")+
     '</tbody></table></div><div class="panel-b">'+
     '<div class="note">Every run has exactly one operator, even when a schedule or a webhook started it: the operator is the person who owns that trigger. A run that arrived without one is attributed to the agent’s owning operator and flagged — never dropped, never spread.</div></div></div>';
  } else if(t==="agent"){
    body='<div class="panel"><div class="panel-h"><h3>By agent</h3></div><div class="tw"><table>'+
     '<thead><tr><th>Agent</th><th class="num">Runs</th><th class="num">Spend</th><th class="num">Tokens</th><th class="num">Per run</th><th class="num">Cache hit</th><th class="num">Potential savings</th><th>Trend</th></tr></thead><tbody>'+
     SPEND.byAgent.map(function(a){
      return '<tr'+drillRow("agent",a.k)+'><td>'+agentCard(a.k,{key:a.k})+'</td><td class="num">'+a.runs.toLocaleString()+'</td>'+
       '<td class="num">'+usd(a.spend)+'</td><td class="num">'+tokn(agentTok(a.k).total)+'</td>'+
       '<td class="num">'+tokn(agentTok(a.k).perRun)+'</td><td class="num">'+per(agentTok(a.k).cacheRate)+'</td>'+savingsCell("agent",a.k)+
       '<td><span class="b b-'+(a.trend.charAt(0)==="-"?"allowed":"approval")+'">'+h(a.trend)+'</span></td></tr>';}).join("")+
     '</tbody></table></div><div class="panel-b"><div class="note">Every figure is a rollup of the agent\u2019s runs, rebuilt from frames. An agent on the harness tier is self-reported: its harness told oxagen the counts, and a class the harness does not report is marked absent, never zero.</div></div></div>';
  } else if(t==="model"){
    /* Consumption by model belongs on Spend; the routes themselves are configured under
       Organization → Model funding and routes, which this panel links to. */
    body='<div class="panel"><div class="panel-h"><div style="flex:1;min-width:0"><h3>Models and keys</h3>'+
     '<p class="muted" style="margin:2px 0 0;font-size:12px">Every model the workspace called this month, and the provider key it was billed to.</p></div>'+
     '<div class="sp"><button class="btn sm" onclick="go(\'#/'+ORG.slug+'\')">Model routes</button></div></div><div class="tw"><table>'+
     '<thead><tr><th>Model</th><th>Provider key</th><th class="num">Model calls</th><th class="num">Spend</th><th class="num">Cache hit rate</th><th>Basis</th></tr></thead><tbody>'+
     spendModelRows().map(function(m){var k=spendKeyOf(m.m,m.tier);
      return '<tr'+(m.route?' data-route="'+h(m.tier)+'"':'')+'><td class="tkey" style="font-size:12px">'+h(m.m)+(m.route?'<div class="dim" style="font-size:11px">oxagen’s own work · '+h(m.provider)+'</div>':'')+'</td><td style="font-size:12px">'+(k?'<span class="mono">'+h(k.id)+'</span><div class="dim" style="font-size:11px">'+h(k.src.split(" · ")[0])+'</div>':'<span class="dim">—</span>')+'</td><td class="num">'+(m.route?orgUseCount(m):m.calls.toLocaleString())+'</td>'+
       '<td class="num">'+usd(m.spend)+'</td><td class="num">'+(m.cache==null?'<span class="dim">—</span>':per(m.cache))+'</td>'+
       '<td class="dim" style="font-size:11px">'+basisChip("client_attested")+'</td></tr>';}).join("")+
     '<tr><td colspan="3"><b>Total</b> <span class="dim" style="font-size:11.5px">· the month’s spend</span></td><td class="num" id="spendModelTotal"><b>'+usd(fmt2(spendMonthTotal()))+'</b></td><td></td><td></td></tr>'+
     '</tbody></table></div><div class="panel-b"><p class="muted" style="font-size:12px;margin:0">The oxagen line and the light, embed and rerank rows are oxagen’s own work, routed by tier and billed back at vendor cost plus a published markup; they count toward the organization’s funding cap and are set under <a href="#/'+ORG.slug+'">Organization → Model routes</a>.</p></div></div>';
  } else if(t==="tool"){
    body=spendByTool();
  } else if(t==="waste"){
    body=spendWaste();
  } else {
    body='<div class="panel"><div class="panel-h"><h3>Budgets</h3>'+
     '<button class="btn sm" style="margin-left:auto" onclick="openDialog(\'budget\')">Set a budget</button></div><div class="tw"><table>'+
     '<thead><tr><th>Scope</th><th>Period</th><th class="num">Limit</th><th class="num">Used</th><th>Mode</th><th>Position</th><th></th></tr></thead><tbody>'+
     SPEND.budgets.map(function(b,i){
      var u=parseFloat(b.used.replace(/,/g,""))/parseFloat(b.limit.replace(/,/g,""));
      return '<tr><td class="tkey" style="font-size:12px">'+h(b.scope)+'</td><td>'+h(b.period)+'</td>'+
       '<td class="num">'+usd(b.limit)+'</td><td class="num">'+usd(b.used)+'</td>'+
       '<td><span class="b b-'+(b.mode==="hard"?"denied":"approval")+'">'+h(b.mode)+'</span></td>'+
       '<td style="min-width:170px"><div class="bar"><i style="width:'+Math.round(u*100)+'%;background:'+(u>0.8?"var(--st-critical)":"var(--st-allowed)")+'"></i></div>'+
       '<div class="dim" style="font-size:11px">'+per(u)+'</div></td>'+
       '<td class="num" style="white-space:nowrap"><button class="btn sm" onclick="openDialog(\'budgetedit\',\''+i+'\')">Edit</button> '+
       '<button class="btn sm danger" onclick="openDialog(\'budgetdel\',\''+i+'\')">Remove</button></td></tr>';}).join("")+
     '</tbody></table></div><div class="panel-b"><div class="note">Hard budgets are checked at each hook boundary, from a running counter fed by the usage each harness reports. A breach is a <span class="mono">policy.decision</span> frame and a pause at the next boundary: client-attested and fail-open. On the <span class="mono">gateway</span> and <span class="mono">contained</span> tiers the proxy enforces the ceiling before the call.</div></div></div>';
  }
  return '<div class="phead"><div class="t"><p class="eyebrow">'+h(w.name)+'</p><h1>Spend</h1>'+
   '<p>What the tokens bought, with the basis on every number.</p></div>'+
   '<div class="acts"><button class="btn" onclick="openDialog(\'spendexport\')">Export report</button>'+
   '<button class="btn primary" onclick="openDialog(\'budget\')">Set a budget</button></div></div>'+(drill?'':strip)+tabs+body;
}

/* ---------- Tokens: where the month's tokens went, by class, by prompt part, by harness ---------- */
function coachCount(){
  var n=0;
  ["agents","operators"].forEach(function(kind){coachSubjects(kind).forEach(function(s){n+=s.items.length;});});
  return n;
}
function spendTokens(WT){
  var w=ws(), sp=spendMonthTotal();
  var cls=[["input_uncached",WT.tokIn-WT.cacheRead,"prompt tokens processed fresh"],["cache_read",WT.cacheRead,"prompt tokens served from cache, priced at a tenth"],
    ["cache_write",WT.cacheWrite,"prompt tokens written to cache, by TTL"],["output",WT.output,"completion tokens, excluding reasoning"],["reasoning",WT.reasoning,"thinking tokens, where the provider reports them"]];
  var clsTot=cls.reduce(function(a,x){return a+x[1];},0);
  var per$=function(tok){return sp*tokShare(tok,clsTot);};
  var hs=Object.keys(WT.byHarness).map(function(k){return WT.byHarness[k];}).sort(function(a,b){return b.total-a.total;});
  return '<div class="grid g2" style="margin-bottom:14px">'+
   '<div class="panel" style="margin:0"><div class="panel-h"><h3>By token class</h3><span class="mono dim" style="margin-left:auto;font-size:11px">'+tokn(WT.total)+'</span></div>'+
    '<div class="tw"><table class="narrow" data-lt="off"><thead><tr><th>Class</th><th class="num">Tokens</th><th class="num">Share</th><th class="num">Cost</th></tr></thead><tbody>'+
    cls.map(function(x){return '<tr><td class="mono"'+tipAttr(x[2])+'>'+x[0]+'</td><td class="num">'+tokn(x[1])+'</td><td class="num dim">'+per(tokShare(x[1],clsTot))+'</td><td class="num">'+(x[0]==="cache_read"?fmt$(per$(x[1])*0.1):fmt$(per$(x[1])))+'</td></tr>';}).join("")+
    '</tbody></table></div><div class="panel-b"><dl class="kv">'+
    '<dt>Cache hit rate</dt><dd>'+per(WT.cacheRate)+' · cache_read ÷ (input_uncached + cache_read), token-weighted</dd>'+
    '<dt>Cache write cost share</dt><dd>'+per(tokShare(WT.cacheWrite*1.25,WT.tokIn))+' · high when a prefix is written and never read</dd>'+
    '<dt>Effective input price</dt><dd>$1.88 per million across every input class</dd>'+
    '<dt>Unmapped classes</dt><dd>0 · a class oxagen does not know is stored under its raw name and priced at zero, so the gap stays visible</dd></dl></div></div>'+
   '<div class="panel" style="margin:0"><div class="panel-h"><h3>Prompt composition</h3></div>'+
    '<div class="panel-b">'+tokBars(WT)+'</div>'+
    '<div class="panel-b" style="border-top:1px solid var(--border)"><div class="note">Tool definitions, context frames and steering are measured by oxagen from the request it assembled; tool results and conversation are the rest of the input. A part that grows without its citation rate growing is a finding, and Coaching says what to change.</div></div></div></div>'+
   '<div class="panel" style="margin-bottom:14px"><div class="panel-h"><h3>By harness</h3><span class="b b-q" style="margin-left:auto">'+per(WT.observed)+' of tokens observed by the gateway</span></div>'+
    '<div class="tw"><table><thead><tr><th>Harness</th><th class="num">Agents</th><th class="num">Tokens</th><th class="num">Cache hit</th><th class="num">Spend</th><th>Basis</th></tr></thead><tbody>'+
    hs.map(function(x){var obs=tokShare(x.observed,x.total);
      return '<tr><td><b>'+h(x.label)+'</b></td><td class="num">'+x.agents+'</td><td class="num">'+tokn(x.total)+'</td><td class="num">'+per(tokShare(x.cacheRead,x.tokIn))+'</td><td class="num">'+fmt$(x.spend)+'</td>'+
       '<td>'+(obs>=0.999?basisChip("gateway_observed") :obs<=0.001?basisChip("client_attested") :basisChip("gateway_observed")+' '+per(obs)+' · '+basisChip("client_attested")+' '+per(1-obs))+'</td></tr>';}).join("")+
    '</tbody></table></div><div class="panel-b"><div class="note">Observed means the gateway\u2019s proxy counted the tokens from the bytes that passed through it. Self-reported means the harness\u2019s own telemetry said so; a class it does not report is marked absent, never zero, and a cache hit rate over a mixed fleet is never computed from missing data as if it were zero.</div></div></div>'+
   '<div class="panel"><div class="panel-h"><h3>By agent</h3></div>'+
    '<div class="tw"><table><thead><tr><th>Agent</th><th class="num">Runs</th><th class="num">Tokens</th><th class="num">Per run</th><th class="num">Cache hit</th><th class="num">Tool defs</th><th class="num">Context</th><th class="num">Tool results</th><th class="num">Reasoning</th><th>Basis</th></tr></thead><tbody>'+
    AGENTS.filter(function(a){return a.ws===w.slug;}).sort(function(a,b){return agentTok(b).total-agentTok(a).total;}).slice(0,12).map(function(a){var t=agentTok(a);
      return '<tr class="click" onclick="go(\'#/'+ORG.slug+'/'+a.ws+'/agents/'+a.key.split(".").pop()+'\')"><td>'+agentCard(a,{key:a.key})+'</td><td class="num">'+(a.runs30||0).toLocaleString()+'</td><td class="num">'+tokn(t.total)+'</td><td class="num">'+tokn(t.perRun)+'</td><td class="num">'+per(t.cacheRate)+'</td>'+
       '<td class="num'+(t.shares.tools>0.16?'" style="color:var(--st-approval)':'')+'">'+per(t.shares.tools)+'</td><td class="num">'+per(t.shares.ctx)+'</td><td class="num'+(t.shares.results>0.3?'" style="color:var(--st-approval)':'')+'">'+per(t.shares.results)+'</td><td class="num">'+per(tokShare(t.reasoning,t.tokOut))+'</td>'+
       '<td class="dim" style="font-size:11px">'+basisChip(t.observed?'gateway_observed':'client_attested')+'</td></tr>';}).join("")+
    '</tbody></table></div></div>';
}
/* ---------- Coaching: the agents and operators with something to change ----------
   The tab opens on the subjects that have a row, worst severity first, then the most rows, then the
   most money. A subject with nothing to change is not a row: a panel per agent saying "nothing to
   change" is the page reporting work that does not exist. Opening one shows every row in full, with
   the signal behind it, the one action that moves it, and a dismiss. Dismissal is keyed by subject
   and signal, so a signal the rollup raises again after the record changes comes back as a new row
   rather than staying buried. */
var COACH_SEV={denied:{r:0,l:"high"},approval:{r:1,l:"medium"},q:{r:2,l:"low"}};
function coachKey(kind,id,k){return kind+":"+id+":"+k;}
function coachRank(c){return COACH_SEV[c.sev]?COACH_SEV[c.sev].r:2;}
function coachWorstLabel(r){var out="\u2014";Object.keys(COACH_SEV).forEach(function(k){if(COACH_SEV[k].r===r)out=COACH_SEV[k].l;});return out;}
function coachAll(kind,id){return kind==="operators"?coachOperator(id):coachAgent(id);}
function coachItems(kind,id){return coachAll(kind,id).filter(function(c){return !S.coachOff[coachKey(kind,id,c.k)];});}
function coachHidden(kind,id){return coachAll(kind,id).filter(function(c){return !!S.coachOff[coachKey(kind,id,c.k)];});}
function coachDismiss(kind,id,k){
  S.coachOff[coachKey(kind,id,k)]=1; render();
  act("Row dismissed. The signal stays in the rollup and returns if it is raised again.");
}
function coachRestore(kind,id,k){delete S.coachOff[coachKey(kind,id,k)];render();act("Restored.");}
function coachLabel(kind,id){return kind==="operators"?(PEOPLE[id]?PEOPLE[id].name:id):id;}
function coachPool(kind){
  var w=ws(), mine=AGENTS.filter(function(a){return a.ws===w.slug;});
  if(kind!=="operators") return mine.length;
  var ops={}; mine.forEach(function(a){ops[a.operator]=1;});
  return Object.keys(ops).filter(function(p){return PEOPLE[p];}).length;
}
/* Every subject in this workspace with at least one live row, ranked. */
function coachSubjects(kind){
  var w=ws(), mine=AGENTS.filter(function(a){return a.ws===w.slug;}), ids;
  if(kind==="operators"){var ops={};mine.forEach(function(a){ops[a.operator]=1;});ids=Object.keys(ops).filter(function(p){return PEOPLE[p];});}
  else ids=mine.map(function(a){return a.key;});
  return ids.map(function(id){
    var items=coachItems(kind,id).sort(function(x,y){return coachRank(x)-coachRank(y)||y.usd-x.usd;});
    return {id:id,label:coachLabel(kind,id),items:items,hidden:coachHidden(kind,id).length,
            worst:items.reduce(function(n,c){return Math.min(n,coachRank(c));},9),
            usd:items.reduce(function(n,c){return n+c.usd;},0)};})
   .filter(function(s){return s.items.length;})
   .sort(function(a,b){return a.worst-b.worst||b.items.length-a.items.length||b.usd-a.usd;});
}
function coachSubject(kind,id){return coachSubjects(kind).filter(function(s){return s.id===id;})[0]||null;}
function coachSevChips(items){
  var n={}; items.forEach(function(c){n[c.sev]=(n[c.sev]||0)+1;});
  return ["denied","approval","q"].filter(function(s){return n[s];})
   .map(function(s){return '<span class="b b-'+s+'"><span class="d"></span>'+n[s]+' '+COACH_SEV[s].l+'</span>';}).join(" ");
}
function coachTo(id){S.coachDrill=id||null;render();}
function coachSub(kind){S.coachFor=kind;S.coachDrill=null;render();}
function coachJump(label){
  var kind=S.coachFor||"agents", hit=coachSubjects(kind).filter(function(s){return s.label===label;})[0];
  if(!hit){act("Nothing with coaching matches \u201c"+label+"\u201d.");return;}
  coachTo(hit.id);
}
/* The jump control is a datalist, so typing filters a list the browser already holds and a name
   that is not on it is refused rather than opening the wrong subject. */
function coachPicker(kind){
  var subs=coachSubjects(kind);
  return '<input class="coach-pick" list="coachPickList" value="" autocomplete="off" '+
   'placeholder="Jump to another '+(kind==="operators"?"operator":"agent")+' \u2014 '+subs.length+' with coaching" '+
   'aria-label="Jump to another subject" onchange="coachJump(this.value)">'+
   '<datalist id="coachPickList">'+subs.map(function(s){
     return '<option value="'+h(s.label)+'">'+h(s.items.length+" row"+(s.items.length===1?"":"s")+" \u00b7 "+fmt$(s.usd)+" a month")+'</option>';}).join("")+'</datalist>';
}
function coachOffCount(kind){var n=0;Object.keys(S.coachOff).forEach(function(k){if(S.coachOff[k]&&k.indexOf(kind+":")===0)n++;});return n;}
function coachClear(kind){Object.keys(S.coachOff).forEach(function(k){if(k.indexOf(kind+":")===0)delete S.coachOff[k];});render();act("Dismissed rows restored.");}
function coachFoot(){
  return '<div class="note" style="margin-top:14px">Coaching is derived from the same rollup the Tokens tab prints, at read time, so the two cannot disagree. '+
   'Each row names its signal, the tokens and money behind it, and the one change that moves it. Sending a note records it as a governed action; nothing here changes an agent by itself.</div>';
}
function spendCoaching(){
  var w=ws(), kind=S.coachFor||"agents";
  var aN=coachSubjects("agents"), oN=coachSubjects("operators"), subs=kind==="operators"?oN:aN;
  var drill=S.coachDrill?coachSubject(kind,S.coachDrill):null;
  var tot=function(l){return l.reduce(function(n,s){return n+s.usd;},0);};
  var rows=function(l){return l.reduce(function(n,s){return n+s.items.length;},0);};
  var worst=[].concat(aN,oN).sort(function(a,b){return a.worst-b.worst;})[0];
  var pick='<div class="tabs" role="tablist" style="margin-bottom:12px">'+
   [["agents","Agents",rows(aN)],["operators","Operators",rows(oN)]].map(function(x){
    return '<button class="tab" role="tab" aria-selected="'+(kind===x[0])+'" onclick="coachSub(\''+x[0]+'\')">'+x[1]+
     (x[2]?'<span class="n">'+x[2]+'</span>':'')+'</button>';}).join("")+'</div>';
  var strip='<div class="grid g3" style="margin-bottom:14px">'+
   '<div class="stat"><span class="k">Agents to coach</span><span class="v">'+aN.length+'</span><span class="s">'+rows(aN)+' rows \u00b7 '+fmt$(tot(aN))+' a month at stake</span></div>'+
   '<div class="stat"><span class="k">Operators to coach</span><span class="v">'+oN.length+'</span><span class="s">'+rows(oN)+' rows \u00b7 '+fmt$(tot(oN))+' a month at stake</span></div>'+
   '<div class="stat"><span class="k">Worst open</span><span class="v">'+(worst?coachWorstLabel(worst.worst):"\u2014")+'</span>'+
   '<span class="s">'+(worst?h(worst.label):"nothing open")+'</span></div></div>';

  if(drill) return strip+pick+coachDetail(kind,drill);

  if(!subs.length){
    var off=coachOffCount(kind);
    return strip+pick+'<div class="panel"><div class="panel-b"><p class="muted" style="margin:0;font-size:12.5px">'+
     '<b>Nothing to change.</b> Every '+(kind==="operators"?"operator":"agent")+' in '+h(w.name)+' is inside the workspace norm on every signal the rollup reads'+
     (off?', and '+off+' row'+(off===1?" is":"s are")+' dismissed. <a href="#" onclick="event.preventDefault();coachClear(\''+kind+'\')">Restore them</a>':'.')+
     '</p></div></div>';
  }

  var body='<div class="panel"><div class="panel-h"><div style="flex:1;min-width:0"><h3>'+(kind==="operators"?"Operators":"Agents")+' with coaching</h3>'+
   '<p class="muted" style="margin:2px 0 0;font-size:12px">Worst severity first, then the most rows. Open one to read its evidence and act.</p></div>'+
   '<div class="sp"><span class="b b-q">'+subs.length+' of '+coachPool(kind)+'</span>'+
   (coachOffCount(kind)?'<button class="btn sm" onclick="coachClear(\''+kind+'\')">Restore '+coachOffCount(kind)+' dismissed</button>':'')+'</div></div>'+
   '<div class="tw"><table><thead><tr><th>'+(kind==="operators"?"Operator":"Agent")+'</th><th>Severity</th><th class="num">Rows</th>'+
   '<th class="num">At stake</th><th>Top row</th><th class="num">Tokens</th><th class="num">Cache hit</th></tr></thead><tbody>'+
   subs.map(function(s){var t=kind==="operators"?operatorTok(s.id):agentTok(s.id);
    return '<tr '+rowClick("coachTo('"+s.id.replace(/'/g,"\\'")+"')","Open coaching for "+s.label)+'>'+
     '<td>'+(kind==="operators"
       ? '<span class="row" style="gap:8px">'+personAv(s.id,24)+'<b>'+h(s.label)+'</b></span><div class="dim mono" style="font-size:11px">'+h(PEOPLE[s.id].role)+'</div>'
       : agentCard(s.id,{layout:"compact",key:s.id}))+'</td>'+
     '<td>'+coachSevChips(s.items)+'</td>'+
     '<td class="num">'+s.items.length+(s.hidden?'<div class="dim" style="font-size:11px">'+s.hidden+' dismissed</div>':'')+'</td>'+
     '<td class="num">'+fmt$(s.usd)+'</td>'+
     '<td style="font-size:12px">'+h(s.items[0].title)+'</td>'+
     '<td class="num">'+(t?tokn(t.total):"\u2014")+'</td><td class="num">'+(t?per(t.cacheRate):"\u2014")+'</td></tr>';}).join("")+
   '</tbody></table></div></div>';
  return strip+pick+body+coachFoot();
}
/* One subject, opened: its token profile, then every row with its signal, its action and a dismiss. */
function coachDetail(kind,s){
  var t=kind==="operators"?operatorTok(s.id):agentTok(s.id), hid=coachHidden(kind,s.id);
  var head='<div class="coach-head">'+
   '<button class="btn sm" onclick="coachTo(null)">\u2039 All '+(kind==="operators"?"operators":"agents")+'</button>'+
   '<div class="coach-who">'+(kind==="operators"
     ? personAv(s.id,32)+'<div style="min-width:0"><b>'+h(s.label)+'</b><div class="dim mono" style="font-size:11px">'+h(PEOPLE[s.id].role)+' \u00b7 '+plural(t.agents,"agent")+'</div></div>'
     : agentCard(s.id,{layout:"compact",key:s.id}))+'</div>'+
   coachPicker(kind)+'</div>';
  var prof='<div class="grid g4" style="margin-bottom:14px">'+
   '<div class="stat"><span class="k">Rows open</span><span class="v">'+s.items.length+'</span><span class="s">'+coachSevChips(s.items)+'</span></div>'+
   '<div class="stat"><span class="k">At stake</span><span class="v">'+fmt$(s.usd)+'</span><span class="s">a month, across every row below</span></div>'+
   '<div class="stat"><span class="k">Tokens</span><span class="v">'+(t?tokn(t.total):"\u2014")+'</span><span class="s">'+(t?per(t.cacheRate)+" served from cache":"")+'</span></div>'+
   '<div class="stat"><span class="k">Basis</span><span class="v" style="font-size:15px">'+basisChip(t&&t.observed?"gateway_observed":"client_attested")+'</span>'+
   '<span class="s">'+(t&&t.observed?"counted by the proxy":"reported by the harness")+'</span></div></div>';
  var cards='<div style="display:grid;gap:10px">'+s.items.map(function(c){return coachCard(c,s.label,{kind:kind,id:s.id});}).join("")+'</div>';
  var back=hid.length?'<div class="panel" style="margin-top:14px"><div class="panel-h"><h3>Dismissed</h3>'+
   '<span class="b b-q" style="margin-left:auto">'+hid.length+'</span></div><div class="panel-b" style="display:grid;gap:8px">'+
   hid.map(function(c){return '<div class="row" style="gap:10px"><span class="b b-'+c.sev+'" style="flex:none"><span class="d"></span>'+h(c.title)+'</span>'+
    '<span class="dim mono grow" style="font-size:11px;min-width:0">'+c.signal+'</span>'+
    '<button class="btn sm" style="flex:none" onclick="coachRestore(\''+kind+'\',\''+s.id.replace(/'/g,"\\'")+'\',\''+h(c.k)+'\')">Restore</button></div>';}).join("")+
   '</div></div>':'';
  return head+prof+cards+back+coachFoot();
}
/* ---------- Spend drill-down: an operator, agent or tool → every metric, and its findings as potential savings ---------- */
function n$(s){return parseFloat(String(s).replace(/,/g,""))||0;}
function fmt$(n){return usd(Number(n).toFixed(2));}
function spendHref(kind,id){return '#/'+ORG.slug+'/'+ws().slug+'/spend/'+kind+(id?'/'+encodeURIComponent(id):'');}
/* Tabs and drills both write the hash: route() re-applies the hash's tab on every render, so state alone snaps back. */
function spendGo(kind,id){
  S.tab.spend=kind; S.spendDrill=id?{kind:kind,id:id}:null;
  var hh=spendHref(kind,id); if(location.hash!==hh) location.hash=hh; render();
}
function spendDrillOk(d){return !!(d&&spendEntity(d.kind,d.id));}
/* The row behind a drill: the byOperator / byAgent / byTool entry plus its SPEND_DETAIL extras. */
function spendEntity(kind,id){
  var row=null;
  if(kind==="operator") row=SPEND.byOperator.filter(function(o){return o.p===id;})[0];
  else if(kind==="agent") row=SPEND.byAgent.filter(function(a){return a.k===id;})[0];
  else if(kind==="tool") row=SPEND.byTool.filter(function(t){return t.t===id&&t.perCall!==null;})[0];
  if(!row) return null;
  return {kind:kind,id:id,row:row,d:SPEND_DETAIL[kind+":"+id]||{},
          spend:kind==="tool"?row.spend:n$(row.spend),name:kind==="operator"?PEOPLE[id].name:id};
}
/* A finding belongs to an entity when it is the subject, or when its evidence names the entity. */
function findingsFor(kind,id){
  var p=kind==="operator"?PEOPLE[id]:null;
  return FINDINGS.filter(function(f){
    var e=EVIDENCE[f.id]||{}, who=e.who||{};
    if(kind==="agent") return (f.level==="agent"&&f.subject===id)||who.agent===id;
    if(kind==="operator") return (f.level==="operator"&&p&&f.subject===p.name)||who.operator===id;
    if(kind==="tool") return f.level==="tool"&&f.subject===id;
    return false;});
}
function fndDirect(f,kind){return kind==="operator"?f.level==="operator":f.level===kind;}
/* The Potential-savings cell on the three list tables. */
function savingsCell(kind,id){
  var fs=findingsFor(kind,id); if(!fs.length) return '<td class="num"><span class="dim">—</span></td>';
  var s=fs.reduce(function(a,f){return a+n$(f.save);},0);
  return '<td class="num"><b style="color:var(--st-approval)">'+fmt$(s)+'</b><div class="dim" style="font-size:10.5px">'+fs.length+' finding'+(fs.length>1?'s':'')+'</div></td>';
}
function drillName(kind,id){
  return '<a class="drill-lnk" href="'+spendHref(kind,id)+'" onclick="event.preventDefault()">'+h(kind==="operator"&&PEOPLE[id]?PEOPLE[id].name:id)+'</a>';
}
function drillRow(kind,id){return ' class="click" onclick="spendGo(\''+kind+'\',\''+h(id)+'\')"';}
/* One finding as a ranked card; shared by the Findings tab and every drill-down. */
function fndCard(f,i,total,top,ofLabel){
  var e=EVIDENCE[f.id]||{}, who=e.who||{}, p=PEOPLE[who.operator], share=n$(f.save)/top;
  return '<article class="fnd"><div class="rank">'+(i+1)+'</div><div>'+
   '<div class="t"><b>'+h(f.kind)+'</b><span class="b b-q">'+h(f.level)+'</span>'+
   (e.confidence?'<span class="b b-'+(e.confidence==="high"?"allowed":"approval")+'">'+h(e.confidence)+' confidence</span>':'')+'</div>'+
   '<div class="who">'+(p?avatarHtml(p.avatar,20,"person")+'<span>'+h(p.name)+'</span><span class="dim">·</span>':'')+
   '<span class="mono">'+h(who.agent||f.subject)+'</span></div>'+
   '<p class="why">'+h(f.why)+'</p>'+
   '<div class="meta">evidence '+h(f.frames)+' · '+h(f.window)+(e.trend?' · trend '+h(e.trend):'')+'</div></div>'+
   '<div class="amt"><div class="v">'+usd(fmt2(n$(f.save)))+'</div><div class="s">at stake · '+Math.round(n$(f.save)/total*100)+'% '+h(ofLabel||"of identified")+'</div>'+
   '<div class="bar"><i style="width:'+Math.round(share*100)+'%"></i></div>'+
   '<div class="acts"><button class="btn sm" onclick="openDialog(\'evidence\',\''+h(f.id)+'\')">Evidence</button>'+
   '<button class="btn sm" onclick="openDialog(\'fix\',\''+h(f.id)+'\')">Fix</button></div></div></article>';
}
/* Daily spend for the last 30 days, derived deterministically from the entity key so the seed stays small.
   Weekends dip (schedules), and the entity's month-over-month trend tilts the line. */
function spendSeries(key,total,trend){
  var hsh=7; for(var i=0;i<key.length;i++) hsh=(hsh*31+key.charCodeAt(i))>>>0;
  var slope=parseFloat(trend)||0, pts=[], sum=0;
  for(var d=0;d<30;d++){ hsh=(hsh*1103515245+12345)>>>0; var r=(hsh>>>8)/16777216, back=29-d;
    var wk=(back%7===5||back%7===6)?0.42:1, v=wk*(0.7+0.6*r)*(1+slope/100*(d/29)); pts.push(v); sum+=v; }
  return pts.map(function(v){return v/sum*total;});
}
function dayLabel(i,n){return new Date(Date.UTC(2026,8,11)-(n-1-i)*864e5).toLocaleDateString("en-US",{month:"short",day:"numeric",timeZone:"UTC"});}
/* Single series: no legend, one thin line, a hover target per day. Text stays in text tokens outside the svg. */
function sparkline(pts,label){
  var W=600,H=72,pad=3,mx=Math.max.apply(null,pts),n=pts.length,cw=(W-2*pad)/(n-1);
  function x(i){return pad+i*cw;} function y(v){return H-pad-(v/mx)*(H-2*pad-6);}
  var line=pts.map(function(v,i){return (i?'L':'M')+x(i).toFixed(1)+' '+y(v).toFixed(1);}).join(' ');
  var area=line+' L'+x(n-1).toFixed(1)+' '+(H-pad)+' L'+x(0).toFixed(1)+' '+(H-pad)+' Z';
  var hover=pts.map(function(v,i){return '<rect x="'+(x(i)-cw/2).toFixed(1)+'" y="0" width="'+cw.toFixed(1)+'" height="'+H+'" fill="transparent"><title>'+dayLabel(i,n)+' · '+fmt$(v)+'</title></rect>';}).join('');
  return '<svg class="spark" viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="none" role="img" aria-label="'+h(label)+'">'+
   '<path d="'+area+'" fill="currentColor" opacity=".08"/>'+
   '<path d="'+line+'" fill="none" stroke="currentColor" stroke-width="1.75" vector-effect="non-scaling-stroke" stroke-linejoin="round"/>'+hover+'</svg>';
}
function tile(k,v,s,col){return '<div class="stat"><span class="k">'+k+'</span><span class="v"'+(col?' style="color:'+col+'"':'')+'>'+v+'</span><span class="s">'+s+'</span></div>';}
/* A cross-cut: this entity's spend split by another dimension; rows that are themselves entities drill further. */
function xcut(title,pairs,kind,total){
  if(!pairs||!pairs.length) return '';
  var mx=Math.max.apply(null,pairs.map(function(p){return p[1];}));
  return '<div class="panel"><div class="panel-h"><h3>'+h(title)+'</h3><span class="b b-q" style="margin-left:auto">share of '+fmt$(total)+'</span></div><div class="panel-b" style="display:grid;gap:11px">'+
   pairs.map(function(p){var ok=spendEntity(kind,p[0]), nm=kind==="operator"&&PEOPLE[p[0]]?PEOPLE[p[0]].name:p[0];
    var lab=ok?'<a class="mono drill-lnk" href="'+spendHref(kind,p[0])+'" onclick="event.preventDefault();spendGo(\''+kind+'\',\''+h(p[0])+'\')">'+h(nm)+'</a>':'<span class="mono dim" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+h(nm)+'</span>';
    return '<div class="meter"><div class="lab" style="display:flex;gap:8px;font-size:11.5px;color:var(--muted)">'+lab+
     '<span style="margin-left:auto;color:var(--fg);font-weight:600;font-variant-numeric:tabular-nums;flex:none">'+fmt$(p[1])+' <span class="dim" style="font-weight:500">· '+per(p[1]/total)+'</span></span></div>'+
     '<div class="bar"><i style="width:'+Math.max(1,Math.round(p[1]/mx*100))+'%;background:var(--st-observe)"></i></div></div>';}).join("")+'</div></div>';
}
function spendDrill(dr){
  var E=spendEntity(dr.kind,dr.id), r=E.row, d=E.d, kind=E.kind, spend=E.spend, monthN=spendMonthTotal();
  var fs=findingsFor(kind,E.id).slice().sort(function(a,b){return n$(b.save)-n$(a.save);});
  var save=fs.reduce(function(s,f){return s+n$(f.save);},0), top=fs.length?n$(fs[0].save):1;
  var kindLabel={operator:"Operator",agent:"Agent",tool:"Tool"}[kind], listLabel={operator:"By operator",agent:"By agent",tool:"By tool"}[kind];
  var eyebrow, sub, a=null;
  if(kind==="operator"){var p=PEOPLE[E.id]; eyebrow=h(kindLabel)+' · <span class="id">'+h(p.role)+'</span>'; sub=plural(r.agents,"agent")+' · '+plural(r.runs.toLocaleString(),"run")+' · '+SPEND.month;}
  else if(kind==="agent"){a=AGENTS.filter(function(x){return x.key===E.id;})[0]; eyebrow=h(kindLabel+(a?' · '+a.harnessLabel+' · operator '+PEOPLE[a.operator].name:'')); sub=plural(r.runs.toLocaleString(),"run")+' · '+SPEND.month;}
  else {eyebrow=h(kindLabel)+' · provider <span class="id">'+h(r.s)+'</span>'; sub=plural(r.calls.toLocaleString(),"call")+' across '+plural(r.runs.toLocaleString(),"run")+' · '+SPEND.month+(r.note&&r.note!=="—"?' · '+r.note:'');}

  var head='<div class="drill-bar"><a href="'+spendHref(kind)+'" onclick="event.preventDefault();spendGo(\''+kind+'\')">← '+listLabel+'</a><span class="dim">/</span><span class="mono">'+h(E.name)+'</span></div>'+
   '<div class="phead drill-head" style="margin-bottom:14px"><div class="t"><p class="eyebrow">'+eyebrow+'</p><h2'+(kind==="operator"?'':' class="mono"')+'>'+h(E.name)+'</h2><p>'+h(sub)+'</p></div>'+
   '<div class="acts">'+(a?'<button class="btn" onclick="go(\'#/'+ORG.slug+'/'+a.ws+'/agents/'+h(a.key)+'\')">Open the agent</button>':'')+
   '<button class="btn" onclick="act(\'Report for '+h(E.name)+' exported: CSV and a signed PDF.\')">Export this view</button></div></div>';

  var hero;
  if(fs.length){
    var ramp=[1,.8,.64,.5,.38,.28], direct=fs.filter(function(f){return fndDirect(f,kind);}).length;
    var strip=fs.map(function(f,i){return '<i style="flex:'+n$(f.save)+';opacity:'+ramp[i%ramp.length]+'" title="'+h(f.kind)+' · '+usd(f.save)+'"></i>';}).join("");
    var legend=fs.map(function(f,i){return '<span><i style="opacity:'+ramp[i%ramp.length]+'"></i>'+h(f.kind)+' <span class="mono">'+Math.round(n$(f.save)/save*100)+'%</span></span>';}).join("");
    hero='<div class="sv-hero"><div><p class="eyebrow">Potential savings</p><div class="sv-amt">'+fmt$(save)+'</div>'+
     '<div class="sv-sub">'+(save/spend*100).toFixed(1)+'% of the '+fmt$(spend)+' this '+kind+' spent in '+h(SPEND.month)+' · about '+fmt$(save*12)+' a year at this run rate</div></div>'+
     '<div><div class="sv-strip" role="img" aria-label="Share of potential savings by finding">'+strip+'</div><div class="sv-legend">'+legend+'</div>'+
     '<div class="sv-facts"><span><b>'+fs.length+'</b> finding'+(fs.length>1?'s':'')+'</span><span><b>'+direct+'</b> on this '+kind+' directly'+
     (fs.length-direct?' · <b>'+(fs.length-direct)+'</b> attributed through evidence':'')+'</span><span>every one opens to its evidence</span></div></div></div>';
  } else {
    hero='<div class="sv-hero"><div><p class="eyebrow">Potential savings</p><div class="sv-amt dim">$0.00</div>'+
     '<div class="sv-sub">No findings cite this '+kind+'. Every dollar below is accounted for in the metrics; nothing measured here is identified as removable.</div></div>'+
     '<div class="sv-facts" style="align-self:end"><span><b>0</b> findings</span><span>findings are frame patterns, re-derived on every rollup</span></div></div>';
  }

  var T=[], share=per(spend/monthN), wasted=d.wasted||0, OT=kind==="operator"?operatorTok(E.id):null, AT=kind==="agent"?agentTok(E.id):null;
  if(kind==="operator"){
    T=[["Spend · "+h(SPEND.month), fmt$(spend), share+' of workspace · '+(OT.observed>=0.999?basisChip("gateway_observed") :OT.observed<=0.001?basisChip("client_attested") :basisChip("gateway_observed")+' '+per(OT.observed)+' · '+basisChip("client_attested")+' '+per(1-OT.observed))],
       ["Tokens", tokn(OT.total), tokn(OT.tokIn)+' in · '+tokn(OT.tokOut)+' out'],
       ["Cache hit rate", per(OT.cacheRate), tokn(OT.cacheRead)+' input tokens served from cache'],
       ["Observed", per(OT.observed), 'of tokens counted by the gateway · the rest self-reported'],
       ["Wasted", fmt$(wasted), per(wasted/spend)+' of spend · the frames show it bought nothing', "var(--st-critical)"],
       ["Productive ratio", per(r.ratio), 'steps that advanced the task'],
       ["Runs", r.runs.toLocaleString(), plural(r.agents,"agent")+' · '+fmt$(d.perRun||spend/r.runs)+' per run'],
       ["Model calls", (d.modelCalls||0).toLocaleString(), (d.toolCalls||0).toLocaleString()+' tool calls'],
       ["Budget position", per(r.used), 'of '+usd(r.budget)+' monthly', r.used>0.8?"var(--st-critical)":null],
       ["Trend", h(d.trend||"—"), 'spend, same period']];
  } else if(kind==="agent"){
    T=[["Spend · "+h(SPEND.month), fmt$(spend), share+' of workspace · '+basisChip(AT.observed?'gateway_observed':'client_attested')],
       ["Tokens", tokn(AT.total), tokn(AT.perRun)+' per run · '+tokn(AT.perCall)+' per call'],
       ["Cache hit rate", per(AT.cacheRate), tokn(AT.cacheRead)+' input tokens served from cache'],
       ["Tool definitions", per(AT.shares.tools), 'of every request · '+plural(AT.neverCalled,"tool")+' never called', AT.shares.tools>0.16?"var(--st-approval)":null],
       ["Wasted", fmt$(wasted), per(wasted/spend)+' of spend', "var(--st-critical)"],
       ["Spend per run", fmt$(d.perRun||spend/r.runs), plural(r.runs.toLocaleString(),"run")],
       ["Productive ratio", per(d.ratio||0), 'steps that advanced the task'],
       ["Model calls", (d.modelCalls||0).toLocaleString(), (d.toolCalls||0).toLocaleString()+' tool calls'],
       ["Trend", h(r.trend), 'spend vs August']];
    if(d.budget) T.push(["Budget · "+h(d.budget.period), usd(d.budget.used), 'of '+usd(d.budget.limit)+' · '+h(d.budget.mode)+' · '+per(n$(d.budget.used)/n$(d.budget.limit))]);
  } else {
    var total=SPEND.byTool.reduce(function(s,x){return s+x.spend;},0), hot=r.perCall>=1.5||r.perRun>=10;
    T=[["Spend · "+h(SPEND.month), fmt$(spend), per(spend/total)+' of tool-attributed spend · '+basisChip("client_attested")],
       ["Calls", r.calls.toLocaleString(), plural(r.runs.toLocaleString(),"run")+' used it'],
       ["Average per call", fmt$(r.perCall), 'the calling turn plus the turn that read the result'],
       ["Average per run", fmt$(r.perRun), hot?'high for the toolbelt':'spend ÷ runs that used it', hot?"var(--st-approval)":null],
       ["Result body", (d.resTok||0).toLocaleString()+' <span class="dim" style="font-size:12px">tok</span>', 'average tokens returned per call'],
       ["Repeat calls", per(d.rerun||0), 'identical input digest inside a run', (d.rerun||0)>=0.2?"var(--st-approval)":null],
       ["Retries", per(d.retry||0), 'calls repeated after a 4xx or a timeout'],
       ["Cache hit rate", per(d.cache||0), 'prefix reads on the calling turns'],
       ["Wasted", fmt$(wasted), per(wasted/spend)+' of this tool’s spend', "var(--st-critical)"],
       ["Trend", h(d.trend||"—"), 'spend, same period']];
  }
  var tiles='<div class="grid g4" style="margin-bottom:14px">'+T.map(function(t){return tile(t[0],t[1],t[2],t[3]);}).join("")+'</div>';

  var pts=spendSeries(kind+":"+E.id,spend,d.trend||r.trend||""), mx=Math.max.apply(null,pts), pk=pts.indexOf(mx);
  var series='<div class="panel" style="margin-bottom:14px"><div class="panel-h"><h3>Spend by day</h3></div>'+
   '<div class="panel-b">'+sparkline(pts,"Daily spend, last 30 days")+
   '<div class="row" style="margin-top:8px;font-size:11.5px;color:var(--muted);flex-wrap:wrap"><span>peak <b style="color:var(--fg)">'+fmt$(mx)+'</b> on '+dayLabel(pk,30)+'</span><span class="dim">·</span>'+
   '<span>'+fmt$(spend/30)+' a day on average</span><span class="dim">·</span><span>weekends dip with the schedules</span></div></div></div>';

  var cuts;
  if(kind==="tool") cuts=xcut("By agent",d.agents,"agent",spend)+xcut("By operator",d.operators,"operator",spend)+xcut("By model",d.models,"model",spend);
  else if(kind==="agent") cuts=xcut("By tool",d.tools,"tool",spend)+xcut("By model",d.models,"model",spend)+xcut("By operator",d.operators,"operator",spend);
  else cuts=xcut("By agent",d.agents,"agent",spend)+xcut("By tool",d.tools,"tool",spend)+xcut("By model",d.models,"model",spend);
  cuts='<div class="grid g3" style="margin-bottom:14px">'+cuts+'</div>';

  var fnd='<div class="panel"><div class="panel-h"><h3>Findings</h3>'+
   '<span class="dim mono" style="margin-left:auto;font-size:11px">'+(fs.length?fs.length:'none')+'</span></div>'+
   '<div class="panel-b" style="display:grid;gap:10px">'+
   (fs.length?fs.map(function(f,i){return fndCard(f,i,save,top,"of this "+kind+"’s savings");}).join(""):
    '<p class="muted" style="margin:0;font-size:12.5px">No findings cite this '+kind+'. When a rollup finds a frame pattern here it appears in this list with the dollars it would remove, and the same amount shows on the '+listLabel+' table.</p>')+
   '</div>'+(fs.length?'<div class="panel-b" style="border-top:1px solid var(--border)"><div class="note">A finding counts toward this '+kind+' when it is the subject, or when its evidence names it — the badge says which level it was found at. '+
   'Potential savings are measured minus counterfactual over the cited runs, at the price each call actually paid; Fix opens the change that removes it.</div></div>':'')+'</div>';

  return head+hero+tiles+series+(kind==="agent"?spendAgentHistory(E):"")+cuts+fnd;
}

/* Spend by tool — cumulative on the left, average per call on the right, the numbers underneath. */
function spendByTool(){
  var rows=SPEND.byTool, tools=rows.filter(function(r){return r.perCall!==null;});
  var total=rows.reduce(function(s,r){return s+r.spend;},0);
  var mxCum=Math.max.apply(null,rows.map(function(r){return r.spend;}));
  var mxAvg=Math.max.apply(null,tools.map(function(r){return r.perCall;}));
  var mxRun=Math.max.apply(null,tools.map(function(r){return r.perRun;}));
  function money(n){return usd(Number(n).toFixed(2));}
  function bar(label,val,mx,text,col){
    var lk=spendEntity("tool",label);
    return '<div class="meter"><div class="lab" style="display:flex;gap:8px;font-size:11.5px;color:var(--muted)">'+
     (lk?'<a class="mono drill-lnk" href="'+spendHref("tool",label)+'" onclick="event.preventDefault();spendGo(\'tool\',\''+h(label)+'\')">'+h(label)+'</a>':'<span class="mono" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+h(label)+'</span>')+
     '<b style="margin-left:auto;color:var(--fg);font-variant-numeric:tabular-nums;flex:none">'+text+'</b></div>'+
     '<div class="bar"><i style="width:'+Math.max(1,Math.round(val/mx*100))+'%;background:'+col+'"></i></div></div>';
  }
  /* The chart column shows the leading twelve. Thirty-seven bars beside a ten-row table left one
     column four times the height of the other, and every bar below the twelfth rounded to 0%. */
  var TOP=12;
  var cum=rows.slice().sort(function(a,b){return b.spend-a.spend;}).slice(0,TOP).map(function(r){
    return bar(r.t,r.spend,mxCum,money(r.spend)+' <span class="dim" style="font-weight:500">· '+per(r.spend/total)+'</span>',r.perCall===null?"var(--st-observe)":"var(--gold)");}).join("");
  var avg=tools.slice().sort(function(a,b){return b.perCall-a.perCall;}).slice(0,TOP).map(function(r){
    return bar(r.t,r.perCall,mxAvg,money(r.perCall)+' <span class="dim" style="font-weight:500">per call</span>',"var(--st-proven)");}).join("");
  var avgRun=tools.slice().sort(function(a,b){return b.perRun-a.perRun;}).slice(0,TOP).map(function(r){
    return bar(r.t,r.perRun,mxRun,money(r.perRun)+' <span class="dim" style="font-weight:500">per run</span>',"var(--st-approval)");}).join("");
  /* One chart at a time in the right third: three side by side made every bar too short to
     compare, and the three answer the same question at different denominators. */
  var metric=S.toolMetric||"cum";
  var CHART={cum:{h:"Cumulative spend",note:"share of "+money(total),b:cum},
             avgRun:{h:"Average per run",note:"",b:avgRun},
             avgCall:{h:"Average per call",note:"",b:avg}};
  var pickedChart=CHART[metric]||CHART.cum;
  var seg='<div class="seg" role="group" aria-label="Chart">'+
   [["cum","Cumulative spend"],["avgRun","Avg per run"],["avgCall","Avg per call"]].map(function(x){
    return '<button type="button" class="btn sm" aria-pressed="'+(metric===x[0])+'" onclick="S.toolMetric=\''+x[0]+'\';render()">'+x[1]+'</button>';}).join("")+'</div>';
  var charts='<div class="panel" style="margin:0"><div class="panel-h" style="flex-wrap:wrap;gap:8px"><h3>'+pickedChart.h+'</h3>'+
   (pickedChart.note?'<span class="b b-q" style="margin-left:auto">'+pickedChart.note+'</span>':'')+
   '<div style="flex-basis:100%">'+seg+'</div></div>'+
   '<div class="panel-b" style="display:grid;gap:11px">'+pickedChart.b+'</div>'+
   '<div class="panel-b" style="border-top:1px solid var(--border)"><p class="muted" style="margin:0;font-size:11.5px">The leading '+TOP+' of '+rows.length+'. The table holds every tool.</p></div></div>';
  return '<div class="split23">'+
   '<div class="panel" style="margin:0"><div class="panel-h"><h3>By tool</h3></div><div class="tw"><table>'+
   '<thead><tr><th>Tool</th><th>Provider</th><th class="num">Calls</th><th class="num">Runs</th><th class="num">Cumulative</th><th class="num">Share</th><th class="num">Avg per call</th><th class="num">Avg per run</th><th class="num">Potential savings</th><th>What the frames say</th></tr></thead><tbody>'+
   rows.map(function(r){
    var hot=r.perCall!==null&&(r.perCall>=1.5||r.perRun>=10), dr=r.perCall!==null;
    return '<tr'+(dr?drillRow("tool",r.t):'')+'><td class="tkey" style="font-size:12px">'+(dr?drillName("tool",r.t):h(r.t))+'</td><td class="mono dim" style="font-size:11px">'+h(r.s)+'</td>'+
     '<td class="num">'+(r.calls?r.calls.toLocaleString():'<span class="dim">—</span>')+'</td><td class="num">'+r.runs.toLocaleString()+'</td>'+
     '<td class="num"><b>'+money(r.spend)+'</b></td><td class="num">'+per(r.spend/total)+'</td>'+
     '<td class="num">'+(r.perCall===null?'<span class="dim">—</span>':money(r.perCall))+'</td>'+
     '<td class="num"'+(hot?' style="color:var(--st-approval);font-weight:600"':'')+'>'+money(r.perRun)+'</td>'+(dr?savingsCell("tool",r.t):'<td class="num"><span class="dim">—</span></td>')+
     '<td class="muted" style="font-size:12px;min-width:220px">'+h(r.note)+'</td></tr>';}).join("")+
   '</tbody></table></div><div class="panel-b"><div class="note">A tool’s spend is the tokens of the turn that called it plus the turn that read its result, so a cheap-to-price tool with a large result body is an expensive tool. '+
   'Tool prices themselves are on the registry and are billed at zero here; this table is what the model paid to use them.</div></div></div>'+
   charts+'</div>';
}

/* Wasted spend — money whose frames show it bought nothing, and the runs that prove it. */
function spendWaste(){
  var byRun={}; RUNS.forEach(function(r){byRun[r.id]=r;});
  var mx=Math.max.apply(null,SPEND.wasteByCause.map(function(c){return parseFloat(c.spend.replace(/,/g,""));}));
  var strip='<div class="grid g4" style="margin-bottom:16px">'+
   '<div class="stat"><span class="k">Wasted</span><span class="v" style="color:var(--st-critical)">'+usd(SPEND.wasteTotal)+'</span><span class="s">'+basisChip("client_attested")+' · USD</span></div>'+
   '<div class="stat"><span class="k">Share of spend</span><span class="v">'+per(SPEND.wasteShare)+'</span><span class="s">of '+usd(fmt2(spendMonthTotal()))+' this month</span></div>'+
   '<div class="stat"><span class="k">Runs with waste</span><span class="v">'+SPEND.wasteRuns+'</span><span class="s">of '+SPEND.runs.toLocaleString()+' sealed runs</span></div>'+
   '<div class="stat"><span class="k">Largest cause</span><span class="v" style="font-size:17px;padding-top:4px">'+h(SPEND.wasteByCause[0].c)+'</span><span class="s">'+usd(SPEND.wasteByCause[0].spend)+' · '+plural(SPEND.wasteByCause[0].runs,"run")+'</span></div></div>';
  var causes='<div class="panel" style="margin-bottom:14px"><div class="panel-h"><h3>By cause</h3></div>'+
   '<div class="panel-b" style="display:grid;gap:12px">'+
   SPEND.wasteByCause.map(function(c){var v=parseFloat(c.spend.replace(/,/g,""));
    return '<div class="meter"><div class="lab" style="display:flex;gap:8px;font-size:12px;align-items:baseline"><b style="margin-left:0">'+h(c.c)+'</b><span class="dim mono" style="font-size:10.5px">'+plural(c.runs,"run")+'</span>'+
     '<b style="margin-left:auto;font-variant-numeric:tabular-nums">'+usd(c.spend)+'</b></div>'+
     '<div class="bar"><i style="width:'+Math.round(v/mx*100)+'%;background:var(--st-critical)"></i></div>'+
     '<div class="muted" style="font-size:11.5px;margin-top:3px">'+h(c.why)+'</div></div>';}).join("")+'</div></div>';
  var runs='<div class="panel"><div class="panel-h"><h3>Runs with waste</h3>'+
   '</div>'+
   '<div class="panel-b" style="display:grid;gap:12px">'+
   SPEND.wasteRunsList.map(function(x){var r=byRun[x.run]; if(!r) return '';
    var href="#/"+ORG.slug+"/"+r.ws+"/runs/"+r.id;
    var badges=x.badges.map(function(b){return '<span class="b b-'+b[1]+'"><span class="d"></span>'+h(b[0])+'</span>';}).join(SEP);
    var frac=Math.min(1,parseFloat(x.wasted)/parseFloat(r.cost));
    return '<div class="act-card" style="margin:0"><div class="t" style="flex-wrap:wrap"><a class="mono" href="'+href+'" style="font-size:12px">'+h(r.id)+'</a>'+
     '<span class="dim" style="font-size:12px">'+h(r.agent)+' · '+h(PEOPLE[r.op].name)+' · '+h(r.started)+'</span>'+
     '<span style="margin-left:auto;font-variant-numeric:tabular-nums"><b style="color:var(--st-critical)">'+usd(x.wasted)+' wasted</b> <span class="dim">of '+usd(r.cost)+'</span></span></div>'+
     '<div class="row" style="margin-bottom:8px">'+badges+'</div>'+
     '<div class="bar" style="margin-bottom:8px"><i style="width:'+Math.round(frac*100)+'%;background:var(--st-critical)"></i></div>'+
     '<p class="muted" style="margin:0 0 9px;font-size:12.5px"><b style="color:var(--fg)">'+h(r.taskTitle)+'.</b> '+h(x.what)+'</p>'+
     '<div class="row"><span class="dim mono" style="font-size:10.5px">'+plural(r.frames,"frame")+' · '+plural(r.steps,"step")+' · cache '+per(r.cache)+' · '+h(r.model)+'</span>'+
     '<button class="btn sm" style="margin-left:auto" onclick="go(\''+href+'\')">Open the run</button>'+
     '<button class="btn sm" onclick="act(\'Frames that prove the waste on '+r.id+' opened.\')">Show the frames</button></div></div>';}).join("")+
   '</div><div class="panel-b" style="border-top:1px solid var(--border)"><div class="note">Wasted is a claim about frames, not about outcomes: it means the frames show the tokens bought nothing — a repeated call, a cold prefix, a turn spent waiting, a chain that broke. '+
   'Accepted-by-a-human work is never counted here.</div></div></div>';
  return strip+causes+runs;
}

/* The waste list named the wrong tool for the parked invoice-bot run: apr_01K5RN9T4 parks stripe__create_payment@4. */
SPEND.wasteRunsList.forEach(function(w){ if(w.run==="run_01K5RN8F3J2GHY6T") w.what=w.what.replace("aws_billing__purchase_savings_plan","stripe__create_payment@4 ($2,450.00 to vendor:aws)"); });

/* a receipt id as a link to its dialog, where the receipt exists */
function receiptLink(id){var r=receiptById(id);
  return r?'<a class="mono drill-lnk" href="#" onclick="event.preventDefault();openDialog(\'receipt\',\''+h(id)+'\')">'+h(id)+'</a>':'<span class="mono">'+h(id)+'</span>';}
/* The provider key each model bills through, for the By model table. */
var PROVIDER_KEYS=[
 {id:"pk_9f21",src:"Anthropic · pk_9f21",model:"claude-opus-5"},
 {id:"pk_9f21",src:"Anthropic · pk_9f21",model:"claude-sonnet-5"},
 {id:"pk_bdrk_7f2a",src:"AWS Bedrock us-east-1 · pk_bdrk_7f2a",model:"claude-haiku-4-5"},
 {id:"pk_or_5c08",src:"OpenRouter · pk_or_5c08",model:"z-ai/glm-latest (oxagen)"},
 {id:"pk_or_5c08",src:"OpenRouter · pk_or_5c08",model:"z-ai/glm-flash-latest",tier:"light"},
 {id:"pk_vo_2e11",src:"Voyage AI · pk_vo_2e11",model:"voyage-4, voyage-code-3, voyage-context-3",tier:"embed"},
 {id:"pk_vo_2e11",src:"Voyage AI · pk_vo_2e11",model:"rerank-2.5",tier:"rerank"}
];
function spendKeyOf(model,tier){var k=null;
  PROVIDER_KEYS.forEach(function(l){if(tier?l.tier===tier:l.model===model) k=l;}); return k;}

/* Agent over time (W8 agent view): tokens per run by month, and where this month's tokens went. The
   current month is the byAgent row itself; earlier months are history. */
SPEND_DETAIL["agent:a-intel.core.stella-ci"].history=[
 {m:"Mar 2026",spend:887.55,runs:302,cache:0.61},{m:"Apr 2026",spend:948.10,runs:341,cache:0.66},{m:"May 2026",spend:1012.30,runs:388,cache:0.71},
 {m:"Jun 2026",spend:1088.40,runs:421,cache:0.77},{m:"Jul 2026",spend:1151.20,runs:458,cache:0.81},{m:"Aug 2026",spend:1200.76,runs:486,cache:0.84}];
function spendAgentHistory(E){
  var d=E.d, r=E.row, a=agent(E.id), t=a?agentTok(a):null; if(!d.history||!t) return '';
  var pts=d.history.concat([{m:"Sep 2026",spend:n$(r.spend),runs:r.runs,cache:t.cacheRate,cur:true}])
    .map(function(x){return {m:x.m,v:x.runs?x.spend/x.runs:0,cur:x.cur,spend:x.spend,runs:x.runs,cache:x.cache};});
  var mx=Math.max.apply(null,pts.map(function(p){return p.v;})), first=pts[0], last=pts[pts.length-1];
  return '<div class="grid g2 agent-hist" style="margin-bottom:14px">'+
   '<div class="panel"><div class="panel-h"><h3>Monthly spend per run</h3><span class="b b-allowed" style="margin-left:auto">'+
    Math.round((1-last.v/first.v)*100)+'% lower since '+h(first.m)+'</span></div><div class="panel-b" style="display:grid;gap:9px">'+
   pts.map(function(p){return '<div class="meter"><div class="lab"><span'+(p.cur?' style="color:var(--fg);font-weight:600"':'')+'>'+h(p.m)+'</span>'+
     '<b>'+fmt$(p.v)+' <span class="dim" style="font-weight:500">· '+fmt$(p.spend)+' ÷ '+p.runs+' · cache '+per(p.cache)+'</span></b></div>'+
     '<div class="bar"><i style="width:'+Math.max(1,Math.round(p.v/mx*100))+'%;background:var(--st-allowed)"></i></div></div>';}).join("")+
   '</div><div class="panel-b" style="border-top:1px solid var(--border)"><p class="muted" style="margin:0;font-size:12px">Spend ÷ sealed runs. It fell as the cache hit rate rose: the same work, fewer tokens paid at full price.</p></div></div>'+
   '<div class="panel"><div class="panel-h"><h3>Token use</h3><span class="b b-q" style="margin-left:auto">'+tokn(t.total)+' tok</span></div><div class="panel-b">'+tokBars(t,{tight:true})+'</div></div></div>';
}
