/* ---- gate step 1 (the org); steps 2 and 3 are regWrap/regRun in onboard mode ---- */
function obOrg(){
  var err=S.state==="error", w=ws();
  return '<div><p class="eyebrow">Step 1 of 3</p><h1>Name your organization</h1>'+
   '<p class="reg-lead">The organization is the tenant: it owns its own graph database, its own encryption key, its billing account, and the namespace that appears in every agent key.</p></div>'+
   '<div class="reg-card"><div class="cb">'+(err?obErr('<b>That namespace is taken.</b> <span class="mono">'+h(ORG.slug)+'</span> belongs to another organization. Pick a different 2–6 character namespace.')+'<div style="height:14px"></div>':'')+
   '<div class="field"><label for="ob-org">Organization name</label><input id="ob-org" type="text" value="'+h(ORG.name)+'"></div>'+
   '<div class="grid g2"><div class="field"><label for="ob-url">Address</label><input id="ob-url" class="mono" value="oxagen.com/'+h(ORG.slug)+'" readonly><div class="hint">Derived from the name. You can change it later.</div></div>'+
   '<div class="field"><label for="ob-ns">Namespace</label><input id="ob-ns" class="mono'+(err?" ob-bad":"")+'" value="'+h(ORG.slug)+'" maxlength="6"><div class="hint">2–6 characters, <b>immutable</b>. Every agent key starts with it: <span class="mono">'+h(ORG.slug)+'.&lt;workspace&gt;.&lt;agent&gt;</span></div></div></div>'+
   '<div class="hr"></div><h3 style="font-size:13px;margin:0 0 10px">First workspace</h3>'+
   '<div class="grid g2"><div class="field"><label for="ob-ws">Workspace name</label><input id="ob-ws" value="'+h(w.slug)+'"></div>'+
   '<div class="field"><label for="ob-mode">Governance mode</label><select id="ob-mode"><option>solo</option><option selected>team</option><option>regulated</option></select></div></div>'+
   '<div class="dim" style="font-size:12px;line-height:1.5">A workspace is a governance partition: one main repo, one steering set, its own agents, tool grants and budgets.</div>'+
   '</div></div>'+
   '<div class="reg-foot">'+regCancelBtn()+'<div class="sp"><span class="reg-cap">Creates <span class="mono">org_'+h(ORG.slug)+'</span> and its graph database.</span><button class="btn primary" onclick="regNav(\'wrap\')">Continue</button></div></div>';
}
/* step 3, onboard mode: the repo the installer saw — bind it, or stay provisional */
function obRepoPanel(){
  var r=S.reg, w=ws();
  if(r.repo==="bound") return '<div class="reg-card ob-repo"><div class="ch"><span class="reg-ok"><span class="dot"></span>bound</span><h3>Main repo</h3></div><div class="cb">'+
   '<div class="row" style="margin-bottom:10px"><span class="b b-q mono">'+h(w.main)+'</span><span class="b b-q">production branch: '+h(w.branch)+'</span><span class="b b-allowed"><span class="d"></span>GitHub App installed</span></div>'+
   '<p class="muted" style="font-size:12.5px;margin:0">Steering, context records and agent definitions will live in <span class="mono">'+h(w.main)+'</span> under <span class="mono">.oxagen/</span>, published through Context PRs.</p></div></div>';
  if(r.repo==="skipped") return '<div class="reg-card ob-repo"><div class="ch"><span class="b b-denied">provisional</span><h3>No main repo bound</h3></div><div class="cb">'+
   '<p class="muted" style="font-size:12.5px;margin:0 0 10px"><b>'+h(w.slug)+' is provisional until '+h(w.provisional?w.provisional.until:obDate(OB_PROVISIONAL_DAYS))+'</b> ('+plural(OB_PROVISIONAL_DAYS,"day")+'). Runs record and spend counts. Steering, context records, and agent definitions stay off until a main repo is bound.</p>'+
   '<button class="btn sm" onclick="obBind()">Bind '+h(w.main)+' now</button></div></div>';
  return '<div class="reg-card ob-repo"><div class="ch"><h3>Repository detected</h3><span class="sp">reported by the installer</span></div><div class="cb">'+
   '<div class="row" style="margin-bottom:6px"><span class="b b-q mono">git@github.com:'+h(w.main)+'.git</span></div>'+
   '<p class="muted" style="font-size:12.5px;margin:0 0 12px">Read from the git remote of <span class="mono">~/src/platform</span>, the directory the installer ran in. Production branch <span class="mono">'+h(w.branch)+'</span>.</p>'+
   '<button class="btn'+(r.first?"":" primary")+'" onclick="obBind()">'+OB_ICON.github+'<span>Bind '+h(w.main)+' as the main repo</span></button>'+
   '<p class="muted" style="font-size:12.5px;margin:12px 0 0">One click installs the GitHub App on <span class="mono">'+h(w.main)+'</span>: repo binding, Context PRs, checks, merge handling and the code graph.</p>'+
   '<div class="hr"></div><p class="muted" style="font-size:12.5px;margin:0"><button type="button" class="ob-link" style="color:var(--muted)" onclick="obSkip()">Skip for now</button> — '+h(w.slug)+' stays <b>provisional for '+plural(OB_PROVISIONAL_DAYS,"day")+'</b>. Runs record and spend counts, but steering, context records and agent definitions stay off until a main repo is bound.</p></div></div>';
}
function pWelcome(r){
  var step=r.step||"signup";
  if(OB_GATE[step]){
    if(!S.reg||S.reg.mode!=="onboard"){regClear();S.reg=obNew();}
    if(S.state==="loading") return regShell(step,skeleton());
    if(S.state==="denied") return regShell(step,deniedState("onboarding","org.create for "+PEOPLE.marcus.email));
    return regShell(step,step==="organization"?obOrg():step==="wrap"?regWrap():regRun());
  }
  if(step==="installer") return obInstaller();
  if(step==="verify") return obVerify();
  if(step==="login") return obLogin();
  if(step==="two-factor") return obTwoFactor();
  if(step==="forgot") return obForgot();
  if(step==="reset") return obReset();
  if(step==="invite") return obInvite();
  return obSignup();
}

/* ============================== render ============================== */
/* ============================== List controls ============================== */


/* ---- the organization's model key, and the engine the assistant talks to ----
   §4.5 carried two funding sources: `platform`, one Oxagen OpenRouter account for every customer,
   and `customer_key`, the customer's own key with its tokens billed at zero. A third was added on
   2026-09-15 (maintainer decision) and it is now the default for a new organization:

     platform_minted — Oxagen mints one OpenRouter key per organization through the provisioning
     API, on Oxagen's own account, and holds it enveloped. Oxagen owns it, pays for it, and can
     rotate or revoke it, so the tokens are billed like `platform`. What it buys is reconciliation:
     OpenRouter's own usage report carries one line per provisioned key, so the provider's number
     and the usage-credit ledger can be joined on `provisioned_id` and compared. With one shared
     key they cannot: the provider returns a single undifferentiated total for every customer at
     once, and our meter is the only witness to its own arithmetic.

   The secret is never in this file and never on the wire to the browser. What a screen may show is
   the prefix, the provisioned id, the hash and the counters. Reading the secret happens in the
   model layer's resolver and is audited; a call that reads it from the environment is a defect. */
var ASST_ENGINE_URL="https://engine.oxagen.sh/v1";
var ASST_ENGINE_VER="0.31.4";
var ASST_MODEL="z-ai/glm-flash-latest";

var ORG_KEY={
  source:"platform_minted",
  customerPrefix:null,                /* set when an operator saves their own key */
  provisionedId:"key_01K5RW8Q2N",     /* OpenRouter's own id — what reconciliation joins on */
  label:"oxagen/a-intel",             /* the name the key carries on Oxagen's OpenRouter account */
  prefix:"sk-or-v1-a3f1",             /* the only part of the secret anything may render */
  hash:"sha256:7c41e0b9ad2f8365",
  minted:"2026-08-02",
  mintedBy:"marcus",
  rotated:null,
  capUsd:2000,
  reads30:41,
  /* what each side says this organization spent this month. They are two independent numbers: the
     first is the provider's, read off the usage report for this key; the second is ours, summed
     from the credit ledger. A screen that derives one from the other proves nothing. */
  providerUsd:"148.02",
  ledgerUsd:"148.02"
};
function orgKeyState(){
  if(ORG_KEY.source==="none") return "none";
  if(ORG_KEY.source==="customer_key") return ORG_KEY.customerPrefix?"ok":"none";
  return ORG_KEY.provisionedId?"ok":"none";
}
var ORG_KEY_SOURCES=[
 ["platform_minted","one key minted for this organization on oxagen’s OpenRouter account",
  "oxagen owns, pays, rotates and revokes it. Its tokens are billed. The provider reports it on its own line, so the bill and the ledger can be compared."],
 ["platform","oxagen’s shared account",
  "One key for every customer. Billed back at vendor cost plus a published markup. The provider returns one undifferentiated total, so our meter is the only witness to its own arithmetic."],
 ["customer_key","your own OpenRouter or vendor key",
  "You own and pay for it. Stored enveloped, tested before save, never returned, every read audited. Your tokens are reported and billed at zero."]
];
function orgKeySource(){ for(var i=0;i<ORG_KEY_SOURCES.length;i++){ if(ORG_KEY_SOURCES[i][0]===ORG_KEY.source) return ORG_KEY_SOURCES[i]; } return ORG_KEY_SOURCES[0]; }
function orgKeyDrift(){ return Math.round((n$(ORG_KEY.providerUsd)-n$(ORG_KEY.ledgerUsd))*100)/100; }

function orgKeyHeld(){ return ORG_KEY.source==="customer_key"?!!ORG_KEY.customerPrefix:!!ORG_KEY.provisionedId; }

/* Switching the source is a claim about who pays, so nothing is charged and no key is resolved
   until a key is actually held under the new source. Picking customer_key therefore leaves the
   organization without a key, and the panel says so, until one is saved. */
function orgKeySourceSet(v){
  if(ORG_KEY.source===v) return;
  ORG_KEY.source=v;
  render();
  act(v==="customer_key"&&!ORG_KEY.customerPrefix
    ? "Save your own key below. Until you do, no model call resolves and nothing is charged."
    : "Funding source set to "+v+". Recorded as a control-plane event.");
}
function orgKeySave(){
  var n=el("byokKey"), v=n?n.value.trim():"";
  if(!v){ act("Paste a key first. oxagen tests it against the provider before it saves anything."); return; }
  ORG_KEY.customerPrefix=v.slice(0,13);
  render();
  act("Tested against "+ASST_MODEL+" and saved, enveloped. Nothing was returned to this screen.","gold");
}
function orgKeyClear(){
  ORG_KEY.customerPrefix=null;
  render();
  act("Your key was removed. Model calls stop at the next request until a source is chosen.");
}

function orgKeyPanel(){
  var src=orgKeySource(), none=orgKeyState()==="none", byok=ORG_KEY.source==="customer_key",
      held=orgKeyHeld(), drift=orgKeyDrift(), minted=ORG_KEY.source==="platform_minted";
  var rows="";
  if(byok){
    rows='<dl class="kv">'+
     '<dt>Key</dt><dd>'+(held
       ?'<span class="mono">'+h(ORG_KEY.customerPrefix)+'…</span> <span class="dim">enveloped, never returned — this prefix is all any screen may show</span>'
       :'<span class="dim">none saved yet</span>')+'</dd>'+
     '<dt>Billing</dt><dd>your tokens are reported and billed at zero; governed actions are billed as usual</dd>'+
     '<dt>Key storage</dt><dd>enveloped, tested before save, never returned, every read audited</dd>'+
     '<dt>Engine</dt><dd><span class="mono">'+h(ASST_ENGINE_URL)+'</span> · stella '+h(ASST_ENGINE_VER)+' over HTTP, on this key</dd>'+
     '</dl>'+
     '<div class="field" style="margin-top:14px"><label for="byokKey">Your OpenRouter or vendor key</label>'+
     '<input id="byokKey" type="password" autocomplete="off" placeholder="sk-or-v1-…" aria-label="Your key">'+
     '<div class="hint">oxagen calls '+h(ASST_MODEL)+' with it once to check it works, then envelopes it. It is never returned to a screen and never read from the environment.</div></div>';
  } else if(none){
    rows='<div class="note">No key is held for '+h(ORG.name)+'. The in-app agent cannot run, and nothing has been charged. Minting one is a governed action and puts your name on it.</div>';
  } else {
    rows='<dl class="kv">'+
     '<dt>Secret</dt><dd><span class="mono">'+h(ORG_KEY.prefix)+'…</span> <span class="dim">enveloped, never returned — this prefix is all any screen may show</span></dd>'+
     '<dt>Provisioned id</dt><dd><span class="mono">'+h(ORG_KEY.provisionedId)+'</span> <span class="dim">the provider’s own id; reconciliation joins on it</span></dd>'+
     '<dt>Name on the account</dt><dd><span class="mono">'+h(ORG_KEY.label)+'</span></dd>'+
     '<dt>Minted</dt><dd>'+h(ORG_KEY.minted)+' by '+h(PEOPLE[ORG_KEY.mintedBy].name)+(ORG_KEY.rotated?' · rotated '+h(ORG_KEY.rotated):' · never rotated')+'</dd>'+
     '<dt>Monthly cap</dt><dd>'+usd(fmt2(ORG_KEY.capUsd))+' USD, set on the key at the provider — not only in our meter · <span id="orgCapUsed">'+usd(fmt2(orgRoutesTotal()))+'</span> used in '+h(SPEND.month)+', the total of the routes below</dd>'+
     '<dt>Reads</dt><dd>'+ORG_KEY.reads30+' in 30 days, each one an audit event</dd>'+
     '<dt>Engine</dt><dd><span class="mono">'+h(ASST_ENGINE_URL)+'</span> · stella '+h(ASST_ENGINE_VER)+' over HTTP, on this key</dd>'+
     '</dl>';
  }
  var acts=byok
   ? '<button class="btn primary" onclick="orgKeySave()">Test and save</button>'+
     (held?'<button class="btn danger" onclick="orgKeyClear()">Remove the key</button>':'')
   : (none?'<button class="btn primary" onclick="openDialog(\'mintkey\')">Mint a key for '+h(ORG.name)+'</button>'
        :'<button class="btn" onclick="openDialog(\'rotateorgkey\')">Rotate</button>'+
         '<button class="btn danger" onclick="openDialog(\'revokeorgkey\')">Revoke</button>');

  return '<div class="panel"><div class="panel-h"><h3>Funding source</h3>'+
   '<span class="sp">'+(held
     ?'<span class="b b-allowed"><span class="d"></span>'+h(ORG_KEY.source)+'</span>'
     :'<span class="b b-approval"><span class="d"></span>no key held</span>')+'</span></div>'+
   '<div class="panel-b">'+
   '<div class="field"><label for="orgFundSrc">Source</label>'+
   '<select id="orgFundSrc" onchange="orgKeySourceSet(this.value)" aria-label="Funding source">'+
    ORG_KEY_SOURCES.map(function(x){return '<option value="'+h(x[0])+'"'+(ORG_KEY.source===x[0]?' selected':'')+'>'+h(x[0])+' — '+h(x[1])+'</option>';}).join("")+
   '</select><div class="hint">'+h(src[2])+'</div></div>'+
   rows+
   '<div class="row" style="margin-top:13px">'+acts+'</div>'+
   '<div class="note" style="margin-top:13px">No call reads the environment. Keys and routes come from the model layer’s resolver, and a path that bypasses it is a defect.</div>'+
   '</div>'+
   (minted&&held?'<div class="panel-b" style="border-top:1px solid var(--border)">'+
    '<p class="eyebrow q" style="margin:0 0 8px">Reconciliation</p>'+
    '<dl class="kv">'+
    '<dt>OpenRouter reports</dt><dd><span class="mono">'+usd(ORG_KEY.providerUsd)+'</span> on <span class="mono">'+h(ORG_KEY.provisionedId)+'</span></dd>'+
    '<dt>Our credit ledger</dt><dd><span class="mono">'+usd(ORG_KEY.ledgerUsd)+'</span> debited to this organization</dd>'+
    '<dt>Difference</dt><dd>'+(drift===0
      ?'<span class="b b-allowed"><span class="d"></span>none</span>'
      :'<span class="b b-critical"><span class="d"></span>'+usd(fmt2(Math.abs(drift)))+' '+(drift>0?'unbilled':'over-billed')+'</span>')+'</dd>'+
    '</dl>'+
    '<div class="note" style="margin-top:10px">Two independent numbers, not one derived from the other: the first is read off the provider’s usage report for this key, the second is summed from our own ledger. A shared key cannot produce this row at all, which is the whole reason this organization has a key of its own.</div>'+
   '</div>':'')+
   '</div>';
}

DLG_EXT.mintkey=function(){
  return {t:"Mint a model key for "+ORG.name, s:"oxagen calls OpenRouter’s provisioning API and holds what comes back. The secret is never returned to this screen.", w:false,
   b:'<div class="field"><label>Name on the account</label><input value="oxagen/'+h(ORG.slug)+'" aria-label="Name"><div class="hint">What the key is called on oxagen’s OpenRouter account. It is how a person reading the provider’s bill finds this organization.</div></div>'+
     '<div class="field"><label>Monthly cap</label><input value="2000.00" aria-label="Monthly cap"><div class="hint">Set on the key at the provider, not only in our meter — so a bug in our metering cannot spend past it.</div></div>'+
     '<div class="field"><label>What this writes</label>'+
      '<div class="sx-cfg"><div class="sx-cfg-h">POST https://openrouter.ai/api/v1/keys</div><pre>'+
      '<span class="k">name</span>  = <span class="s">"oxagen/'+h(ORG.slug)+'"</span>\n'+
      '<span class="k">limit</span> = <span class="n">2000.00</span>            <span class="c"># USD a month, enforced by the provider</span>\n'+
      '<span class="c"># the response is stored enveloped under the organization key; what is kept in the</span>\n'+
      '<span class="c"># clear is the prefix, the provisioned id and a hash. Nothing returns the secret.</span></pre></div></div>'+
     '<div class="note">Minting is a governed action. It appears in the audit record with your name, and every later read of the key is its own audit event.</div>',
   f:'<button class="btn" onclick="closeDialog()">Cancel</button>'+
     '<button class="btn primary" onclick="closeDialog();act(\'Key minted on oxagen\\u2019s OpenRouter account as oxagen/'+h(ORG.slug)+', capped at $2,000.00 a month. The secret was enveloped and never returned; org.model_key.mint is in the audit record.\',\'gold\')">Mint the key</button>'};
};
DLG_EXT.rotateorgkey=function(){
  return {t:"Rotate this key", s:ORG_KEY.provisionedId+" · "+ORG_KEY.label, w:false,
   b:'<div class="note">Rotation provisions a new key at the provider and envelopes it, then revokes the old one once the engine has picked the new one up. Turns in flight finish on the key they started with.</div>'+
     '<dl class="kv" style="margin-top:12px"><dt>This month on the old key</dt><dd><span class="mono">'+usd(ORG_KEY.providerUsd)+'</span> — it stays on the provider’s report under <span class="mono">'+h(ORG_KEY.provisionedId)+'</span>, so the month still reconciles across both</dd></dl>',
   f:'<button class="btn" onclick="closeDialog()">Cancel</button>'+
     '<button class="btn primary" onclick="closeDialog();act(\'Rotated. The new key is enveloped and in force; the old one is revoked and keeps its line on this month\\u2019s provider report.\')">Rotate</button>'};
};
DLG_EXT.revokeorgkey=function(){
  return {t:"Revoke this key", s:ORG_KEY.provisionedId+" · "+ORG_KEY.label, w:false,
   b:'<div class="warn"><b>The in-app agent stops for everyone in '+h(ORG.name)+'.</b> Revocation ends the key at the provider at the next call. Nothing else changes: no run, no receipt and no record depends on it, and the month’s spend stays on the provider’s report.</div>'+
     '<div class="note" style="margin-top:12px">oxagen’s own work — reflection, promotion rationale, Context PR bodies, run names — routes on the tiers above and is unaffected.</div>',
   f:'<button class="btn" onclick="closeDialog()">Cancel</button>'+
     '<button class="btn danger" onclick="ORG_KEY.source=\'none\';ORG_KEY.provisionedId=null;closeDialog();act(\'Revoked at the provider. The in-app agent is unavailable in '+h(ORG.name)+' until a key is minted.\')">Revoke</button>'};
};

/* ============================== the in-app agent ==============================
   Restored 2026-09-15. The scope review of 2026-09-14 proposed cutting it, the maintainer kept it
   the same day ("dont cut the in app agent"), and the chrome removed that morning was never put
   back — see scope-review.md, the In-app agent row. Spec §4.4: it opens as a flyout from the
   sidebar, each of its turns is a run of its own, and it acts through the same agent tools a person
   clicks, so what it does passes IAM and lands in the record like an action taken on a page.

   Two things it is not. It is not a second way to get authority: it holds none and carries no
   credential, and every action it takes is the same governed action the page would have taken. And
   its runs are Oxagen's, not the tenant's — they never appear in Fleet, in the run index or in
   Spend's run counts. What they do cost is the second meter: usage credits (§12.1), against the
   organization's balance, served by the Stella engine over HTTP on the org's own model key (§4.5).

   The panel lives in #asst, a host render() never replaces. That is deliberate: a CSS transition
   cannot run on an element rebuilt from an innerHTML string, and a half-typed message cannot
   survive one either. The class is toggled on the host, and the sheet inside it is rebuilt only
   when the thing it renders actually changes. */
S.asst=false; S.asstEngine="up";

/* Stella's marks, from the house brand kit (oxagen-brand, logo/svg/stella-wordmark-adaptive.svg).
   The paths are the kit's and are never redrawn. The icon is the wordmark's own asterisk, cropped to
   its box. The letters take currentColor, so they follow this page's theme, including ?theme=. The
   asterisk is gold in both themes, as it is in the kit's light and dark wordmarks. The kit's adaptive
   file switches its ink with a prefers-color-scheme block that works only inside an <img>. Inlined,
   that block would restyle this page, so it is left out and the theme tokens do its job. */
